/* GEOS3141 review deck, used by review.html (and index.html for the due count).
   CARDS is a plain global array so the page works from file:// with no fetch.
   Each card: {id, lecture, kind, front, back} plus, for checkpoints, opts (the
   choices) and ans (the right one), and for self-test questions, lvl.
   kind: term (glossary), mc (checkpoint), q (self-test or short answer).
   Ids are what the schedule in localStorage (geos3141-srs) is keyed on, so
   don't renumber them. The block above the marker is generated from each
   lecture page by tools/build_cards.py; add extra cards below the marker. */
var CARDS = [
 /* Lecture 1: 36 terms, 11 checkpoints, 10 self-test */
 {"id": "L1-g-assay", "lecture": 1, "kind": "term", "front": "Assay", "back": "A laboratory chemical analysis that measures how much of a metal is in a sample."},
 {"id": "L1-g-bonanza", "lecture": 1, "kind": "term", "front": "Bonanza", "back": "A very high grade, usually over 100 g/t gold. It is found in some epithermal and orogenic deposits."},
 {"id": "L1-g-brownfield", "lecture": 1, "kind": "term", "front": "Brownfield", "back": "Exploration in or near an existing or historic mining area."},
 {"id": "L1-g-concentration-factor", "lecture": 1, "kind": "term", "front": "Concentration factor", "back": "Economic grade divided by average crustal abundance. It shows how many times a process must concentrate an element to make ore."},
 {"id": "L1-g-connate-water", "lecture": 1, "kind": "term", "front": "Connate water", "back": "Water trapped in sediment pores when the sediment was deposited."},
 {"id": "L1-g-critical-minerals", "lecture": 1, "kind": "term", "front": "Critical minerals", "back": "A policy term for commodities that a country thinks are essential and whose supply is at risk. Each country has a different list."},
 {"id": "L1-g-cut-off-grade", "lecture": 1, "kind": "term", "front": "Cut-off grade", "back": "The lowest grade that can be mined and processed at a profit. Rock below it is treated as waste."},
 {"id": "L1-g-diatreme", "lecture": 1, "kind": "term", "front": "Diatreme", "back": "A volcanic pipe filled with broken rock. It forms when magma or gas meets groundwater and explodes."},
 {"id": "L1-g-epigenetic", "lecture": 1, "kind": "term", "front": "Epigenetic", "back": "Ore that was added after its host rock formed, such as any vein."},
 {"id": "L1-g-exsolution", "lecture": 1, "kind": "term", "front": "Exsolution", "back": "When one phase separates from another as conditions change. For example, water forms bubbles and leaves a rising magma as the pressure drops."},
 {"id": "L1-g-gangue", "lecture": 1, "kind": "term", "front": "Gangue", "back": "Minerals that are mined together with the ore but have no value in that deposit, such as quartz, carbonates and usually pyrite. Pronounced 'gang'."},
 {"id": "L1-g-grade", "lecture": 1, "kind": "term", "front": "Grade", "back": "The amount of the valuable commodity in the ore: g/t for precious metals, wt% for base metals. Waste rock has no grade."},
 {"id": "L1-g-grade-control", "lecture": 1, "kind": "term", "front": "Grade control", "back": "Daily sampling and assaying at a working mine. It decides which blasted rock goes to the processing plant and which goes to the waste dump."},
 {"id": "L1-g-greenfield", "lecture": 1, "kind": "term", "front": "Greenfield", "back": "Exploration in an area with no known deposits or previous mining."},
 {"id": "L1-g-hydrothermal-alteration", "lecture": 1, "kind": "term", "front": "Hydrothermal alteration", "back": "Changes to a rock's minerals, texture and chemistry caused by reaction with hot fluids."},
 {"id": "L1-g-hypogene", "lecture": 1, "kind": "term", "front": "Hypogene", "back": "Formed by fluids rising from depth, usually hot hydrothermal fluids."},
 {"id": "L1-g-iocg", "lecture": 1, "kind": "term", "front": "IOCG", "back": "Iron oxide copper-gold deposit. Olympic Dam is the type example."},
 {"id": "L1-g-joint-venture", "lecture": 1, "kind": "term", "front": "Joint venture", "back": "A partnership where companies share the cost and ownership of a project. It is common when a small company asks a large company to pay for building a mine."},
 {"id": "L1-g-jorc-code", "lecture": 1, "kind": "term", "front": "JORC Code", "back": "The Australasian code for reporting exploration results, mineral resources and ore reserves. A Competent Person must approve each report."},
 {"id": "L1-g-kimberlite", "lecture": 1, "kind": "term", "front": "Kimberlite", "back": "An ultramafic rock, rich in gas and water, that erupts from deep in the mantle through narrow pipes. It is the most common host rock for diamonds."},
 {"id": "L1-g-lamproite", "lecture": 1, "kind": "term", "front": "Lamproite", "back": "A mantle-derived alkaline volcanic rock that is very rich in potassium. Like kimberlite, it can carry diamonds, for example at Argyle."},
 {"id": "L1-g-ligand", "lecture": 1, "kind": "term", "front": "Ligand", "back": "An ion or molecule (such as Cl⁻ or HS⁻) that bonds to a metal in solution. This allows the fluid to carry the metal."},
 {"id": "L1-g-metallotect", "lecture": 1, "kind": "term", "front": "Metallotect", "back": "Any geological, tectonic, rock-type or geochemical feature that helped to concentrate one or more elements."},
 {"id": "L1-g-metasomatism", "lecture": 1, "kind": "term", "front": "Metasomatism", "back": "A change in a rock's chemical composition when fluids flow through it and add or remove elements (an open system)."},
 {"id": "L1-g-meteoric-water", "lecture": 1, "kind": "term", "front": "Meteoric water", "back": "Water that fell as rain or snow and entered the ground as groundwater."},
 {"id": "L1-g-mineral-resource", "lecture": 1, "kind": "term", "front": "Mineral resource", "back": "An estimate of tonnage and grade in the ground that could reasonably be mined one day. It is inferred, indicated or measured."},
 {"id": "L1-g-modifying-factors", "lecture": 1, "kind": "term", "front": "Modifying factors", "back": "Mining, metallurgical, economic, marketing, legal, environmental, social and government factors. They are used to turn resources into reserves."},
 {"id": "L1-g-ore-mineral", "lecture": 1, "kind": "term", "front": "Ore mineral", "back": "A mineral that you sell. Which minerals count as ore minerals depends on the deposit and the market."},
 {"id": "L1-g-ore-reserve", "lecture": 1, "kind": "term", "front": "Ore reserve", "back": "The part of a measured or indicated resource that has been shown to be profitable to mine after the modifying factors are applied. It is probable or proved."},
 {"id": "L1-g-porphyry", "lecture": 1, "kind": "term", "front": "Porphyry", "back": "A large, low-grade copper (gold, molybdenum) deposit. It forms from fluids released by an oxidised intrusion in a volcanic arc."},
 {"id": "L1-g-ppm-and-ppb", "lecture": 1, "kind": "term", "front": "Ppm and ppb", "back": "Parts per million and per billion by mass. 1 ppm = 1 g/t = 1000 ppb; 1% = 10 000 ppm."},
 {"id": "L1-g-regolith", "lecture": 1, "kind": "term", "front": "Regolith", "back": "The layer of weathered rock, soil and transported sediment that covers fresh bedrock. In much of Australia it is tens of metres to over 100 m thick."},
 {"id": "L1-g-supergene", "lecture": 1, "kind": "term", "front": "Supergene", "back": "Formed by surface water moving down during weathering. The water dissolves metals near the surface and deposits them again lower down."},
 {"id": "L1-g-syngenetic", "lecture": 1, "kind": "term", "front": "Syngenetic", "back": "Ore that formed at the same time as its host rock, such as a seafloor massive sulphide layer or a placer."},
 {"id": "L1-g-tonnage", "lecture": 1, "kind": "term", "front": "Tonnage", "back": "The mass of ore in a deposit, usually in millions of tonnes (Mt)."},
 {"id": "L1-g-top-cut", "lecture": 1, "kind": "term", "front": "Top cut", "back": "Reducing very high assays to a set maximum value during resource estimation, so that a few extreme results do not make the overall grade too high."},
 {"id": "L1-cp1", "lecture": 1, "kind": "mc", "front": "The copper price falls by half in one day. What happens to the copper ore at a mine?", "opts": ["Nothing. The rocks have not changed.", "Some of it becomes waste because the cut-off grade rises.", "The grade of every block falls."], "ans": "Some of it becomes waste because the cut-off grade rises.", "back": "Ore depends on profit. A lower price means a higher cut-off grade, so the lower-grade blocks become waste. The grades themselves do not change."},
 {"id": "L1-cp2", "lecture": 1, "kind": "mc", "front": "1 g/t is the same as...", "opts": ["1 ppm", "1 ppb", "0.1%"], "ans": "1 ppm", "back": "A tonne is a million grams, so 1 g in a tonne is one part per million. 0.1% would be 1000 ppm."},
 {"id": "L1-cp3", "lecture": 1, "kind": "mc", "front": "A deposit is 20 Mt at 2.5 g/t Au. Roughly how much gold does it contain?", "opts": ["About 50 000 oz", "About 1.6 million oz", "About 50 million oz"], "ans": "About 1.6 million oz", "back": "20 000 000 t × 2.5 g/t = 50 000 000 g. Divide by 31.1 g/oz to get about 1.6 million ounces."},
 {"id": "L1-cp4", "lecture": 1, "kind": "mc", "front": "Which of these can be changed directly into an ore reserve?", "opts": ["An inferred resource", "An indicated resource", "Exploration results"], "ans": "An indicated resource", "back": "Indicated changes to probable, and measured changes to proved or probable. Inferred never changes directly."},
 {"id": "L1-cp5", "lecture": 1, "kind": "mc", "front": "A galena-sphalerite vein with chalcedony bands and no chalcopyrite cuts across bedding. What is the best label?", "opts": ["Syngenetic and hypothermal", "Epigenetic and epithermal", "Syngenetic and epithermal"], "ans": "Epigenetic and epithermal", "back": "It cuts across bedding, so it is epigenetic. Low-temperature minerals and no chalcopyrite point to the shallow, cool epithermal zone."},
 {"id": "L1-cp6", "lecture": 1, "kind": "mc", "front": "Your company wants a SEDEX zinc deposit. Where do you look first?", "opts": ["A continental arc above a subduction zone", "A rifted continental margin or rift basin", "The middle of a stable craton without basins"], "ans": "A rifted continental margin or rift basin", "back": "SEDEX forms where basin brines rise up growth faults in rifted margins and in rifts within continents. It does not form in arcs."},
 {"id": "L1-cp7", "lecture": 1, "kind": "mc", "front": "In one sentence, what is an ore deposit?", "opts": ["Any rock that contains metal", "An unusually high concentration of elements that are normally spread thinly through the crust", "Any rock that formed from magma"], "ans": "An unusually high concentration of elements that are normally spread thinly through the crust", "back": "All the other ideas in this lecture follow from this: when it counts as ore, how much concentration is needed, and which processes do it."},
 {"id": "L1-cp8", "lecture": 1, "kind": "mc", "front": "An alkaline syenite with carbonatite dykes is most likely to host...", "opts": ["chromite and platinum group elements", "porphyry copper-gold", "rare earths and phosphate"], "ans": "rare earths and phosphate", "back": "Small amounts of mantle melting concentrate incompatible elements. Tholeiites give Cr-Ni-PGE. Wet, oxidised calc-alkaline magmas give porphyries."},
 {"id": "L1-cp9", "lecture": 1, "kind": "mc", "front": "Hydrothermal fluid flows through a permeable fault zone for a long time. But nothing cools it, boils it, mixes with it or reacts with it. Which link is missing?", "opts": ["A metal source", "A trap: something that makes the fluid deposit its metal", "A pathway"], "ans": "A trap: something that makes the fluid deposit its metal", "back": "Fluids are usually undersaturated. They only deposit metal when cooling, boiling, mixing or reaction with rock changes them quickly."},
 {"id": "L1-cp10", "lecture": 1, "kind": "mc", "front": "Why was the Argyle diamond deposit not properly followed up at first?", "opts": ["It was too deep to drill", "The model in use said economic diamonds only occur in kimberlite, but Argyle is hosted by lamproite", "Its diamonds were too small to see"], "ans": "The model in use said economic diamonds only occur in kimberlite, but Argyle is hosted by lamproite", "back": "Use a model as a tool to find the next deposit, not as a strict definition."},
 {"id": "L1-cp11", "lecture": 1, "kind": "mc", "front": "The ore suites are worth 50 per cent. What do they depend on most?", "opts": ["Describing ore and gangue minerals, textures and the likely setting, using the words from this lecture", "Spreadsheet economics", "Seminar slides"], "ans": "Describing ore and gangue minerals, textures and the likely setting, using the words from this lecture", "back": "Your first ore suite page is not marked, but you get feedback on it. So do it carefully, and then improve it."},
 {"id": "L1-st1", "lecture": 1, "kind": "q", "lvl": "Recall", "front": "A copper deposit has not changed since last year, but the company no longer calls part of it ore. How is this possible?", "back": "Ore depends on whether it can be mined at a profit. If the copper price fell or costs rose, the cut-off grade went up. Then the lower-grade parts are no longer profitable, so they are reclassified as waste. The rocks are the same; only the economics changed."},
 {"id": "L1-st2", "lecture": 1, "kind": "q", "lvl": "Recall", "front": "Why is pyrite gangue at most deposits but ore at Mount Isa?", "back": "Pyrite is only ore if someone pays for it. Phosphate Hill, south of Mount Isa, needs sulphuric acid to process phosphate, and pyrite (FeS₂) can be used to make that acid. In other places pyrite has no value and causes problems, because it makes acid mine drainage."},
 {"id": "L1-st3", "lecture": 1, "kind": "q", "lvl": "Calculate", "front": "Calculate the concentration factor for copper if average crust is 55 ppm and the economic grade is 1%.", "back": "1% is 10 000 ppm. 10 000 ÷ 55 ≈ 180, so copper must be concentrated about 180 times."},
 {"id": "L1-st4", "lecture": 1, "kind": "q", "lvl": "Think", "front": "Zinc needs a bigger concentration factor than nickel, but zinc deposits are more common. Does this disagree with the idea of concentration factors?", "back": "No. The factor shows how much concentration is needed, not how often it happens. Zinc moves easily in low-temperature salty basin fluids, and these fluids are common. Nickel sulphide ore needs a sulphide liquid to separate from a hot ultramafic magma, and this is much rarer."},
 {"id": "L1-st5", "lecture": 1, "kind": "q", "lvl": "Recall", "front": "Why do companies sample every metre of half core, even parts with no visible mineralisation?", "back": "Grade is an average over the whole interval. If you only sampled the parts that look mineralised, the average would be too high. Also, in many gold deposits you cannot see the gold anyway."},
 {"id": "L1-st6", "lecture": 1, "kind": "q", "lvl": "Think", "front": "A company reports a large inferred resource and says it will \"start mining soon\". Why should you doubt this?", "back": "Inferred is the lowest level of confidence, and it cannot become a reserve directly. Mining needs indicated or measured resources, plus studies that show the modifying factors are met. This usually takes years."},
 {"id": "L1-st7", "lecture": 1, "kind": "q", "lvl": "Apply", "front": "A quartz vein full of chalcopyrite cuts bedding in a sandstone. Is it syngenetic or epigenetic? Is it likely to be epithermal?", "back": "Epigenetic, because it cuts bedding. Probably not epithermal: a lot of chalcopyrite suggests more than about 200 °C. This points to mesothermal or deeper conditions, or a porphyry-related setting."},
 {"id": "L1-st8", "lecture": 1, "kind": "q", "lvl": "Apply", "front": "You are exploring for primary REE in a region with a tholeiitic gabbro, a calc-alkaline granodiorite and an alkaline syenite with carbonatite dykes. Where do you start?", "back": "The alkaline syenite and carbonatite. REE are incompatible elements. They are concentrated by small amounts of mantle melting, and this is exactly what produces alkaline magmas and carbonatites."},
 {"id": "L1-st9", "lecture": 1, "kind": "q", "lvl": "Think", "front": "Why is an alteration halo usually a better exploration target than the ore body itself?", "back": "The fluid reacted with a much larger volume of rock than the ore. So the halo can be 10 to 100 times bigger or more, and easier to detect. Zones within the halo then help you move towards the ore."},
 {"id": "L1-st10", "lecture": 1, "kind": "q", "lvl": "Synthesise", "front": "Give two different reasons why a region with lots of hot fluid flow might have no deposit.", "back": "Any broken link is correct. No trap, so the metals stayed dissolved and spread out. No focusing structure, so the metal spread thinly through a huge volume of rock. Or a deposit formed but was later eroded, so it was not preserved."},
 /* Lecture 2: 40 terms, 12 checkpoints, 10 self-test */
 {"id": "L2-g-acid-mine-drainage", "lecture": 2, "kind": "term", "front": "Acid mine drainage", "back": "Acidic water with dissolved metals. It forms when pyrite and other sulphides oxidise. Each mole of pyrite releases four moles of H⁺."},
 {"id": "L2-g-advanced-argillic", "lecture": 2, "kind": "term", "front": "Advanced argillic", "back": "Very acidic alteration: quartz, alunite, pyrophyllite, dickite, diaspore, opaline silica."},
 {"id": "L2-g-alteration", "lecture": 2, "kind": "term", "front": "Alteration", "back": "A change in a rock's minerals at low pressure, caused by fluids moving through the rock, or by oxygen."},
 {"id": "L2-g-alteration-index", "lecture": 2, "kind": "term", "front": "Alteration index", "back": "AI = 100(K₂O+MgO)/(K₂O+MgO+Na₂O+CaO). Higher means more altered."},
 {"id": "L2-g-argillic", "lecture": 2, "kind": "term", "front": "Argillic", "back": "Clay alteration: kaolinite, dickite, illite, montmorillonite."},
 {"id": "L2-g-bauxite", "lecture": 2, "kind": "term", "front": "Bauxite", "back": "Aluminium ore formed by strong tropical weathering. It is mostly gibbsite."},
 {"id": "L2-g-bleaching", "lecture": 2, "kind": "term", "front": "Bleaching", "back": "Loss of colour when iron and other colouring elements are removed. The pale rock that is left is richer in Si and Al."},
 {"id": "L2-g-boxwork", "lecture": 2, "kind": "term", "front": "Boxwork", "back": "A gossan texture where goethite fills the spaces left by dissolved sulphide crystals. The spaces keep the shapes of the crystals."},
 {"id": "L2-g-ccpi", "lecture": 2, "kind": "term", "front": "CCPI", "back": "Chlorite-carbonate-pyrite index = 100(MgO+FeO)/(MgO+FeO+Na₂O+K₂O)."},
 {"id": "L2-g-chalcocite", "lecture": 2, "kind": "term", "front": "Chalcocite", "back": "Cu₂S, about 80% copper. The classic supergene enrichment mineral."},
 {"id": "L2-g-cryptic-alteration", "lecture": 2, "kind": "term", "front": "Cryptic alteration", "back": "Alteration that you can only detect with chemistry or isotopes. There is no visible change in the minerals."},
 {"id": "L2-g-footwall", "lecture": 2, "kind": "term", "front": "Footwall", "back": "The rock below an orebody. In VMS systems, most of the alteration is in the footwall."},
 {"id": "L2-g-gibbsite", "lecture": 2, "kind": "term", "front": "Gibbsite", "back": "Aluminium hydroxide, Al(OH)₃, the main mineral in bauxite."},
 {"id": "L2-g-goethite", "lecture": 2, "kind": "term", "front": "Goethite", "back": "Iron oxyhydroxide, FeO(OH). Brown-orange. It contains hydrogen, so it shows where water collected, for example at a water table."},
 {"id": "L2-g-gossan", "lecture": 2, "kind": "term", "front": "Gossan", "back": "The oxidised, iron-rich cap on top of a sulphide body, mostly goethite and hematite. There may or may not be ore below it."},
 {"id": "L2-g-heap-leaching", "lecture": 2, "kind": "term", "front": "Heap leaching", "back": "Ore is crushed and piled on a pad. Acid flows through the pile and dissolves the metal, and the metal is recovered from the solution."},
 {"id": "L2-g-hematite", "lecture": 2, "kind": "term", "front": "Hematite", "back": "Iron oxide, Fe₂O₃. Red. General rule: it forms where water flows and there is plenty of oxygen."},
 {"id": "L2-g-immobile-elements", "lecture": 2, "kind": "term", "front": "Immobile elements", "back": "Elements that do not move during weathering and alteration: Si (mostly), Al, Ti, Zr, Y, Cr. They are used to identify the original rock."},
 {"id": "L2-g-jarosite", "lecture": 2, "kind": "term", "front": "Jarosite", "back": "A group of potassium iron sulphate minerals that form when sulphides weather in acidic conditions."},
 {"id": "L2-g-kaolinite", "lecture": 2, "kind": "term", "front": "Kaolinite", "back": "The most common clay formed when feldspar weathers. Also called kaolin."},
 {"id": "L2-g-karst", "lecture": 2, "kind": "term", "front": "Karst", "back": "A landscape of caves and sinkholes formed when limestone dissolves."},
 {"id": "L2-g-laterite", "lecture": 2, "kind": "term", "front": "Laterite", "back": "A deeply weathered profile, rich in iron and aluminium, that forms in hot, wet tropical conditions."},
 {"id": "L2-g-leached-zone", "lecture": 2, "kind": "term", "front": "Leached zone", "back": "The part of a weathered profile where metals have been dissolved and removed."},
 {"id": "L2-g-mobile-elements", "lecture": 2, "kind": "term", "front": "Mobile elements", "back": "Elements that water or hydrothermal fluid easily dissolves and removes: Na, K, Ca, Mg, Fe, Sr and many metals."},
 {"id": "L2-g-oxidation", "lecture": 2, "kind": "term", "front": "Oxidation", "back": "Loss of electrons. In ore deposits, it means sulphides and carbonates change to oxides and hydroxides when water with oxygen reaches them."},
 {"id": "L2-g-oxide-zone", "lecture": 2, "kind": "term", "front": "Oxide zone", "back": "The zone above the water table where metals are in oxide, carbonate and silicate minerals, such as malachite and azurite."},
 {"id": "L2-g-pearce-element-ratios", "lecture": 2, "kind": "term", "front": "Pearce element ratios", "back": "Molar ratios of mobile elements divided by an element that does not move (usually Al). They show what mass was gained or lost."},
 {"id": "L2-g-phyllic", "lecture": 2, "kind": "term", "front": "Phyllic", "back": "Alteration to quartz, sericite (fine muscovite) and pyrite; also called sericitic."},
 {"id": "L2-g-potassic", "lecture": 2, "kind": "term", "front": "Potassic", "back": "Alteration that adds potassium: K-feldspar, biotite, quartz, often magnetite. It is the hot core of porphyries."},
 {"id": "L2-g-propylitic", "lecture": 2, "kind": "term", "front": "Propylitic", "back": "Green alteration far from the centre (distal): chlorite, epidote, albite, carbonate, pyrite."},
 {"id": "L2-g-protolith", "lecture": 2, "kind": "term", "front": "Protolith", "back": "The original rock before weathering, alteration or metamorphism."},
 {"id": "L2-g-pxrf", "lecture": 2, "kind": "term", "front": "PXRF", "back": "Portable X-ray fluorescence. Very good for Cu, Pb and Zn; poor for REE; weak for Ag; useless for Au."},
 {"id": "L2-g-reduction", "lecture": 2, "kind": "term", "front": "Reduction", "back": "Gain of electrons. Sulphides form and stay stable in reduced conditions, below the water table."},
 {"id": "L2-g-residual-enrichment", "lecture": 2, "kind": "term", "front": "Residual enrichment", "back": "When an element becomes more concentrated only because other components around it were removed."},
 {"id": "L2-g-sericite", "lecture": 2, "kind": "term", "front": "Sericite", "back": "Not a mineral: a field term for fine-grained white mica (muscovite) with quartz."},
 {"id": "L2-g-supergene-enrichment", "lecture": 2, "kind": "term", "front": "Supergene enrichment", "back": "Metals dissolved from above are deposited again at the water table, where conditions change from oxidising to reducing."},
 {"id": "L2-g-vector", "lecture": 2, "kind": "term", "front": "Vector", "back": "Any measurable change (in minerals, chemistry or isotopes) that shows the direction towards ore."},
 {"id": "L2-g-water-table", "lecture": 2, "kind": "term", "front": "Water table", "back": "The top of the groundwater-saturated zone; the boundary between oxidising and reducing conditions."},
 {"id": "L2-g-weathering", "lecture": 2, "kind": "term", "front": "Weathering", "back": "Physical and chemical breakdown of rock at or near the Earth's surface, usually within a few tens of metres."},
 {"id": "L2-g-xrd", "lecture": 2, "kind": "term", "front": "XRD", "back": "X-ray diffraction. It identifies minerals from their crystal structure, especially fine-grained clays and micas."},
 {"id": "L2-cp1", "lecture": 2, "kind": "mc", "front": "If all other conditions are the same, which rock weathers fastest?", "opts": ["A fine-grained quartzite", "A coarse-grained limestone", "A fine-grained quartz sandstone"], "ans": "A coarse-grained limestone", "back": "Calcite is soluble, and water can enter along the long boundaries of coarse grains. Quartz hardly reacts at all."},
 {"id": "L2-cp2", "lecture": 2, "kind": "mc", "front": "You find goethite, not hematite, in an oxidised zone. What is the best interpretation?", "opts": ["Water collected there, probably at an old water table", "It was extremely dry", "The rock was never oxidised"], "ans": "Water collected there, probably at an old water table", "back": "Goethite contains hydrogen, so it needs water that stays in one place. Hematite shows flowing water and free oxygen."},
 {"id": "L2-cp3", "lecture": 2, "kind": "mc", "front": "A company drills a huge gossan in central NSW. The sulphides below it are only massive pyrite with no valuable metals. What went wrong?", "opts": ["The drill missed the water table", "Nothing: gossans often form over barren pyrite or pyrrhotite", "Gold was eroded from the gossan"], "ans": "Nothing: gossans often form over barren pyrite or pyrrhotite", "back": "A gossan only tells you that sulphides were there. Many large gossans are goethite that replaced barren iron sulphides. Assays and boxwork textures tell you whether it is worth exploring."},
 {"id": "L2-cp4", "lecture": 2, "kind": "mc", "front": "In a weathered copper deposit, where is copper usually most concentrated?", "opts": ["The leached zone", "The supergene blanket at the water table", "The gossan at the surface"], "ans": "The supergene blanket at the water table", "back": "The water table is the boundary between oxidation and reduction. Copper dissolved from above is deposited again there as chalcocite, covellite and bornite."},
 {"id": "L2-cp5", "lecture": 2, "kind": "mc", "front": "You drill through fresh chalcopyrite at 80 m, then reach native copper at 108 m. What is the most likely cause?", "opts": ["A second, deeper oxide zone along a fault", "The rock became hotter with depth", "A mistake caused by contamination during drilling"], "ans": "A second, deeper oxide zone along a fault", "back": "Water with oxygen that flows down a fault can oxidise rock far below the normal oxide zone, as at Drake and Tsumeb."},
 {"id": "L2-cp6", "lecture": 2, "kind": "mc", "front": "A quartz-sericite rock contains 10% pyrite. This pyrite is probably...", "opts": ["The ore, so drill it out", "Part of the phyllic pyrite shell, not necessarily ore", "A weathering product"], "ans": "Part of the phyllic pyrite shell, not necessarily ore", "back": "Around porphyries, phyllic alteration has a pyrite shell with about 10% pyrite and no copper. The ore shell is further inwards."},
 {"id": "L2-cp7", "lecture": 2, "kind": "mc", "front": "A sample has AI 88 and CCPI 94, with only 0.1% Na2O. What does this suggest?", "opts": ["Fresh basalt", "Intense chlorite-pyrite alteration close to ore", "Weak propylitic alteration far from the ore"], "ans": "Intense chlorite-pyrite alteration close to ore", "back": "High AI and CCPI with the sodium removed is exactly the pattern of the Cowley Hills ore zone."},
 {"id": "L2-cp8", "lecture": 2, "kind": "mc", "front": "Why can alteration not guide you to most hydrothermal vein deposits from far away?", "opts": ["Veins never have alteration", "The alteration is narrow, usually under a metre wide", "Veins are always too deep"], "ans": "The alteration is narrow, usually under a metre wide", "back": "Vein deposits usually have narrow bleached zones, from a few centimetres to one metre wide. So there is no large halo to follow."},
 {"id": "L2-cp9", "lecture": 2, "kind": "mc", "front": "Which of the three processes can happen kilometres below the surface, wherever fluids go?", "opts": ["Weathering", "Oxidation", "Alteration"], "ans": "Alteration", "back": "Weathering and oxidation work from the top down and stop near the water table, unless a structure lets water with oxygen go deeper."},
 {"id": "L2-cp10", "lecture": 2, "kind": "mc", "front": "Why do all the minerals in the weathered-rock table survive?", "opts": ["They are end products, so they do not break down any further", "They all formed at high temperature", "They are all sulphides"], "ans": "They are end products, so they do not break down any further", "back": "Quartz, kaolinite, hematite, goethite, gibbsite, anatase: these are what is left after everything mobile has gone."},
 {"id": "L2-cp11", "lecture": 2, "kind": "mc", "front": "Why is alteration the most commonly used vector to ore?", "opts": ["It is always ore grade", "The halo is much bigger than the ore, up to about two kilometres around a porphyry", "It is easy to date"], "ans": "The halo is much bigger than the ore, up to about two kilometres around a porphyry", "back": "A bigger target is easier to find, and its zones point inwards to the ore."},
 {"id": "L2-cp12", "lecture": 2, "kind": "mc", "front": "In a porphyry district, why should you not only look for the porphyry itself?", "opts": ["Porphyries never carry copper", "Distal Cu-Pb-Zn-Ag-Au veins are found out in the propylitic zone", "The potassic core is always the richest ore"], "ans": "Distal Cu-Pb-Zn-Ag-Au veins are found out in the propylitic zone", "back": "The propylitic halo is wide, and it can contain its own veins that are worth mining."},
 {"id": "L2-st1", "lecture": 2, "kind": "q", "lvl": "Recall", "front": "Why does chemical weathering make dark rocks pale?", "back": "It removes iron, the main colouring element, together with other mobile elements. The rock that is left is richer in silicon and aluminium, which form pale minerals like kaolinite and quartz. This is bleaching."},
 {"id": "L2-st2", "lecture": 2, "kind": "q", "lvl": "Calculate", "front": "A basalt with 15 wt% Al2O3 loses half its mass during weathering, but keeps all its aluminium. What is the new Al2O3 grade?", "back": "The 15 g of Al2O3 is now in 50 g of rock, so the grade is 30 wt%. This is a concentration factor of 2, only from removing other elements."},
 {"id": "L2-st3", "lecture": 2, "kind": "q", "lvl": "Recall", "front": "Give three reasons why weathered rock matters to a mining company: one good reason and two bad reasons.", "back": "Good: it can form ore (bauxite, supergene enrichment, oxide zones), and gossans can show where ore is. Bad: it hides the geology below; it usually contains nothing valuable and must be removed before open-cut mining; and it is weak, which causes engineering problems."},
 {"id": "L2-st4", "lecture": 2, "kind": "q", "lvl": "Apply", "front": "Write the total effect of oxidising one mole of pyrite in terms of acid. Explain why carbonate host rocks reduce the problem.", "back": "Each mole of FeS2 releases four moles of H⁺, plus iron hydroxide. Carbonate minerals react with H⁺ and neutralise it, so carbonate-rich rock buffers the acid. Quartz-rich rock cannot."},
 {"id": "L2-st5", "lecture": 2, "kind": "q", "lvl": "Think", "front": "Explain why the supergene blanket forms exactly at the water table.", "back": "Above the water table, water with oxygen dissolves copper from sulphides. Below it, conditions are reducing. When the water with copper reaches the reducing zone, the copper is deposited again as Cu-rich sulphides like chalcocite. The water table is this redox boundary."},
 {"id": "L2-st6", "lecture": 2, "kind": "q", "lvl": "Recall", "front": "Why might a mine put native copper in a stockpile instead of sending it to the crusher?", "back": "Native copper is soft and malleable. It does not break in the crusher; instead it spreads out and blocks it. It also uses up acid in heap leaching. Mines often stockpile it and mix it slowly with lower-grade ore."},
 {"id": "L2-st7", "lecture": 2, "kind": "q", "lvl": "Apply", "front": "A porphyry explorer finds green rock with 2% pyrite, and then pale rock with 10% pyrite. Which way should they go next, and what do they hope to find?", "back": "Continue in the same direction (from propylitic to phyllic), but carefully. Just inside the phyllic pyrite shell is the ore shell with 1 to 3% chalcopyrite. If you go too far, you reach the potassic, low-grade core."},
 {"id": "L2-st8", "lecture": 2, "kind": "q", "lvl": "Recall", "front": "In a VMS footwall, how does chlorite change as you get closer to the ore? How could you see this in core?", "back": "It changes from magnesium-rich (almost colourless) far away to iron-rich (dark green) near the ore and feeder zone. You can see the colour change in hand specimen."},
 {"id": "L2-st9", "lecture": 2, "kind": "q", "lvl": "Think", "front": "Why do you divide strontium by titanium instead of using Sr alone?", "back": "Titanium is immobile, so it stays constant during alteration. Dividing by titanium removes the effect of changes in rock type or mass. So a falling Sr/Ti really means that fluid removed strontium, not that you drilled into a different rock."},
 {"id": "L2-st10", "lecture": 2, "kind": "q", "lvl": "Apply", "front": "Your pXRF shows no gold in a gossan sample with visible gold. What happened?", "back": "The gossan is fine. pXRF cannot measure gold. When gold is the target, send samples to a laboratory for proper assay (fire assay)."},
 /* Lecture 3: 37 terms, 13 checkpoints, 10 self-test */
 {"id": "L3-g-breccia", "lecture": 3, "kind": "term", "front": "Breccia", "back": "Broken rock: angular fragments (clasts) in a finer-grained matrix or cement."},
 {"id": "L3-g-cement", "lecture": 3, "kind": "term", "front": "Cement", "back": "Minerals deposited from fluid in the spaces between clasts. They hold the clasts together."},
 {"id": "L3-g-chaotic-breccia", "lecture": 3, "kind": "term", "front": "Chaotic breccia", "back": "A fault breccia with strongly rotated clasts that no longer fit together; 30 to 60% large clasts."},
 {"id": "L3-g-chert-breccia", "lecture": 3, "kind": "term", "front": "Chert breccia", "back": "A breccia where both the clasts and the matrix are microcrystalline quartz. It forms when quartz replaces carbonate during diagenesis."},
 {"id": "L3-g-clast", "lecture": 3, "kind": "term", "front": "Clast", "back": "A fragment of rock or mineral within a breccia or sediment."},
 {"id": "L3-g-comb-quartz", "lecture": 3, "kind": "term", "front": "Comb quartz", "back": "Quartz crystals that grew from the vein walls into open space, with crystal points facing inwards."},
 {"id": "L3-g-crack-seal", "lecture": 3, "kind": "term", "front": "Crack-seal", "back": "A vein that cracked and sealed many times, building many thin layers."},
 {"id": "L3-g-crackle-breccia", "lecture": 3, "kind": "term", "front": "Crackle breccia", "back": "A fault breccia with very little clast rotation; 75 to 100% large clasts."},
 {"id": "L3-g-disseminated-ore", "lecture": 3, "kind": "term", "front": "Disseminated ore", "back": "Ore with less than 10% ore minerals, scattered through the host rock."},
 {"id": "L3-g-durchbewegung", "lecture": 3, "kind": "term", "front": "Durchbewegung", "back": "A texture of rigid, rotated clasts in a ductile sulphide matrix. It forms when sulphide ore is deformed."},
 {"id": "L3-g-effective-stress", "lecture": 3, "kind": "term", "front": "Effective stress", "back": "Confining stress minus fluid pressure. When it is close to zero, rock breaks easily."},
 {"id": "L3-g-epiclastic", "lecture": 3, "kind": "term", "front": "Epiclastic", "back": "Volcanic fragments moved by water or gravity, such as lahars and debris flows."},
 {"id": "L3-g-extensional-vein", "lecture": 3, "kind": "term", "front": "Extensional vein", "back": "A planar vein formed when rock simply pulls apart. The crystals grow at right angles to the walls."},
 {"id": "L3-g-ginguro", "lecture": 3, "kind": "term", "front": "Ginguro", "back": "A Japanese term for layered epithermal veins with black sulphide bands that are rich in gold and silver."},
 {"id": "L3-g-hyaloclastite", "lecture": 3, "kind": "term", "front": "Hyaloclastite", "back": "A glassy breccia that forms when lava cools very quickly in water and breaks."},
 {"id": "L3-g-hydrofracturing", "lecture": 3, "kind": "term", "front": "Hydrofracturing", "back": "Fracturing that happens when the fluid pressure is greater than the confining stress plus the rock's tensile strength."},
 {"id": "L3-g-jig-saw-breccia", "lecture": 3, "kind": "term", "front": "Jig-saw breccia", "back": "A breccia formed by dilation with almost no rotation, so the clasts fit back together."},
 {"id": "L3-g-magmatic-breccia", "lecture": 3, "kind": "term", "front": "Magmatic breccia", "back": "A breccia that forms when a crystallising magma, which is still plastic, breaks. Often caused by gases and water separating from the magma."},
 {"id": "L3-g-massive-ore", "lecture": 3, "kind": "term", "front": "Massive ore", "back": "Ore with more than 50% ore minerals."},
 {"id": "L3-g-matrix", "lecture": 3, "kind": "term", "front": "Matrix", "back": "The finer-grained material between clasts. It can be broken material (rock flour) or crystals."},
 {"id": "L3-g-mosaic-breccia", "lecture": 3, "kind": "term", "front": "Mosaic breccia", "back": "A fault breccia with more separation and rotation; 60 to 75% large clasts."},
 {"id": "L3-g-mvt", "lecture": 3, "kind": "term", "front": "MVT", "back": "Mississippi Valley type: lead-zinc deposits hosted in carbonate rocks, often in solution-collapse breccias."},
 {"id": "L3-g-net-textured", "lecture": 3, "kind": "term", "front": "Net-textured", "back": "Sulphide that forms a connected network between silicate grains. Typical of magmatic nickel ores."},
 {"id": "L3-g-peperite", "lecture": 3, "kind": "term", "front": "Peperite", "back": "A breccia of magma mixed with the wet, soft sediment that it intruded."},
 {"id": "L3-g-phreatic-breccia", "lecture": 3, "kind": "term", "front": "Phreatic breccia", "back": "A breccia formed by steam explosions when magma heats groundwater. Most clasts are country rock."},
 {"id": "L3-g-pseudotachylite", "lecture": 3, "kind": "term", "front": "Pseudotachylite", "back": "Glassy rock formed by almost instant melting from friction or shock, as in impact structures. The name means 'false glass'."},
 {"id": "L3-g-remobilisation", "lecture": 3, "kind": "term", "front": "Remobilisation", "back": "Physical and chemical movement and recrystallisation of ore minerals during metamorphism and deformation."},
 {"id": "L3-g-rip-up-clasts", "lecture": 3, "kind": "term", "front": "Rip-up clasts", "back": "Pieces of partly hardened sediment that a later current tore up and deposited in a younger layer."},
 {"id": "L3-g-rock-flour", "lecture": 3, "kind": "term", "front": "Rock flour", "back": "Rock ground to a fine powder by fault movement or by explosive release of fluid."},
 {"id": "L3-g-semi-massive-ore", "lecture": 3, "kind": "term", "front": "Semi-massive ore", "back": "Ore with 10 to 50% ore minerals."},
 {"id": "L3-g-skarn", "lecture": 3, "kind": "term", "front": "Skarn", "back": "A calc-silicate rock (garnet, pyroxene, wollastonite) formed when hot fluids react with rock that contains carbonate."},
 {"id": "L3-g-slickenlines", "lecture": 3, "kind": "term", "front": "Slickenlines", "back": "Lines on a fault surface that show the direction of movement."},
 {"id": "L3-g-solution-collapse-breccia", "lecture": 3, "kind": "term", "front": "Solution-collapse breccia", "back": "A breccia that forms when the rock above collapses into a space left by dissolved evaporite or carbonate. Many MVT deposits are in these breccias."},
 {"id": "L3-g-space-fill-vein", "lecture": 3, "kind": "term", "front": "Space-fill vein", "back": "A zoned vein that only partly filled at first, so open space was left for later minerals."},
 {"id": "L3-g-stockwork", "lecture": 3, "kind": "term", "front": "Stockwork", "back": "A network of many crossing and nearly parallel veins in a small volume of rock."},
 {"id": "L3-g-syngenetic", "lecture": 3, "kind": "term", "front": "Syngenetic", "back": "Formed at the same time as the host rock, as in banded SEDEX and VMS ores."},
 {"id": "L3-g-vein", "lecture": 3, "kind": "term", "front": "Vein", "back": "A fracture that opened (dilated) and filled with minerals."},
 {"id": "L3-cp1", "lecture": 3, "kind": "mc", "front": "A carbonate-evaporite sequence has V-shaped sags, a pipe of broken rock with beds dipping inwards, and a sharp, flat base. Which breccia is it?", "opts": ["Solution-collapse", "Impact", "Phreatic"], "ans": "Solution-collapse", "back": "All three features show collapse into a space left by dissolved evaporite or carbonate."},
 {"id": "L3-cp2", "lecture": 3, "kind": "mc", "front": "A fault breccia is 65% large clasts with some rotation, but you can still roughly fit pieces together. Classify it.", "opts": ["Crackle", "Mosaic", "Chaotic"], "ans": "Mosaic", "back": "Mosaic breccias are 60 to 75% large clasts with moderate rotation."},
 {"id": "L3-cp3", "lecture": 3, "kind": "mc", "front": "Rounded host-rock clasts are in a sulphide matrix that was also a melt. Which breccia type is it?", "opts": ["Hydrothermal", "Magmatic", "Epiclastic"], "ans": "Magmatic", "back": "A molten sulphide matrix with rounded clasts is magmatic, as at Sudbury."},
 {"id": "L3-cp4", "lecture": 3, "kind": "mc", "front": "A hand specimen has about 25% sphalerite and galena. How do you classify it?", "opts": ["Massive", "Semi-massive", "Disseminated"], "ans": "Semi-massive", "back": "10 to 50% ore minerals is semi-massive."},
 {"id": "L3-cp5", "lecture": 3, "kind": "mc", "front": "In a laminated crack-seal vein, where is the youngest material?", "opts": ["At the walls", "At the centre", "Randomly spread"], "ans": "At the centre", "back": "The centre is the weakest plane and keeps opening again. So the walls crystallise first and the centre last."},
 {"id": "L3-cp6", "lecture": 3, "kind": "mc", "front": "Vein A is offset by vein B. Vein C cuts both of them, without offsetting them. What is the order?", "opts": ["A, B, C", "C, B, A", "B, A, C"], "ans": "A, B, C", "back": "Offset features are older than the feature that offsets them. The cross-cutting feature that is not broken is the youngest."},
 {"id": "L3-cp7", "lecture": 3, "kind": "mc", "front": "Rigid quartz clasts have rotated inside fine-grained galena in a deformed ore. What is this texture?", "opts": ["Jig-saw breccia", "Durchbewegung", "Crackle breccia"], "ans": "Durchbewegung", "back": "Durchbewegung: brittle clasts rolled around in a ductile sulphide matrix during deformation."},
 {"id": "L3-cp8", "lecture": 3, "kind": "mc", "front": "In the Tuena goldfield, an honours project found five generations of veins. Why was it important to tell them apart?", "opts": ["Only the last generation contained the gold", "Every generation had the same grade", "They were all the same age"], "ans": "Only the last generation contained the gold", "back": "Textures show the order of events. If you cannot tell the veins apart, you do not know which one to follow."},
 {"id": "L3-cp9", "lecture": 3, "kind": "mc", "front": "Which three observations let you work out what broke a breccia?", "opts": ["Colour, hardness and lustre", "Clast shape and sorting, how far the clasts moved and rotated, and what the matrix is made of", "Matrix grain size only"], "ans": "Clast shape and sorting, how far the clasts moved and rotated, and what the matrix is made of", "back": "Use these three observations to work backwards to one of the six breaking agents."},
 {"id": "L3-cp10", "lecture": 3, "kind": "mc", "front": "Why do hydrothermal breccias form more easily near the surface?", "opts": ["Rock is stronger there", "Confining stress is low, so less fluid pressure is needed to reduce the effective stress to zero", "There’s no fluid at depth"], "ans": "Confining stress is low, so less fluid pressure is needed to reduce the effective stress to zero", "back": "Effective stress is confining stress minus fluid pressure. Near the surface, the confining stress is smaller, so it is easier to overcome."},
 {"id": "L3-cp11", "lecture": 3, "kind": "mc", "front": "The clasts of a breccia still fit together like a jigsaw puzzle, with quartz filling between them, and they have not rotated. What does this tell you?", "opts": ["A debris flow carried them a long way", "The rock broke and opened in place, with almost no movement", "It’s an impact breccia"], "ans": "The rock broke and opened in place, with almost no movement", "back": "A jig-saw texture means the rock only fractured and opened (dilation)."},
 {"id": "L3-cp12", "lecture": 3, "kind": "mc", "front": "Gold ore is usually in which abundance class? Why is it still mined?", "opts": ["Massive, because gold is dense", "Disseminated, because gold is so valuable that low concentrations are profitable", "Semi-massive, because it forms bands"], "ans": "Disseminated, because gold is so valuable that low concentrations are profitable", "back": "What counts as economic depends on the commodity. At Thackaringa, disseminated pyrite is the target because it contains cobalt."},
 {"id": "L3-cp13", "lecture": 3, "kind": "mc", "front": "You log three sphalerite bands: honey-yellow, red and black. What is changing?", "opts": ["Grain size", "Iron content, from low to high", "How weathered it is"], "ans": "Iron content, from low to high", "back": "Sphalerite can take iron into its structure. The darker it is, the more iron it has."},
 {"id": "L3-st1", "lecture": 3, "kind": "q", "lvl": "Recall", "front": "What three observations let you work out what broke a breccia?", "back": "(1) Clast shape and sorting: angular or rounded, sorted or not. (2) How much the clasts moved and rotated: do they still fit together? (3) What the matrix or cement is: rock flour, quartz, sulphide, melt or glass."},
 {"id": "L3-st2", "lecture": 3, "kind": "q", "lvl": "Think", "front": "Why are solution-collapse breccias good hosts for MVT ore?", "back": "The collapse makes a pipe of permeable broken rock with a lot of open space. Later, basin brines can flow through it and deposit galena and sphalerite between the blocks."},
 {"id": "L3-st3", "lecture": 3, "kind": "q", "lvl": "Apply", "front": "Explain hydrofracturing using effective stress. Why is it easier near the surface?", "back": "Effective stress is confining stress minus fluid pressure. As fluid pressure rises, effective stress falls. When the fluid pressure is greater than the confining stress plus the tensile strength, the rock breaks. Near the surface, the confining stress is much lower, so less fluid pressure is needed. A sudden drop in pressure can make the breaking explosive."},
 {"id": "L3-st4", "lecture": 3, "kind": "q", "lvl": "Think", "front": "How can you tell a debris flow breccia from a hydrothermal breccia in the field?", "back": "A debris flow is extremely poorly sorted. It forms at the surface by gravity, and it has no hydrothermal cement or alteration. A hydrothermal breccia has altered clasts, and a cement deposited from fluid (quartz, carbonate, sulphide) or rock flour crushed by the fluid."},
 {"id": "L3-st5", "lecture": 3, "kind": "q", "lvl": "Recall", "front": "Why are banded ores strong evidence that the ore is syngenetic?", "back": "Continuous bands of ore minerals parallel to bedding show that the sulphide was deposited layer by layer with the host sediment. This happens on the floor of a SEDEX basin or around VMS vents."},
 {"id": "L3-st6", "lecture": 3, "kind": "q", "lvl": "Recall", "front": "List the five things that you should record when you describe a vein.", "back": "Geometry (planar, sinuous), width and spacing, continuity, orientation compared with bedding or structures, and mineralogy."},
 {"id": "L3-st7", "lecture": 3, "kind": "q", "lvl": "Apply", "front": "A vein has comb quartz along both walls and molybdenite in the centre. What type of vein is it, and what is the sequence?", "back": "A space-fill vein. Quartz grew first from the walls into open space (the crystal points face inwards). Then molybdenite filled the space that was left."},
 {"id": "L3-st8", "lecture": 3, "kind": "q", "lvl": "Think", "front": "Why do companies like stockwork veins in a porphyry so much?", "back": "A stockwork shows strong, repeated hydrofracturing and many pulses of mineralisation through a large volume of rock. This gives the very large, low-grade tonnage that porphyries are mined for."},
 {"id": "L3-st9", "lecture": 3, "kind": "q", "lvl": "Recall", "front": "What is the easiest field sign that an ore has been remobilised by metamorphism?", "back": "A coarse grain size compared with the original fine sulphides, often with strained, ribbon-shaped galena."},
 {"id": "L3-st10", "lecture": 3, "kind": "q", "lvl": "Think", "front": "Why does durchbewegung texture need both brittle and ductile materials?", "back": "The brittle material (siliceous host rock or quartz) breaks into clasts. The ductile sulphide (galena, sphalerite) flows around them, so the clasts can rotate. If everything were ductile, the rock would just be smeared. If everything were brittle, the rock would just be crushed (cataclasis)."},
 /* Lecture 4: 30 terms, 8 checkpoints, 10 self-test */
 {"id": "L4-g-anisotropy", "lecture": 4, "kind": "term", "front": "Anisotropy", "back": "Shows colours, and goes dark four times in one rotation, under crossed polars."},
 {"id": "L4-g-bireflectance", "lecture": 4, "kind": "term", "front": "Bireflectance", "back": "A change in the brightness of a grain when you rotate the stage in PPL."},
 {"id": "L4-g-bireflectance-pleochroism", "lecture": 4, "kind": "term", "front": "Bireflectance pleochroism", "back": "A change in the colour of a grain when you rotate the stage in PPL. Very strong in covellite."},
 {"id": "L4-g-caries-texture", "lecture": 4, "kind": "term", "front": "Caries texture", "back": "The edges of an early mineral look eaten away, because a later mineral replaced them. Also called atoll texture."},
 {"id": "L4-g-chalcopyrite-disease", "lecture": 4, "kind": "term", "front": "Chalcopyrite disease", "back": "Tiny chalcopyrite spots in sphalerite. They usually form by later replacement, not by exsolution."},
 {"id": "L4-g-conchoidal-fracture", "lecture": 4, "kind": "term", "front": "Conchoidal fracture", "back": "Curved, shell-shaped fractures. Typical of chromite in polished section."},
 {"id": "L4-g-crossed-polars", "lecture": 4, "kind": "term", "front": "Crossed polars", "back": "Both the polariser and the analyser are in (XPL or UXP). Used to test anisotropy and to see internal reflections."},
 {"id": "L4-g-cuspate-lobate", "lecture": 4, "kind": "term", "front": "Cuspate-lobate", "back": "Smooth grain boundaries where each mineral pushes into the other. They show that the two minerals grew together."},
 {"id": "L4-g-euhedral", "lecture": 4, "kind": "term", "front": "Euhedral", "back": "Has its own crystal faces."},
 {"id": "L4-g-exsolution-lamellae", "lecture": 4, "kind": "term", "front": "Exsolution lamellae", "back": "Thin, oriented plates of one mineral that separated from another mineral during cooling, like chalcopyrite in bornite."},
 {"id": "L4-g-framboid", "lecture": 4, "kind": "term", "front": "Framboid", "back": "A round cluster of tiny pyrite (or galena) crystals. Often formed by microbes, but can be hydrothermal."},
 {"id": "L4-g-free-gold", "lecture": 4, "kind": "term", "front": "Free gold", "back": "Gold that occurs as separate grains. It can be recovered by gravity or simple leaching."},
 {"id": "L4-g-grain-mount", "lecture": 4, "kind": "term", "front": "Grain mount", "back": "Loose grains (concentrate, crushed ore) set in resin and polished."},
 {"id": "L4-g-gravity-separation", "lecture": 4, "kind": "term", "front": "Gravity separation", "back": "Recovering dense minerals, like free gold, because their density is different from the rest of the ore."},
 {"id": "L4-g-internal-reflections", "lecture": 4, "kind": "term", "front": "Internal reflections", "back": "Coloured light that comes back from inside a partly transparent grain, reflected by fractures. Classic in sphalerite."},
 {"id": "L4-g-isotropic", "lecture": 4, "kind": "term", "front": "Isotropic", "back": "Stays dark under crossed polars at every angle of rotation. Cubic minerals are isotropic, except pyrite."},
 {"id": "L4-g-mineragraphy", "lecture": 4, "kind": "term", "front": "Mineragraphy", "back": "Ore microscopy: the study of ore minerals in polished sections using reflected light."},
 {"id": "L4-g-opaque-mineral", "lecture": 4, "kind": "term", "front": "Opaque mineral", "back": "A mineral that does not let transmitted light pass through, such as most sulphides and oxides."},
 {"id": "L4-g-paragenesis", "lecture": 4, "kind": "term", "front": "Paragenesis", "back": "The order in which minerals crystallised in a deposit. It is often drawn as a chart."},
 {"id": "L4-g-penalty-elements", "lecture": 4, "kind": "term", "front": "Penalty elements", "back": "Elements such as arsenic and tellurium. Smelters charge extra money when they are in a concentrate."},
 {"id": "L4-g-polished-block", "lecture": 4, "kind": "term", "front": "Polished block", "back": "A sample set in resin, with one face polished for reflected light."},
 {"id": "L4-g-polished-thin-section", "lecture": 4, "kind": "term", "front": "Polished thin section", "back": "A 30 µm section with a polished top surface. You can use it in both transmitted and reflected light."},
 {"id": "L4-g-polishing-hardness", "lecture": 4, "kind": "term", "front": "Polishing hardness", "back": "Relative hardness seen in a polished section. Hard grains stand higher with sharp edges; soft grains get scratched."},
 {"id": "L4-g-porphyroblast", "lecture": 4, "kind": "term", "front": "Porphyroblast", "back": "A large crystal that grew inside a finer matrix. It often contains inclusions of earlier minerals."},
 {"id": "L4-g-ppl", "lecture": 4, "kind": "term", "front": "PPL", "back": "Plane-polarised light: one polariser in. Used for colour, reflectance and bireflectance."},
 {"id": "L4-g-reflectance", "lecture": 4, "kind": "term", "front": "Reflectance", "back": "How much light a polished surface reflects. Judge it by comparing with the grains next to it."},
 {"id": "L4-g-reflected-light", "lecture": 4, "kind": "term", "front": "Reflected light", "back": "Light that comes down through the objective and reflects off a polished surface. It is used for opaque minerals."},
 {"id": "L4-g-refractory-gold", "lecture": 4, "kind": "term", "front": "Refractory gold", "back": "Gold that is locked inside sulphides such as pyrite or arsenopyrite. It needs extra processing to recover it."},
 {"id": "L4-g-tarnish", "lecture": 4, "kind": "term", "front": "Tarnish", "back": "A colour change on the surface after polishing: purple on bornite, bluish on chalcocite."},
 {"id": "L4-g-triangular-pits", "lecture": 4, "kind": "term", "front": "Triangular pits", "back": "Small pits left where polishing pulls out cleavage fragments. They are diagnostic of galena."},
 {"id": "L4-cp1", "lecture": 4, "kind": "mc", "front": "Why should you report minerals that contain arsenic and tellurium in an ore?", "opts": ["They raise the grade", "Smelters charge penalties for them, and they can harm the environment", "They make the ore easier to grind"], "ans": "Smelters charge penalties for them, and they can harm the environment", "back": "Unwanted minerals cost money at the smelter and can be dangerous to the environment, so you want to know about them early."},
 {"id": "L4-cp2", "lecture": 4, "kind": "mc", "front": "Under crossed polars, a grain stays completely black when you rotate the stage. It is...", "opts": ["Isotropic, like galena", "Strongly anisotropic", "Showing internal reflections"], "ans": "Isotropic, like galena", "back": "Isotropic minerals stay dark at every angle under crossed polars. Cubic minerals are isotropic, except pyrite."},
 {"id": "L4-cp3", "lecture": 4, "kind": "mc", "front": "Pyrite looks bright next to sphalerite but dull next to galena. Which property are you judging wrongly?", "opts": ["Hardness", "Reflectance, which you must judge by comparing with the grains next to it", "Crystal system"], "ans": "Reflectance, which you must judge by comparing with the grains next to it", "back": "How bright a grain looks depends on the grains next to it. Always compare a grain with its neighbours."},
 {"id": "L4-cp4", "lecture": 4, "kind": "mc", "front": "A galena inclusion in sphalerite has smooth boundaries where each mineral pushes into the other. What does this mean?", "opts": ["Galena replaced sphalerite much later", "They co-crystallised", "Weathering"], "ans": "They co-crystallised", "back": "Cuspate-lobate boundaries with no cross-cutting are an equilibrium texture: the two minerals grew together."},
 {"id": "L4-cp5", "lecture": 4, "kind": "mc", "front": "Bright white mineral, soft, isotropic, with triangular pits. Name it.", "opts": ["Arsenopyrite", "Galena", "Chalcocite"], "ans": "Galena", "back": "Triangular cleavage pits mean galena; no other common mineral has them."},
 {"id": "L4-cp6", "lecture": 4, "kind": "mc", "front": "Why do ore minerals need reflected light instead of transmitted light?", "opts": ["They are too soft to make thin sections", "They are opaque: their dense structures with heavy elements absorb the light, so you study the polished surface instead", "They’re colourless"], "ans": "They are opaque: their dense structures with heavy elements absorb the light, so you study the polished surface instead", "back": "The reflective surface gives you information, even though the mineral is opaque."},
 {"id": "L4-cp7", "lecture": 4, "kind": "mc", "front": "A grain stays dark when you rotate it under crossed polars. What does this tell you?", "opts": ["It’s strongly anisotropic", "It is isotropic, like galena or pentlandite", "It’s magnetic"], "ans": "It is isotropic, like galena or pentlandite", "back": "Isotropic minerals stay dark when rotated. Anisotropic minerals change colour and brightness."},
 {"id": "L4-cp8", "lecture": 4, "kind": "mc", "front": "Where should you start when you use the identification key?", "opts": ["Hardness", "Colour, the easiest observation. Then reflectance, anisotropy, hardness and internal reflections", "Internal reflections"], "ans": "Colour, the easiest observation. Then reflectance, anisotropy, hardness and internal reflections", "back": "You do not memorise nineteen descriptions; you remove the minerals that do not match."},
 {"id": "L4-st1", "lecture": 4, "kind": "q", "lvl": "Recall", "front": "Why are most ore minerals studied in reflected light instead of transmitted light?", "back": "They are opaque. Their dense structures with heavy elements absorb transmitted light, so they look black in a thin section. A polished surface reflects light, and this shows their colour, reflectance and anisotropy."},
 {"id": "L4-st2", "lecture": 4, "kind": "q", "lvl": "Recall", "front": "Give three reasons why a mining company pays for ore microscopy.", "back": "Any three of these: which mineral contains the metal (free or refractory gold); grain size, for grinding and liberation; unwanted minerals like As and Te that cause penalties; alteration minerals linked to ore, for exploration; timing relationships, for understanding how the deposit formed."},
 {"id": "L4-st3", "lecture": 4, "kind": "q", "lvl": "Recall", "front": "What is the difference between bireflectance and bireflectance pleochroism?", "back": "You see both when you rotate the stage in PPL. Bireflectance is a change in brightness. Bireflectance pleochroism is a change in colour."},
 {"id": "L4-st4", "lecture": 4, "kind": "q", "lvl": "Think", "front": "Pyrite is cubic. What is unusual about it under crossed polars?", "back": "Cubic minerals should be isotropic, but pyrite is often weakly to strongly anisotropic. It is the classic exception."},
 {"id": "L4-st5", "lecture": 4, "kind": "q", "lvl": "Apply", "front": "How can you tell pyrite, chalcopyrite and gold apart?", "back": "Pyrite: pale yellow, high reflectance, hard, perfect polish. Chalcopyrite: stronger yellow, softer, moderate reflectance. Gold: yellow-orange, very bright even when the lamp is turned down, soft and polishes poorly."},
 {"id": "L4-st6", "lecture": 4, "kind": "q", "lvl": "Apply", "front": "A grain is pink-brown with thin blue and yellow lamellae and a purple tarnish. Identify all three minerals.", "back": "Bornite (pink-brown, purple tarnish) with lamellae of chalcocite (blue) and chalcopyrite (yellow). The lamellae formed by exsolution or replacement."},
 {"id": "L4-st7", "lecture": 4, "kind": "q", "lvl": "Think", "front": "Why should you never build a paragenesis from only one polished section?", "back": "One section may miss important relationships. Also, the main ore event can be separate from earlier and later events in other parts of the deposit. You need many samples, and you must connect observations at different scales."},
 {"id": "L4-st8", "lecture": 4, "kind": "q", "lvl": "Recall", "front": "What does a caries texture tell you about timing?", "back": "The mineral with the eaten-away edges (often pyrite) formed first. It was partly dissolved and replaced by the mineral that fills the holes."},
 {"id": "L4-st9", "lecture": 4, "kind": "q", "lvl": "Recall", "front": "Why can you not use magnetism alone to identify pyrrhotite?", "back": "Some pyrrhotite (monoclinic) is magnetic and some (hexagonal) is not. Use the bronze colour, strong anisotropy and fast oxidation instead."},
 {"id": "L4-st10", "lecture": 4, "kind": "q", "lvl": "Apply", "front": "All the gold in a deposit is refractory. What extra process step does the plant need, compared with a free-gold plant?", "back": "A step that breaks down the host sulphide before cyanide leaching or other recovery: roasting, pressure oxidation or bacterial oxidation."},
 /* Lecture 5: 31 terms, 8 checkpoints, 10 self-test */
 {"id": "L5-g-anticline", "lecture": 5, "kind": "term", "front": "Anticline", "back": "A fold that arches upwards. Its hinge can trap rising fluids under an impermeable cap."},
 {"id": "L5-g-aquitard", "lecture": 5, "kind": "term", "front": "Aquitard", "back": "A layer or structure that greatly slows fluid flow, such as clay-rich fault gouge, shale or a dyke."},
 {"id": "L5-g-bad-ground", "lecture": 5, "kind": "term", "front": "Bad ground", "back": "Weak rock, rich in soft minerals (talc, chlorite), along shear zones. It is hard to support underground."},
 {"id": "L5-g-brittle-ductile-transition", "lecture": 5, "kind": "term", "front": "Brittle-ductile transition", "back": "The depth in the crust where rocks change from breaking (brittle) to flowing (ductile). It is the best depth for orogenic gold."},
 {"id": "L5-g-carlin-type-gold", "lecture": 5, "kind": "term", "front": "Carlin-type gold", "back": "Invisible, micron-sized gold that replaces silty limestone along extensional faults, as in Nevada."},
 {"id": "L5-g-crustal-continuum", "lecture": 5, "kind": "term", "front": "Crustal continuum", "back": "The model where one orogenic gold system deposits gold over a wide range of depths in the crust."},
 {"id": "L5-g-decalcification", "lecture": 5, "kind": "term", "front": "Decalcification", "back": "Removal of carbonate from limestone by acidic fluid."},
 {"id": "L5-g-detachment-fault", "lecture": 5, "kind": "term", "front": "Detachment fault", "back": "A large, low-angle normal fault. It separates the stretched upper crust from the rocks below."},
 {"id": "L5-g-diapir", "lecture": 5, "kind": "term", "front": "Diapir", "back": "A body of low-density rock (such as granite) that rises and pushes through the rocks above."},
 {"id": "L5-g-en-echelon", "lecture": 5, "kind": "term", "front": "En echelon", "back": "A stepped set of parallel, overlapping structures, such as tension gashes. Typical of shear."},
 {"id": "L5-g-fault-gouge", "lecture": 5, "kind": "term", "front": "Fault gouge", "back": "Rock ground to clay-sized material along a fault. It is usually impermeable."},
 {"id": "L5-g-first-order-fault", "lecture": 5, "kind": "term", "front": "First-order fault", "back": "A very large fault, tens to hundreds of kilometres long, that acts as a main pathway for fluid."},
 {"id": "L5-g-fold-hinge", "lecture": 5, "kind": "term", "front": "Fold hinge", "back": "The part of a fold with the greatest curvature. It is a zone of weakness and a common trap."},
 {"id": "L5-g-footwall", "lecture": 5, "kind": "term", "front": "Footwall", "back": "The block below an inclined fault or orebody."},
 {"id": "L5-g-greenstone-belt", "lecture": 5, "kind": "term", "front": "Greenstone belt", "back": "An Archaean belt of metamorphosed volcanic and sedimentary rocks. Often rich in gold."},
 {"id": "L5-g-hanging-wall", "lecture": 5, "kind": "term", "front": "Hanging wall", "back": "The block above an inclined fault or orebody."},
 {"id": "L5-g-horst-and-graben", "lecture": 5, "kind": "term", "front": "Horst and graben", "back": "Blocks that are raised (horst) and dropped down (graben) between normal faults, in extension."},
 {"id": "L5-g-jasperoid", "lecture": 5, "kind": "term", "front": "Jasperoid", "back": "Fine-grained silica that has replaced limestone. Typical of Carlin-type alteration."},
 {"id": "L5-g-l-tectonite", "lecture": 5, "kind": "term", "front": "L-tectonite", "back": "A rock with a strong stretching lineation, so it looks like a bundle of rods or pencils."},
 {"id": "L5-g-lineament", "lecture": 5, "kind": "term", "front": "Lineament", "back": "A line on images or geophysical maps that may show a fault or a structural corridor."},
 {"id": "L5-g-normal-fault", "lecture": 5, "kind": "term", "front": "Normal fault", "back": "A fault where the hanging wall moves down compared with the footwall. It forms under extension."},
 {"id": "L5-g-orogenic-gold", "lecture": 5, "kind": "term", "front": "Orogenic gold", "back": "Gold deposits formed by metamorphic fluids along shear zones in mountain belts that are being deformed."},
 {"id": "L5-g-plane-of-weakness", "lecture": 5, "kind": "term", "front": "Plane of weakness", "back": "Any surface that already exists (bedding, contact, fault, foliation). Later stress moves the rock along it, instead of breaking new rock."},
 {"id": "L5-g-reactivation", "lecture": 5, "kind": "term", "front": "Reactivation", "back": "New movement on a structure that already exists, during a later deformation."},
 {"id": "L5-g-reverse-fault", "lecture": 5, "kind": "term", "front": "Reverse fault", "back": "A fault where the hanging wall moves up. It forms under compression. A low-angle reverse fault is a thrust."},
 {"id": "L5-g-rheological-barrier", "lecture": 5, "kind": "term", "front": "Rheological barrier", "back": "A strong, rigid body (such as a granite) that deforms differently from the rocks around it and blocks fluid."},
 {"id": "L5-g-rock-softening", "lecture": 5, "kind": "term", "front": "Rock softening", "back": "When competent rock becomes weaker because of deformation and fluid, often because chlorite and talc grow."},
 {"id": "L5-g-saddle-reef", "lecture": 5, "kind": "term", "front": "Saddle reef", "back": "A body of quartz and gold that fills the gap opened between beds at an anticline hinge, as at Bendigo."},
 {"id": "L5-g-splay", "lecture": 5, "kind": "term", "front": "Splay", "back": "A smaller fault that branches off a larger one. Second-order and third-order splays often host orogenic gold."},
 {"id": "L5-g-strike-slip-fault", "lecture": 5, "kind": "term", "front": "Strike-slip fault", "back": "A fault with mainly horizontal movement, parallel to its strike."},
 {"id": "L5-g-tension-gash", "lecture": 5, "kind": "term", "front": "Tension gash", "back": "A short vein opened by extension inside a shear zone. It is often S-shaped (sigmoidal)."},
 {"id": "L5-cp1", "lecture": 5, "kind": "mc", "front": "A fault cuts an ore lens and offsets it by 40 m. The fault zone is full of talc. What type of structure is it, and what problem does it cause?", "opts": ["Pre-mineralisation; it focused the fluid", "Post-mineralisation; it offsets ore and makes bad ground", "Syn-mineralisation; it carries the gold"], "ans": "Post-mineralisation; it offsets ore and makes bad ground", "back": "It cuts and offsets the ore, so it is younger than the ore. Fluid flowing along it grew talc and chlorite. This makes weak ground that is hard to support, and the talc makes the flotation concentrate less pure."},
 {"id": "L5-cp2", "lecture": 5, "kind": "mc", "front": "Where along a very large shear zone would you expect to find orogenic gold deposits?", "opts": ["On the main first-order fault itself", "On second- and third-order splays and cross-faults", "Far from any faults"], "ans": "On second- and third-order splays and cross-faults", "back": "The large fault is the main pathway for fluid. But the deposits are on the smaller branches, where fluid slowed down, mixed or met reactive rock."},
 {"id": "L5-cp3", "lecture": 5, "kind": "mc", "front": "Which deformation style is critical for Carlin-type gold?", "opts": ["Extension", "Compression", "None: it’s magmatic"], "ans": "Extension", "back": "Extensional faults let fluid rise and spread sideways into reactive silty limestone. Without extension, there is no deposit."},
 {"id": "L5-cp4", "lecture": 5, "kind": "mc", "front": "Why is an anticline hinge a good trap for both oil and gold?", "opts": ["It’s the lowest point", "It is a zone of weakness, and it is the highest point under an impermeable cap", "It’s always hotter"], "ans": "It is a zone of weakness, and it is the highest point under an impermeable cap", "back": "Fluid that is lighter than the rock rises to the hinge and is held under a seal. The hinge also cracks and opens space (saddle reefs)."},
 {"id": "L5-cp5", "lecture": 5, "kind": "mc", "front": "At Granny Smith, the gold is along only one side of a granite. What is the best explanation?", "opts": ["The granite acted as a rheological barrier that blocked fluid flow", "The granite is the source of gold on one side only", "Erosion removed the other side"], "ans": "The granite acted as a rheological barrier that blocked fluid flow", "back": "A rigid granite changes the direction of the fluid and makes it collect along its edge. So local structure controls where the gold is."},
 {"id": "L5-cp6", "lecture": 5, "kind": "mc", "front": "In the Pilbara, where should you look for gold?", "opts": ["In the centres of granite domes", "In shear zones on the sides of the granite domes, where greenstones sank between them", "Only on the largest regional faults"], "ans": "In shear zones on the sides of the granite domes, where greenstones sank between them", "back": "Dome-and-keel tectonics placed the shear zones, and the gold, between the rising domes and the sinking greenstone."},
 {"id": "L5-cp7", "lecture": 5, "kind": "mc", "front": "Which of these structures is doing the \"block flow\" job?", "opts": ["A dilational jog opening space", "Fault gouge ground to clay, which stops the fluid so it deposits its metals", "A later fault that moves part of the orebody"], "ans": "Fault gouge ground to clay, which stops the fluid so it deposits its metals", "back": "Seals make fluid collect and deposit its metal. Examples: gouge, impermeable beds in fold hinges, dykes."},
 {"id": "L5-cp8", "lecture": 5, "kind": "mc", "front": "Why does later stress usually move bedding planes and old faults again, instead of breaking new rock?", "opts": ["Any surface that already exists is a plane of weakness", "Old faults are always vertical", "Fresh rock is weaker"], "ans": "Any surface that already exists is a plane of weakness", "back": "This is also why contacts weather first and are hard to find exposed."},
 {"id": "L5-st1", "lecture": 5, "kind": "q", "lvl": "Recall", "front": "Name the four jobs structures do in ore systems.", "back": "(1) Make space for fluid and minerals. (2) Block fluid flow so that fluid collects. (3) Make rock weaker (with fluid, forming chlorite and talc). (4) Move ore after it forms."},
 {"id": "L5-st2", "lecture": 5, "kind": "q", "lvl": "Think", "front": "Why do structures that already exist move again, instead of new structures forming?", "back": "They are planes of weakness. Stress concentrates in them, and they break at a lower stress than unbroken rock."},
 {"id": "L5-st3", "lecture": 5, "kind": "q", "lvl": "Recall", "front": "Give one example each of pre-, syn- and post-mineralisation structures.", "back": "Pre: bedding, an old growth fault. Syn: a vein, a fault that moved while a porphyry formed, slump folds in VMS or SEDEX. Post: a fault that offsets a lode, a shear zone that makes bad ground."},
 {"id": "L5-st4", "lecture": 5, "kind": "q", "lvl": "Think", "front": "Why can VMS deposits only form in extensional ocean settings?", "back": "They need thin crust above a heat source, and permeable faults. Then seawater can circulate, dissolve metals and come out through black smokers. Extension provides both."},
 {"id": "L5-st5", "lecture": 5, "kind": "q", "lvl": "Apply", "front": "You followed a vein in the hanging wall to a normal fault. Should you go up or down the fault to find it again?", "back": "Up. The hanging wall moved down, so the other part of the vein, in the footwall, is up the fault plane compared with you."},
 {"id": "L5-st6", "lecture": 5, "kind": "q", "lvl": "Recall", "front": "How is the shape of the ore different in extensional and compressional settings, in the same rocks?", "back": "Extension makes open faults that host one large lens. In compression, folds and faults act as aquitards, so fluid replaces favourable beds below them and forms a series of smaller lenses."},
 {"id": "L5-st7", "lecture": 5, "kind": "q", "lvl": "Recall", "front": "Why do faults often seal oil fields instead of letting the oil escape?", "back": "Fault movement grinds rock into clay gouge, and oil and gas cannot flow through it."},
 {"id": "L5-st8", "lecture": 5, "kind": "q", "lvl": "Think", "front": "Why are the first-order shear zones in the Yilgarn often barren, while their splays are rich?", "back": "The large faults are mostly in compression, so fluid passes through them instead of being trapped. The smaller splays are in extension and open up. There, fluid slows down, mixes and deposits gold."},
 {"id": "L5-st9", "lecture": 5, "kind": "q", "lvl": "Recall", "front": "What is typical about the orientation of veins in orogenic gold deposits like Red Lake?", "back": "The orebody plunges steeply to a great depth, but the individual quartz veins and lenses are almost horizontal."},
 {"id": "L5-st10", "lecture": 5, "kind": "q", "lvl": "Apply", "front": "What are L-tectonites? Why are they found between Pilbara granite domes?", "back": "Rocks with a strong stretching lineation, like bundles of rods. The dense greenstone keels sank between the rising granite domes and were stretched vertically."},
 /* Lecture 6: 33 terms, 11 checkpoints, 10 self-test */
 {"id": "L6-g-anhydrite", "lecture": 6, "kind": "term", "front": "Anhydrite", "back": "Calcium sulphate (CaSO₄). It forms when seawater is heated, and makes the first walls of chimneys."},
 {"id": "L6-g-back-arc-basin", "lecture": 6, "kind": "term", "front": "Back-arc basin", "back": "A spreading basin behind an arc. About 22% of active vent fields are in back-arc basins."},
 {"id": "L6-g-black-smoker", "lecture": 6, "kind": "term", "front": "Black smoker", "back": "A high-temperature vent (about 350 to 400 °C). Its fluid forms a black cloud of fine metal sulphide particles."},
 {"id": "L6-g-bornite", "lecture": 6, "kind": "term", "front": "Bornite", "back": "A copper-iron sulphide (Cu₅FeS₄). A high-temperature copper mineral inside chimneys."},
 {"id": "L6-g-brothers-volcano", "lecture": 6, "kind": "term", "front": "Brothers volcano", "back": "A submarine caldera on the Kermadec Arc. Its NW caldera has a Cu-Au-Ag deposit with up to 90 ppm gold."},
 {"id": "L6-g-caldera", "lecture": 6, "kind": "term", "front": "Caldera", "back": "A large depression formed by collapse at the top of a volcano."},
 {"id": "L6-g-chimney", "lecture": 6, "kind": "term", "front": "Chimney", "back": "A pipe of minerals built around a vent's jet. It is zoned from hot copper minerals inside to cooler sulphate and zinc minerals outside."},
 {"id": "L6-g-convection", "lecture": 6, "kind": "term", "front": "Convection", "back": "Circulation driven by heat. Cold seawater sinks through fractures, heats up near the magma, and rises to the vents."},
 {"id": "L6-g-ctd", "lecture": 6, "kind": "term", "front": "CTD", "back": "Conductivity-temperature-depth instrument package. It is pulled behind a ship or lowered from it, often with turbidity and ORP sensors."},
 {"id": "L6-g-cubanite", "lecture": 6, "kind": "term", "front": "Cubanite", "back": "A copper-iron sulphide (CuFe₂S₃) found in the hot interior of black smoker chimneys."},
 {"id": "L6-g-diffuse-flow", "lecture": 6, "kind": "term", "front": "Diffuse flow", "back": "Warm fluid (about 2 to 60 °C) that seeps out through the seafloor around a vent."},
 {"id": "L6-g-east-pacific-rise", "lecture": 6, "kind": "term", "front": "East Pacific Rise", "back": "The spreading ridge in the eastern Pacific. It spreads at about 6 cm per year. Vents were first found here in 1977."},
 {"id": "L6-g-entrainment", "lecture": 6, "kind": "term", "front": "Entrainment", "back": "Being carried along by a moving fluid. Here, circulating hydrothermal fluid carries vapour bubbles upwards."},
 {"id": "L6-g-exclusive-economic-zone", "lecture": 6, "kind": "term", "front": "Exclusive economic zone", "back": "The sea area around a country, where that country owns the rights to resources, including seafloor minerals."},
 {"id": "L6-g-extremophile", "lecture": 6, "kind": "term", "front": "Extremophile", "back": "An organism that lives well in extreme conditions, such as heat, pressure, acid or salt."},
 {"id": "L6-g-focused-flow", "lecture": 6, "kind": "term", "front": "Focused flow", "back": "Hot fluid (about 350 °C) that flows up through the vent and chimney in a narrow channel."},
 {"id": "L6-g-hyperthermophile", "lecture": 6, "kind": "term", "front": "Hyperthermophile", "back": "An organism that lives above about 80 °C, as at deep-sea vents."},
 {"id": "L6-g-island-arc", "lecture": 6, "kind": "term", "front": "Island arc", "back": "A chain of volcanoes above a subduction zone. It is the best modern example of most ancient VMS settings."},
 {"id": "L6-g-kermadec-arc", "lecture": 6, "kind": "term", "front": "Kermadec Arc", "back": "An intra-oceanic arc about 1200 km long, from New Zealand towards Tonga. It is the most hydrothermally active arc in the world."},
 {"id": "L6-g-ligand", "lecture": 6, "kind": "term", "front": "Ligand", "back": "An ion or molecule that bonds to a metal and carries it. Here, it is sulphur in vapour."},
 {"id": "L6-g-metalliferous-sediment", "lecture": 6, "kind": "term", "front": "Metalliferous sediment", "back": "Sediment rich in iron and manganese. It settles out of vent plumes away from the vent, and is a vector towards sulphides."},
 {"id": "L6-g-mound", "lecture": 6, "kind": "term", "front": "Mound", "back": "A pile of sulphide that builds up around vents over time, mainly sphalerite, pyrite and some chalcopyrite."},
 {"id": "L6-g-ntu", "lecture": 6, "kind": "term", "front": "NTU", "back": "Nephelometric turbidity units: a measure of how much the particles in the water scatter light. High NTU shows a plume."},
 {"id": "L6-g-orp", "lecture": 6, "kind": "term", "front": "ORP", "back": "Oxidation-reduction potential. It drops sharply where there are reduced chemicals, such as H₂S, from fresh vent fluid."},
 {"id": "L6-g-palaeoalluvial", "lecture": 6, "kind": "term", "front": "Palaeoalluvial", "back": "An old river (alluvial) deposit that is now preserved in the rock record, like the Witwatersrand gold."},
 {"id": "L6-g-piezophile", "lecture": 6, "kind": "term", "front": "Piezophile", "back": "An organism that lives well at very high pressure (up to 130 MPa), as at deep-sea vents."},
 {"id": "L6-g-pillow-lava", "lecture": 6, "kind": "term", "front": "Pillow lava", "back": "Rounded lava shapes that form when lava erupts into water. The rims cool very quickly to glass."},
 {"id": "L6-g-plume", "lecture": 6, "kind": "term", "front": "Plume", "back": "The cloud of vent fluid and particles that rises from a vent. It then spreads sideways and drifts with currents."},
 {"id": "L6-g-sms", "lecture": 6, "kind": "term", "front": "SMS", "back": "Seafloor massive sulphide: the modern, still-forming seafloor equivalent of a VMS deposit."},
 {"id": "L6-g-solwara-1", "lecture": 6, "kind": "term", "front": "Solwara 1", "back": "A seafloor massive sulphide deposit in the Bismarck Sea, PNG. It has about 7% Cu, but only about 2 Mt. It was never mined."},
 {"id": "L6-g-vapour-exsolution", "lecture": 6, "kind": "term", "front": "Vapour exsolution", "back": "Gas that separates from a magma as bubbles when the magma rises and the pressure drops."},
 {"id": "L6-g-vms", "lecture": 6, "kind": "term", "front": "VMS", "back": "Volcanogenic massive sulphide deposit: a body of massive sulphide formed on or just below the seafloor by hydrothermal vents in a volcanic setting."},
 {"id": "L6-g-white-smoker", "lecture": 6, "kind": "term", "front": "White smoker", "back": "A cooler vent (about 260 to 300 °C). It gives off pale barium, calcium and silicon minerals such as baryte, anhydrite and silica."},
 {"id": "L6-cp1", "lecture": 6, "kind": "mc", "front": "What can a mineralising system that is active today give you that an ancient orebody cannot?", "opts": ["Higher grades", "Direct measurements of fluid temperature, pH, metal content and flow while the ore forms", "Bigger tonnages"], "ans": "Direct measurements of fluid temperature, pH, metal content and flow while the ore forms", "back": "A rock only shows the final result. A living vent lets you measure the process itself."},
 {"id": "L6-cp2", "lecture": 6, "kind": "mc", "front": "What did the first towed-camera surveys of the East Pacific Rise show?", "opts": ["Every vent is active and the same", "Venting is normal along the ridge, but only some vents are active, and they have different temperatures and compositions", "Vents occur only at the ends of transform faults"], "ans": "Venting is normal along the ridge, but only some vents are active, and they have different temperatures and compositions", "back": "Vents turn on and off and are very different from each other. This is why ancient deposits record many pulses."},
 {"id": "L6-cp3", "lecture": 6, "kind": "mc", "front": "What is the main reason that sulphides are deposited at a black smoker?", "opts": ["Seawater evaporating", "Hot, acidic fluid with dissolved metals mixes with cold, alkaline seawater, and the pressure drops", "Bacteria eating the metals"], "ans": "Hot, acidic fluid with dissolved metals mixes with cold, alkaline seawater, and the pressure drops", "back": "Mixing and the pressure drop at the seafloor make the metals insoluble, so they crystallise as tiny sulphide particles."},
 {"id": "L6-cp4", "lecture": 6, "kind": "mc", "front": "A cut chimney has chalcopyrite and bornite along its central channel and anhydrite on the outside. Why?", "opts": ["The channel carried the hottest fluid, so copper minerals formed there. The outside touched cold seawater", "Copper is heavy and sank inwards", "The outside formed later, at a higher temperature"], "ans": "The channel carried the hottest fluid, so copper minerals formed there. The outside touched cold seawater", "back": "Copper minerals need the hottest fluid. Heated seawater on the outer wall deposits calcium sulphate."},
 {"id": "L6-cp5", "lecture": 6, "kind": "mc", "front": "You find iron-manganese crusts and metalliferous sediment in an old volcanic sequence. What does this suggest?", "opts": ["You are far from any hydrothermal system", "You are in the right environment, and sulphide mounds may be nearby", "The rocks were weathered on land"], "ans": "You are in the right environment, and sulphide mounds may be nearby", "back": "Fe and Mn settle out of plumes away from vents, so they are a vector towards sulphides."},
 {"id": "L6-cp6", "lecture": 6, "kind": "mc", "front": "Tube worms can live at vents because...", "opts": ["they photosynthesise", "microbes live inside them. The microbes use vent chemicals such as sulphide and make organic compounds", "they eat the chimney"], "ans": "microbes live inside them. The microbes use vent chemicals such as sulphide and make organic compounds", "back": "It is a food chain based on chemistry: the microbes change vent chemicals into organic matter."},
 {"id": "L6-cp7", "lecture": 6, "kind": "mc", "front": "Turbidity is high in a layer above the summit, but ORP drops sharply only at one place near the seafloor. Where is the vent?", "opts": ["Where turbidity is highest in the plume layer", "Below the ORP drop, because dissolved reduced chemicals have not spread far", "At the sea surface"], "ans": "Below the ORP drop, because dissolved reduced chemicals have not spread far", "back": "Particles in the plume drift with currents. The ORP drop shows fresh vent fluid close to its source."},
 {"id": "L6-cp8", "lecture": 6, "kind": "mc", "front": "About 65% of active vent fields are on mid-ocean ridges, but ancient VMS deposits look more like arc settings. Why?", "opts": ["Most ridge crust is subducted, but arc and back-arc deposits are preserved and are usually bigger", "Mid-ocean ridges never make sulphides", "Arcs are colder"], "ans": "Most ridge crust is subducted, but arc and back-arc deposits are preserved and are usually bigger", "back": "Preservation decides what stays in the rock record. Arcs also favour larger VMS deposits."},
 {"id": "L6-cp9", "lecture": 6, "kind": "mc", "front": "Why is the Kermadec Arc called a natural laboratory?", "opts": ["It is the most hydrothermally active intra-oceanic arc, with about 30 major submarine volcanoes and at least three VMS deposits forming now", "It has the deepest trench on Earth", "Its volcanoes are extinct, so it is safe"], "ans": "It is the most hydrothermally active intra-oceanic arc, with about 30 major submarine volcanoes and at least three VMS deposits forming now", "back": "You can watch arc-type VMS systems working. They are the best modern examples of ancient deposits."},
 {"id": "L6-cp10", "lecture": 6, "kind": "mc", "front": "In the arc vapour-transport model, where are the sulphides finally deposited?", "opts": ["Deep in the magma chamber", "At the seafloor, where the pressure drops suddenly", "In the atmosphere"], "ans": "At the seafloor, where the pressure drops suddenly", "back": "Vapour carries sulphur and metal upwards. The sudden pressure drop at the seafloor makes the sulphide insoluble."},
 {"id": "L6-cp11", "lecture": 6, "kind": "mc", "front": "Solwara 1 had about 7% Cu, ten times more than a typical land deposit. Why was it never mined?", "opts": ["The grade was too low", "It was very small (about 2 Mt), it could not be drilled to report it properly, it was expensive at 1.6 km depth, and the company went bankrupt", "PNG banned copper mining"], "ans": "It was very small (about 2 Mt), it could not be drilled to report it properly, it was expensive at 1.6 km depth, and the company went bankrupt", "back": "Size and practical problems mattered more than grade. Kidd Creek is 115 Mt and Ok Tedi is about 910 Mt."},
 {"id": "L6-st1", "lecture": 6, "kind": "q", "lvl": "Recall", "front": "Why are present-day vents so useful for understanding VMS deposits?", "back": "They are a natural laboratory. You can directly measure fluid temperature, pH, metal content and flow. You can sample chimneys while they form. You can compare modern volcanic rocks with ancient terranes to classify old VMS districts."},
 {"id": "L6-st2", "lecture": 6, "kind": "q", "lvl": "Recall", "front": "Write the reaction from the slide for sphalerite deposition, and say what causes it.", "back": "Zn²⁺ + 2HS⁻ → ZnS + H₂S. It happens when hot, acidic vent fluid with dissolved metals mixes with cold (2 °C), alkaline, salty seawater, and when the pressure drops at the seafloor."},
 {"id": "L6-st3", "lecture": 6, "kind": "q", "lvl": "Apply", "front": "Describe the mineral zones across the wall of a black smoker chimney, and explain them.", "back": "Inside, next to the hot channel: chalcopyrite, cubanite and bornite (copper minerals, about 350 °C). Outside, against cold seawater: anhydrite, gypsum and sphalerite. The hot fluid flows up the centre, and heated seawater deposits calcium sulphate on the outer wall."},
 {"id": "L6-st4", "lecture": 6, "kind": "q", "lvl": "Recall", "front": "How are black smokers and white smokers different?", "back": "Black smokers are hotter (350 to 400 °C) and deposit metal sulphides. White smokers are cooler (260 to 300 °C) and give off barium, calcium and silicon minerals such as baryte, anhydrite and amorphous silica."},
 {"id": "L6-st5", "lecture": 6, "kind": "q", "lvl": "Think", "front": "Why are modern vent sulphides finer grained than the sulphides in ancient VMS deposits?", "back": "They crystallise instantly as tiny particles when the fluid meets cold seawater. Ancient deposits have had time to partly recrystallise, which makes the grains coarser."},
 {"id": "L6-st6", "lecture": 6, "kind": "q", "lvl": "Think", "front": "What must happen to a sulphide mound for it to become an ore deposit?", "back": "It must be preserved: buried quickly by lava, ash or sediment. It is a loose pile of fine sulphide, so otherwise it would oxidise and break apart on the seafloor."},
 {"id": "L6-st7", "lecture": 6, "kind": "q", "lvl": "Apply", "front": "How would you find an active vent from a ship?", "back": "Map the seafloor with sonar. Pull or lower a CTD with a light-scattering sensor to find cloudy plumes (high NTU), and an ORP sensor to find fresh reduced fluid. Take water samples in bottles. Then collect rock with a submersible or ROV, and maybe drill."},
 {"id": "L6-st8", "lecture": 6, "kind": "q", "lvl": "Recall", "front": "Give the percentage of active vent fields in each tectonic setting. Explain why arcs are a better modern example of ancient VMS.", "back": "About 65% mid-ocean ridge, 22% back-arc, 12% island arc and 1% inside plates. Most ridge crust is subducted, but arc and back-arc deposits are preserved, and arcs favour larger sulphide bodies."},
 {"id": "L6-st9", "lecture": 6, "kind": "q", "lvl": "Think", "front": "Explain the vapour-transport model for metals in a magmatic arc system.", "back": "The magma boils and releases vapour. Sulphur in the vapour acts as a ligand and carries metal in vapour bubbles. Circulating hydrothermal fluid carries these bubbles upwards. Near the seafloor the pressure drops suddenly, the sulphide becomes insoluble, and it is deposited at the seafloor."},
 {"id": "L6-st10", "lecture": 6, "kind": "q", "lvl": "Synthesise", "front": "Give four reasons why seafloor massive sulphides like Solwara 1 have not been mined.", "back": "Any four: the deposits are very small (about 2 Mt, compared with hundreds of Mt on land); tonnage and grade are uncertain because they are based on grab samples, not drill core, so they cannot be reported normally; mining at 1.6 km depth in a cyclone area is very expensive; it destroys seafloor life; the law for mining in international waters is unclear; equipment is hard to repair; and there are enough resources on land."},
 /* Lecture 7: 32 terms, 11 checkpoints, 10 self-test */
 {"id": "L7-g-acid", "lecture": 7, "kind": "term", "front": "Acid", "back": "Chemical term: over 63% SiO₂."},
 {"id": "L7-g-compound-flow-facies", "lecture": 7, "kind": "term", "front": "Compound flow facies", "back": "Komatiite fields made of many smaller flow lobes."},
 {"id": "L7-g-contamination", "lecture": 7, "kind": "term", "front": "Contamination", "back": "When a magma takes in crustal material (silica, iron-rich rock, carbon) and this changes how it crystallises."},
 {"id": "L7-g-cooperite", "lecture": 7, "kind": "term", "front": "Cooperite", "back": "(Pt,Pd,Ni)S, a platinum group mineral."},
 {"id": "L7-g-cumulate", "lecture": 7, "kind": "term", "front": "Cumulate", "back": "A rock or layer made of crystals that collected by sinking in a magma chamber."},
 {"id": "L7-g-dunite", "lecture": 7, "kind": "term", "front": "Dunite", "back": "Ultramafic rock with over 90% olivine."},
 {"id": "L7-g-epigenetic", "lecture": 7, "kind": "term", "front": "Epigenetic", "back": "Formed after the host rock."},
 {"id": "L7-g-felsic", "lecture": 7, "kind": "term", "front": "Felsic", "back": "Mineral term: mostly feldspar and quartz."},
 {"id": "L7-g-flood-flow-facies", "lecture": 7, "kind": "term", "front": "Flood flow facies", "back": "Wide komatiite flow fields formed by long eruptions with large volumes of lava."},
 {"id": "L7-g-greenstone-belt", "lecture": 7, "kind": "term", "front": "Greenstone belt", "back": "A belt of altered, metamorphosed volcanic rocks. It is green because of serpentine and chlorite."},
 {"id": "L7-g-harzburgite", "lecture": 7, "kind": "term", "front": "Harzburgite", "back": "Ultramafic rock of olivine and orthopyroxene; most of the oceanic mantle."},
 {"id": "L7-g-immiscible", "lecture": 7, "kind": "term", "front": "Immiscible", "back": "Cannot mix: two liquids that stay separate, like oil and water."},
 {"id": "L7-g-interflow-sediment", "lecture": 7, "kind": "term", "front": "Interflow sediment", "back": "Sediment between lava flows. At Kambalda it supplied the sulphur."},
 {"id": "L7-g-komatiite", "lecture": 7, "kind": "term", "front": "Komatiite", "back": "An Archaean ultramafic lava. It erupted at about 1400 °C and had very low viscosity."},
 {"id": "L7-g-laterite", "lecture": 7, "kind": "term", "front": "Laterite", "back": "A deeply weathered soil profile that stayed in place (residual). Nickel laterites now supply most of the world's nickel."},
 {"id": "L7-g-lherzolite", "lecture": 7, "kind": "term", "front": "Lherzolite", "back": "Ultramafic rock of olivine with both orthopyroxene and clinopyroxene; most of the continental mantle."},
 {"id": "L7-g-merensky-reef", "lecture": 7, "kind": "term", "front": "Merensky Reef", "back": "A layer 1 to 5 m thick in the Bushveld Complex, rich in Pt, Fe, Ni, Cu and Cr."},
 {"id": "L7-g-millerite", "lecture": 7, "kind": "term", "front": "Millerite", "back": "NiS, a minor nickel sulphide in the supergene zone."},
 {"id": "L7-g-norite", "lecture": 7, "kind": "term", "front": "Norite", "back": "A gabbro where the pyroxene is orthopyroxene. It hosts much PGE and sulphide ore."},
 {"id": "L7-g-olivine-suppression", "lecture": 7, "kind": "term", "front": "Olivine suppression", "back": "Stopping olivine from crystallising early, so that nickel goes into the sulphide melt instead of into olivine."},
 {"id": "L7-g-ore-shoot", "lecture": 7, "kind": "term", "front": "Ore shoot", "back": "A long, ribbon-shaped body of ore that plunges."},
 {"id": "L7-g-pentlandite", "lecture": 7, "kind": "term", "front": "Pentlandite", "back": "(Fe,Ni)₉S₈, the main nickel ore mineral. It occurs as grains and along fractures in pyrrhotite."},
 {"id": "L7-g-peridotite", "lecture": 7, "kind": "term", "front": "Peridotite", "back": "Ultramafic rock of olivine and pyroxene with over 40% olivine."},
 {"id": "L7-g-pyroxenite", "lecture": 7, "kind": "term", "front": "Pyroxenite", "back": "Ultramafic rock with under 40% olivine and more pyroxene than hornblende."},
 {"id": "L7-g-pyrrhotite", "lecture": 7, "kind": "term", "front": "Pyrrhotite", "back": "Fe₁₋ₓS. It makes up most of magmatic Ni sulphide ore. It oxidises quickly and releases heat."},
 {"id": "L7-g-segregation", "lecture": 7, "kind": "term", "front": "Segregation", "back": "Dense crystals or droplets that sink through a magma and collect on the floor of the chamber."},
 {"id": "L7-g-sperrylite", "lecture": 7, "kind": "term", "front": "Sperrylite", "back": "PtAs₂, a platinum arsenide. Norilsk has the best crystals."},
 {"id": "L7-g-spinifex-texture", "lecture": 7, "kind": "term", "front": "Spinifex texture", "back": "Long, thin, blade-shaped olivine crystals in komatiite that cooled very quickly."},
 {"id": "L7-g-sulphide-melt", "lecture": 7, "kind": "term", "front": "Sulphide melt", "back": "A sulphide liquid that does not mix with silicate magma. It separates from a mafic or ultramafic magma and collects Ni, Cu and PGE."},
 {"id": "L7-g-syngenetic", "lecture": 7, "kind": "term", "front": "Syngenetic", "back": "Formed at the same time as the host rock."},
 {"id": "L7-g-thermal-erosion", "lecture": 7, "kind": "term", "front": "Thermal erosion", "back": "Hot lava melting and cutting down into the rock below it."},
 {"id": "L7-g-ultrabasic", "lecture": 7, "kind": "term", "front": "Ultrabasic", "back": "Chemical term: less than 45% SiO₂."},
 {"id": "L7-cp1", "lecture": 7, "kind": "mc", "front": "What do all magmatic ore deposits have in common?", "opts": ["They formed from seawater", "They are linked to primary magmas that formed in the mantle", "They are all in granites"], "ans": "They are linked to primary magmas that formed in the mantle", "back": "Ni-Cu sulphides, PGE, Cr-V-Ti oxides, P, REE and diamonds all come from magmas that formed in the mantle."},
 {"id": "L7-cp2", "lecture": 7, "kind": "mc", "front": "A rock is 70% olivine and 30% orthopyroxene, with no clinopyroxene. What is it?", "opts": ["Dunite", "Harzburgite", "Wehrlite"], "ans": "Harzburgite", "back": "Olivine plus orthopyroxene is harzburgite, the main rock of the oceanic mantle. Dunite needs more than 90% olivine."},
 {"id": "L7-cp3", "lecture": 7, "kind": "mc", "front": "Why does a magma need olivine suppressed to make a nickel sulphide deposit?", "opts": ["Olivine is too dense", "Early olivine takes the nickel into its structure, so no nickel is left for the sulphide melt", "Olivine dissolves sulphide"], "ans": "Early olivine takes the nickel into its structure, so no nickel is left for the sulphide melt", "back": "If olivine is suppressed (by silica, iron or reducing contamination), nickel goes into the sulphide liquid."},
 {"id": "L7-cp4", "lecture": 7, "kind": "mc", "front": "Why does plagioclase usually float to the top of a mafic magma chamber?", "opts": ["Its density is about the same as mafic magma (2.8), or slightly less", "It is magnetic", "It crystallises last"], "ans": "Its density is about the same as mafic magma (2.8), or slightly less", "back": "Minerals denser than the magma (2.8) sink. Plagioclase, at about 2.8, rises to the top instead."},
 {"id": "L7-cp5", "lecture": 7, "kind": "mc", "front": "Which deposit is both very large and high grade, with almost 4% Cu and about 10 g/t PGE?", "opts": ["Duluth", "Norilsk", "Mount Keith"], "ans": "Norilsk", "back": "Norilsk: 1257 Mt at 1.84% Ni, 3.75% Cu, 10 g/t PGE. Duluth is very large but very low grade."},
 {"id": "L7-cp6", "lecture": 7, "kind": "mc", "front": "Where does most of the world's nickel come from now?", "opts": ["Primary sulphide deposits like Kambalda", "Laterites, mainly in Indonesia, the Philippines and New Caledonia", "Seafloor nodules"], "ans": "Laterites, mainly in Indonesia, the Philippines and New Caledonia", "back": "New processing methods made laterites cheap. They now supply about 65%, and Indonesia produces the most."},
 {"id": "L7-cp7", "lecture": 7, "kind": "mc", "front": "Most of the sulphide in Kambalda ore is pyrrhotite, but the miners want...", "opts": ["pyrite", "pentlandite, the main nickel mineral", "magnetite"], "ans": "pentlandite, the main nickel mineral", "back": "Pentlandite contains the nickel. It occurs as grains and along fractures in the pyrrhotite."},
 {"id": "L7-cp8", "lecture": 7, "kind": "mc", "front": "Where did the sulphur in the komatiite-hosted deposits come from?", "opts": ["The mantle only", "Sediments with sulphide between the lava flows", "Seawater sulphate in the vents"], "ans": "Sediments with sulphide between the lava flows", "back": "The hot lava eroded the sulphide-rich sediments between the flows and melted them into the lava."},
 {"id": "L7-cp9", "lecture": 7, "kind": "mc", "front": "In a komatiite lava river, where do you get massive sulphide instead of disseminated sulphide?", "opts": ["Where the flow is fast and turbulent", "Where the flow is quiet, so the sulphide droplets have time to sink to the base", "Only at the flow top"], "ans": "Where the flow is quiet, so the sulphide droplets have time to sink to the base", "back": "Quiet flow lets the sulphide sink to the base. Fast flow keeps it mixed through the lava, so it is disseminated."},
 {"id": "L7-cp10", "lecture": 7, "kind": "mc", "front": "Why is drilling so important at Kambalda?", "opts": ["The ore is very deep", "The ore shoots are long and narrow, and faults, folds and dykes have cut and moved them", "Gold gets in the way"], "ans": "The ore shoots are long and narrow, and faults, folds and dykes have cut and moved them", "back": "Long, narrow lenses that later deformation has moved are easy to miss."},
 {"id": "L7-cp11", "lecture": 7, "kind": "mc", "front": "Mount Keith has only about 0.6% Ni. Why can it be mined?", "opts": ["It is very high in gold", "It is about a billion tonnes, and it could be mined as an open cut from the surface", "It is under a salt lake"], "ans": "It is about a billion tonnes, and it could be mined as an open cut from the surface", "back": "Its large size and easy access make up for the low grade."},
 {"id": "L7-st1", "lecture": 7, "kind": "q", "lvl": "Recall", "front": "Explain the difference between acid and felsic, and between basic and mafic.", "back": "Acid and basic are chemical terms based on silica (more than 63%; 45 to 55%). Felsic and mafic are mineral terms (mostly feldspar and quartz; mostly dark minerals plus plagioclase)."},
 {"id": "L7-st2", "lecture": 7, "kind": "q", "lvl": "Apply", "front": "Explain olivine suppression, and give three ways it can happen in a magma.", "back": "Olivine that crystallises early takes nickel into its structure. If olivine is suppressed, pyroxene crystallises first, and nickel goes into the sulphide melt. Three ways: silica contamination (olivine + SiO₂ → pyroxene), contamination by iron-rich rock, or a reducing environment such as a coal bed."},
 {"id": "L7-st3", "lecture": 7, "kind": "q", "lvl": "Recall", "front": "Why do chromite, magnetite and sulphide droplets collect at the base of a magma chamber, but plagioclase does not?", "back": "They are much denser (chromite 4.5 to 4.8, magnetite 5.1, chalcopyrite 4.2) than mafic magma (2.8), so they sink and form cumulates. Plagioclase (2.8) has about the same density as the magma, so it floats to the top."},
 {"id": "L7-st4", "lecture": 7, "kind": "q", "lvl": "Recall", "front": "Describe the general relationship between grade and tonnage in magmatic Ni-Cu deposits. Give one exception.", "back": "High-grade deposits are usually small (Victor and Cosmos: more than 10% Ni, about 1 Mt). The largest deposits are usually low grade (Duluth: 4000 Mt at 0.2%). Norilsk is the exception: 1257 Mt at 1.84% Ni, 3.75% Cu and 10 g/t PGE."},
 {"id": "L7-st5", "lecture": 7, "kind": "q", "lvl": "Think", "front": "Why has Australian nickel production fallen so much in recent years?", "back": "Laterites, mainly in Indonesia, became cheap to process, helped by Chinese investment in central processing plants on Sulawesi. Australian sulphide mines cannot compete on cost. So production fell from 160 000 t (2023) to 45 000 t (2025), and much of Kambalda has closed for now."},
 {"id": "L7-st6", "lecture": 7, "kind": "q", "lvl": "Recall", "front": "List the main ore minerals in a magmatic Ni-Cu sulphide deposit, and the role of each.", "back": "Pyrrhotite (most of the ore; oxidises quickly and releases heat), pentlandite (main Ni mineral), chalcopyrite (main Cu mineral), and minor millerite (supergene NiS), cooperite and sperrylite (PGE minerals), and magnetite."},
 {"id": "L7-st7", "lecture": 7, "kind": "q", "lvl": "Think", "front": "Why are komatiites found only in the Archaean? What textures do they show?", "back": "The mantle was much hotter then, so ultramafic melts erupted at about 1400 °C. Channels that cooled slowly show cumulate textures. Thin sheet flows that cooled very quickly show spinifex texture."},
 {"id": "L7-st8", "lecture": 7, "kind": "q", "lvl": "Recall", "front": "How did Western Mining find Kambalda, when Canadian explorers did not?", "back": "The Canadians explored as if the rock was fresh and exposed by glaciers. Kambalda has about 100 m of weathered cover. Western Mining understood weathered terrain and found the nickel using soil geochemistry."},
 {"id": "L7-st9", "lecture": 7, "kind": "q", "lvl": "Apply", "front": "Explain how the speed of the flow controls massive and disseminated sulphide in a komatiite channel.", "back": "Thermal erosion of sediment with sulphide releases sulphur, which forms sulphide droplets. Where the flow is quiet, the droplets have time to sink and collect at the base as massive sulphide. Where the flow is fast and turbulent, they stay mixed through the lava as disseminated sulphide."},
 {"id": "L7-st10", "lecture": 7, "kind": "q", "lvl": "Synthesise", "front": "Compare Type 1 (Kambalda) and Type 2 (Mount Keith) komatiite-hosted deposits.", "back": "Type 1: thin ribbons (1 to 5 m thick, 50 to 100 m wide, 100 to 700 m long, less than 5 Mt). Layered massive, matrix and disseminated sulphide, with up to 20% Ni at the base, in lava channels with thermal erosion. Type 2: a thick cumulate body (up to 800 m thick, 1 to 3 km wide) with 1 to 5% disseminated sulphide in olivine cumulate. About 0.6% Ni, but very large (about 1 billion t) and can be mined as an open pit."},
 /* Lecture 8: 32 terms, 11 checkpoints, 10 self-test */
 {"id": "L8-g-alkaline-intrusion", "lecture": 8, "kind": "term", "front": "Alkaline intrusion", "back": "An intrusion rich in Na and K, often with unusual minerals, REE and apatite."},
 {"id": "L8-g-anorthosite", "lecture": 8, "kind": "term", "front": "Anorthosite", "back": "A rock made almost only of plagioclase. It forms where plagioclase floats in a magma chamber."},
 {"id": "L8-g-apatite", "lecture": 8, "kind": "term", "front": "Apatite", "back": "A calcium phosphate mineral. It is the ore of phosphorus."},
 {"id": "L8-g-chromitite", "lecture": 8, "kind": "term", "front": "Chromitite", "back": "A rock made mostly of chromite."},
 {"id": "L8-g-contamination", "lecture": 8, "kind": "term", "front": "Contamination", "back": "Crustal material (silica, sulphur, Fe³⁺, carbon, sulphate) added to a magma. It causes the magma to become saturated in sulphide early."},
 {"id": "L8-g-evaporite", "lecture": 8, "kind": "term", "front": "Evaporite", "back": "Salt and sulphate rock left by evaporation. At Norilsk it supplied sulphur."},
 {"id": "L8-g-flood-basalt", "lecture": 8, "kind": "term", "front": "Flood basalt", "back": "A very large eruption of basalt lava, like the Permian-Triassic Siberian Traps at Norilsk."},
 {"id": "L8-g-garnierite", "lecture": 8, "kind": "term", "front": "Garnierite", "back": "A talc-like Ni-Mg silicate in high-grade laterite ore."},
 {"id": "L8-g-granophyre", "lecture": 8, "kind": "term", "front": "Granophyre", "back": "A fine-grained granitic rock. It is the upper part of the Sudbury melt sheet."},
 {"id": "L8-g-hortonolite", "lecture": 8, "kind": "term", "front": "Hortonolite", "back": "An iron-rich olivine. Hortonolite pipes in the Bushveld were the first hard-rock platinum deposits mined."},
 {"id": "L8-g-ipge", "lecture": 8, "kind": "term", "front": "IPGE", "back": "Iridium, osmium and ruthenium: they usually stay in the host rock."},
 {"id": "L8-g-layered-intrusion", "lecture": 8, "kind": "term", "front": "Layered intrusion", "back": "A large mafic-ultramafic intrusion made of layers of crystals that sank, like the Bushveld."},
 {"id": "L8-g-limonite-zone", "lecture": 8, "kind": "term", "front": "Limonite zone", "back": "A fine-grained, goethite-rich zone of a laterite. It has the most cobalt."},
 {"id": "L8-g-merensky-reef", "lecture": 8, "kind": "term", "front": "Merensky Reef", "back": "A thin, very coarse-grained (pegmatoidal) Bushveld layer rich in PGE, Ni, Cu and Cr."},
 {"id": "L8-g-nickel-laterite", "lecture": 8, "kind": "term", "front": "Nickel laterite", "back": "A nickel deposit formed by strong weathering of ultramafic rock."},
 {"id": "L8-g-nodular-chromitite", "lecture": 8, "kind": "term", "front": "Nodular chromitite", "back": "Chromitite made of rounded chromite nodules. Typical of podiform deposits."},
 {"id": "L8-g-offset-dyke", "lecture": 8, "kind": "term", "front": "Offset dyke", "back": "A dyke of quartz diorite that spreads out from, or circles around, the Sudbury structure. Many offset dykes contain ore."},
 {"id": "L8-g-ophiolite", "lecture": 8, "kind": "term", "front": "Ophiolite", "back": "A piece of oceanic lithosphere (mantle and crust) pushed up onto land."},
 {"id": "L8-g-pal", "lecture": 8, "kind": "term", "front": "PAL", "back": "Pressure acid leaching: processing clay-type laterite with acid at high pressure."},
 {"id": "L8-g-partition-coefficient", "lecture": 8, "kind": "term", "front": "Partition coefficient", "back": "How strongly an element prefers one phase over another. Here, sulphide melt compared with silicate melt."},
 {"id": "L8-g-platreef", "lecture": 8, "kind": "term", "front": "Platreef", "back": "The PGE-bearing pyroxenite of the Bushveld's northern limb, with sulphide between the grains."},
 {"id": "L8-g-podiform-chromitite", "lecture": 8, "kind": "term", "front": "Podiform chromitite", "back": "A pod of chromitite in the mantle part of an ophiolite. It is the source of metallurgical-grade chromium."},
 {"id": "L8-g-pothole", "lecture": 8, "kind": "term", "front": "Pothole", "back": "A dip in a Bushveld reef, where a hot new batch of magma melted and eroded the layer below."},
 {"id": "L8-g-ppge", "lecture": 8, "kind": "term", "front": "PPGE", "back": "Platinum, palladium and rhodium: they go into sulphide."},
 {"id": "L8-g-r-factor", "lecture": 8, "kind": "term", "front": "R-factor", "back": "The mass ratio of silicate magma to the sulphide melt that has reacted with it. High R: a small amount of sulphide, very rich in Ni, Cu and PGE."},
 {"id": "L8-g-saprolite", "lecture": 8, "kind": "term", "front": "Saprolite", "back": "Weathered rock that still has the texture of the original rock. It is the zone of a laterite with the most Ni."},
 {"id": "L8-g-shatter-cone", "lecture": 8, "kind": "term", "front": "Shatter cone", "back": "A cone-shaped fracture with lines on it, formed by the shock wave of a meteorite impact."},
 {"id": "L8-g-sublayer", "lecture": 8, "kind": "term", "front": "Sublayer", "back": "The contaminated base of the Sudbury Igneous Complex. It has many inclusions and is rich in sulphide."},
 {"id": "L8-g-sulphide-saturation", "lecture": 8, "kind": "term", "front": "Sulphide saturation", "back": "The point where a silicate magma cannot hold any more sulphur, so sulphide droplets that do not mix with it form."},
 {"id": "L8-g-taxitic", "lecture": 8, "kind": "term", "front": "Taxitic", "back": "An irregular, mixed texture with no clear pattern. Typical of the ore-bearing gabbro-dolerite at Norilsk."},
 {"id": "L8-g-ug2", "lecture": 8, "kind": "term", "front": "UG2", "back": "The Bushveld's Upper Group 2 chromitite. It is the world's largest platinum resource."},
 {"id": "L8-g-violarite", "lecture": 8, "kind": "term", "front": "Violarite", "back": "Ni₂FeS₄. It replaces pyrrhotite and pentlandite during deep oxidation."},
 {"id": "L8-cp1", "lecture": 8, "kind": "mc", "front": "For a magmatic nickel sulphide deposit you want...", "opts": ["a small R-factor: lots of sulphide melt", "a large R-factor: a small amount of sulphide melt that has met a lot of magma", "no sulphide at all"], "ans": "a large R-factor: a small amount of sulphide melt that has met a lot of magma", "back": "A high R-factor concentrates Ni, Cu and PGE into a small volume of sulphide. Laterites need the opposite."},
 {"id": "L8-cp2", "lecture": 8, "kind": "mc", "front": "In a deposit hosted in an intrusion, where is the massive sulphide?", "opts": ["At the top of the intrusion", "In the lower zone, at the base and contact, with network and then disseminated sulphide above it", "Only in the country rock far away"], "ans": "In the lower zone, at the base and contact, with network and then disseminated sulphide above it", "back": "Dense sulphide liquid collects at the base: massive (more than 70%), then network, then disseminated."},
 {"id": "L8-cp3", "lecture": 8, "kind": "mc", "front": "Why is Sudbury different from all other Ni-Cu deposits?", "opts": ["It formed in a meteorite impact structure, and mantle melt rose through fractures made by the impact", "It is a laterite", "It has no sulphide"], "ans": "It formed in a meteorite impact structure, and mantle melt rose through fractures made by the impact", "back": "An impact into an area that was being pulled apart broke the crust down to the mantle. The ore is in the sublayer and the offset dykes."},
 {"id": "L8-cp4", "lecture": 8, "kind": "mc", "front": "At Norilsk, what supplied much of the sulphur?", "opts": ["Seawater", "Evaporites that the sills intruded", "The mantle alone"], "ans": "Evaporites that the sills intruded", "back": "The sills intruded evaporites, and their sulphate added sulphur. The country rocks also added silica and Fe³⁺."},
 {"id": "L8-cp5", "lecture": 8, "kind": "mc", "front": "Why do massive sulphides collect at the base of an intrusion or flow?", "opts": ["Sulphide liquid (about 4.4) is much denser than silicate liquid (about 3.3)", "They crystallise first at the top and then fall", "Groundwater carries them down"], "ans": "Sulphide liquid (about 4.4) is much denser than silicate liquid (about 3.3)", "back": "Gravity separates them, and flow separation helps."},
 {"id": "L8-cp6", "lecture": 8, "kind": "mc", "front": "Which deposit is small but has by far the highest PGE grade on slide 24?", "opts": ["UG2", "Stillwater, about 21 g/t", "Platreef"], "ans": "Stillwater, about 21 g/t", "back": "Stillwater: 323 Mt at 20.7 g/t PGE. UG2 is the largest, 5743 Mt at 5.7 g/t."},
 {"id": "L8-cp7", "lecture": 8, "kind": "mc", "front": "What forms the alternating chromitite and anorthosite layers in the Bushveld?", "opts": ["Each new batch of magma deposits dense chromite at the base, while plagioclase floats", "Hydrothermal veins", "Weathering"], "ans": "Each new batch of magma deposits dense chromite at the base, while plagioclase floats", "back": "Repeated batches make rhythmic layering. A hot batch can also erode a pothole."},
 {"id": "L8-cp8", "lecture": 8, "kind": "mc", "front": "Where does metallurgical-grade chromium come from?", "opts": ["Podiform chromitites in the mantle part of ophiolites", "Laterites", "Mineral sands"], "ans": "Podiform chromitites in the mantle part of ophiolites", "back": "Layered intrusions like the Bushveld give chemical-grade chromium. Podiform pods give metallurgical-grade chromium."},
 {"id": "L8-cp9", "lecture": 8, "kind": "mc", "front": "A chromitite pod is surrounded by dunite inside harzburgite. Why is the dunite there?", "opts": ["It is a reaction rim, where basaltic magma in the channel reacted with the harzburgite", "It is weathered chromite", "It came from a later dyke"], "ans": "It is a reaction rim, where basaltic magma in the channel reacted with the harzburgite", "back": "Podiform chromitites form in conduits. The magma reacts with the host rock and leaves dunite around the channel."},
 {"id": "L8-cp10", "lecture": 8, "kind": "mc", "front": "What is the ore mineral of primary magmatic phosphorus deposits?", "opts": ["Apatite", "Monazite", "Chromite"], "ans": "Apatite", "back": "Apatite, in lenses in layered intrusions or in alkaline syenites like Khibiny."},
 {"id": "L8-cp11", "lecture": 8, "kind": "mc", "front": "Which laterite zone has the most nickel?", "opts": ["Ferricrete at the top", "Saprolite, where the texture of the original rock is preserved", "Fresh peridotite at the base"], "ans": "Saprolite, where the texture of the original rock is preserved", "back": "Saprolite has the most Ni. The limonite zone above it has the most Co."},
 {"id": "L8-st1", "lecture": 8, "kind": "q", "lvl": "Recall", "front": "Define the R-factor. Why do nickel sulphide deposits and nickel laterite deposits need opposite values?", "back": "It is the ratio of silicate magma to the sulphide melt that reacts with it. Sulphide deposits need a high R (a small volume of sulphide very rich in Ni, Cu, PGE). Laterites need a low R, so that nickel stays in olivine and is concentrated later by weathering."},
 {"id": "L8-st2", "lecture": 8, "kind": "q", "lvl": "Recall", "front": "Describe the zones and minerals of a Ni-Cu deposit hosted in an intrusion.", "back": "A lower zone of massive and brecciated sulphide (more than 70%), then network sulphide (40 to 70%) and disseminated sulphide (15 to 40%). About 70% pyrrhotite, 15% pentlandite, 15% chalcopyrite."},
 {"id": "L8-st3", "lecture": 8, "kind": "q", "lvl": "Apply", "front": "Why is contamination so important in these deposits? Give three contaminants.", "back": "It makes the magma saturated in sulphide early (and suppresses olivine). Contaminants: silica-rich crust, crustal sulphur (sediments with sulphide, or sulphate from evaporites), Fe³⁺, and carbon such as coal."},
 {"id": "L8-st4", "lecture": 8, "kind": "q", "lvl": "Think", "front": "Describe the Sudbury model, from the impact to the ore.", "back": "An impact into an area being pulled apart broke the crust down to the mantle. A melt sheet formed, and quartz diorite was injected into offset dykes. The sheet separated into norite below and granophyre above. Dense sulphides collected in the hollows of the sublayer and in the offset dykes. Cu-rich parts moved furthest out, as at Copper Cliff."},
 {"id": "L8-st5", "lecture": 8, "kind": "q", "lvl": "Think", "front": "Why can Norilsk be mined to great depth, while at Voisey's Bay a deep chamber is exposed?", "back": "At Norilsk, the whole system, from the sills to the lavas above, is preserved. At Voisey's Bay, erosion has removed the upper levels, so the chamber in the middle crust is exposed."},
 {"id": "L8-st6", "lecture": 8, "kind": "q", "lvl": "Recall", "front": "Distinguish PPGE from IPGE.", "back": "PPGE (Pt, Pd, Rh) go strongly into sulphide. IPGE (Ir, Os, Ru) usually stay in the host rock."},
 {"id": "L8-st7", "lecture": 8, "kind": "q", "lvl": "Apply", "front": "Explain the rhythmic chromitite-anorthosite layering and the potholes in the Bushveld.", "back": "Each new batch of magma crystallises dense chromite, which sinks to form chromitite, and plagioclase, which floats to form anorthosite. A hotter new batch can melt and erode the layer below, which makes potholes in the Merensky Reef."},
 {"id": "L8-st8", "lecture": 8, "kind": "q", "lvl": "Recall", "front": "List the conditions needed to form an economic Cr-V-Ti oxide deposit.", "back": "A high starting amount of Cr, Ti and V, or a new supply; early crystallisation of chromite, magnetite and ilmenite; a process that concentrates them (gravity, segregation, movement); stable T, P and oxidation state for long enough to form thick layers; removal of light minerals such as floating plagioclase; and preservation."},
 {"id": "L8-st9", "lecture": 8, "kind": "q", "lvl": "Think", "front": "How do podiform chromitites form? Why are they only found in ophiolites?", "back": "Basaltic magma flows through channels in mantle harzburgite and reacts with it, leaving a dunite rim. Chromite crystallises as magma batches mix. The dense chromite collects as pods. This happens in the oceanic upper mantle, which is only exposed on land in ophiolites."},
 {"id": "L8-st10", "lecture": 8, "kind": "q", "lvl": "Synthesise", "front": "Describe a nickel laterite profile. Say where Ni and Co are highest, and how each ore type is processed.", "back": "From the top: ferricrete, transported limonite, limonite (highest Co, with the most Ni at its base), an intermediate zone of quartz and kaolinite, saprolite (highest Ni), and fresh peridotite. Garnierite ore is smelted. Clay ore is processed by pressure acid leaching. Limonitic ore is processed by ammonia leach."},
 /* Lecture 9: 34 terms, 11 checkpoints, 10 self-test */
 {"id": "L9-g-ankerite", "lecture": 9, "kind": "term", "front": "Ankerite", "back": "Ca(Fe,Mg)(CO₃)₂, a carbonate with iron. Pale orange to yellow. Part of the halo around SEDEX ore."},
 {"id": "L9-g-anoxic", "lecture": 9, "kind": "term", "front": "Anoxic", "back": "Without oxygen. An anoxic basin floor contains H₂S and preserves organic matter."},
 {"id": "L9-g-aquifer", "lecture": 9, "kind": "term", "front": "Aquifer", "back": "A permeable rock layer that holds fluid and lets it flow. In SEDEX, the coarse syn-rift clastic sediments."},
 {"id": "L9-g-aquitard", "lecture": 9, "kind": "term", "front": "Aquitard", "back": "An impermeable layer that holds fluid in. Here, shale, chert or carbonate deposited after the rifting."},
 {"id": "L9-g-back-arc", "lecture": 9, "kind": "term", "front": "Back-arc", "back": "The region behind a volcanic arc, on the side away from the trench. It is often under extension."},
 {"id": "L9-g-barite", "lecture": 9, "kind": "term", "front": "Barite", "back": "BaSO₄, a common, dense gangue mineral in SEDEX deposits. There is more of it further from the vent."},
 {"id": "L9-g-barney-creek-formation", "lecture": 9, "kind": "term", "front": "Barney Creek Formation", "back": "The organic-rich dolomitic siltstone of the McArthur Group that hosts HYC."},
 {"id": "L9-g-brine-pool", "lecture": 9, "kind": "term", "front": "Brine pool", "back": "A body of dense, salty fluid in a low area on the seafloor."},
 {"id": "L9-g-chalcopyrite-disease", "lecture": 9, "kind": "term", "front": "Chalcopyrite disease", "back": "Tiny chalcopyrite inclusions in sphalerite. They are used as a sign of a higher temperature of formation."},
 {"id": "L9-g-chloride-complex", "lecture": 9, "kind": "term", "front": "Chloride complex", "back": "A dissolved metal bonded to chloride, like ZnCl₂. This is how zinc and lead travel in salty brine."},
 {"id": "L9-g-diagenetic", "lecture": 9, "kind": "term", "front": "Diagenetic", "back": "Formed in the sediment soon after burial, while it is still being compacted and cemented."},
 {"id": "L9-g-epigenetic", "lecture": 9, "kind": "term", "front": "Epigenetic", "back": "Formed after the host rock, for example by later replacement or veins."},
 {"id": "L9-g-exhalative", "lecture": 9, "kind": "term", "front": "Exhalative", "back": "Deposited from fluid that flowed out (exhaled) onto the seafloor."},
 {"id": "L9-g-ferroan-dolomite", "lecture": 9, "kind": "term", "front": "Ferroan dolomite", "back": "Dolomite with some iron, between ankerite and plain dolomite in the halo sequence."},
 {"id": "L9-g-galena", "lecture": 9, "kind": "term", "front": "Galena", "back": "PbS, the main lead ore mineral. White with triangular cleavage pits in reflected light. Very dense."},
 {"id": "L9-g-galvanising", "lecture": 9, "kind": "term", "front": "Galvanising", "back": "Covering steel with zinc to stop it rusting. It uses about 60% of all zinc."},
 {"id": "L9-g-growth-fault", "lecture": 9, "kind": "term", "front": "Growth fault", "back": "A normal fault that moves while sediment is being deposited, so the beds are thicker on one side."},
 {"id": "L9-g-hematite-pyrite-buffer", "lecture": 9, "kind": "term", "front": "Hematite-pyrite buffer", "back": "The redox boundary where hematite changes to pyrite. Above it, brines can carry much more Zn and Pb."},
 {"id": "L9-g-hemimorphite", "lecture": 9, "kind": "term", "front": "Hemimorphite", "back": "Zn₄Si₂O₇(OH)₂·H₂O, a white zinc silicate formed when zinc sulphide weathers."},
 {"id": "L9-g-irish-type", "lecture": 9, "kind": "term", "front": "Irish-type", "back": "Zn-Pb deposits in Carboniferous carbonates in Ireland. They have features of both SEDEX and MVT."},
 {"id": "L9-g-mvt", "lecture": 9, "kind": "term", "front": "MVT", "back": "Mississippi Valley-type: Zn-Pb deposits that replace carbonate rocks. They form from basin brines, and the brine does not flow out onto the seafloor."},
 {"id": "L9-g-overpressured", "lecture": 9, "kind": "term", "front": "Overpressured", "back": "Holding fluid at a pressure higher than normal for its depth. Also called geopressured."},
 {"id": "L9-g-sedex", "lecture": 9, "kind": "term", "front": "SEDEX", "back": "Sedimentary exhalative: a Zn-Pb-Ag deposit that forms where basin brine flows out into a reduced sedimentary basin. Also called sediment-hosted massive sulphide (SHMS)."},
 {"id": "L9-g-siderite", "lecture": 9, "kind": "term", "front": "Siderite", "back": "FeCO₃, iron carbonate. In north Australian halos, it forms brown spots closest to the ore."},
 {"id": "L9-g-sphalerite", "lecture": 9, "kind": "term", "front": "Sphalerite", "back": "ZnS, the main zinc ore mineral. Grey with low reflectance in reflected light."},
 {"id": "L9-g-syn-rift", "lecture": 9, "kind": "term", "front": "Syn-rift", "back": "Deposited while the rift was opening. Here, coarse, permeable clastic sediments."},
 {"id": "L9-g-syngenetic", "lecture": 9, "kind": "term", "front": "Syngenetic", "back": "Formed at the same time as the host rock. Here, sulphide deposited together with the sediment."},
 {"id": "L9-g-thallium-halo", "lecture": 9, "kind": "term", "front": "Thallium halo", "back": "A small increase in thallium (a few ppm) in the host rocks around SEDEX ore. It is found by assay."},
 {"id": "L9-g-tourmaline", "lecture": 9, "kind": "term", "front": "Tourmaline", "back": "A boron silicate. It is common near SEDEX vents because seawater supplies boron."},
 {"id": "L9-g-turbidite", "lecture": 9, "kind": "term", "front": "Turbidite", "back": "A graded bed deposited by a turbidity current or a mass flow that slid down a slope."},
 {"id": "L9-g-vent-distal", "lecture": 9, "kind": "term", "front": "Vent-distal", "back": "Formed away from the vent from dense brine that collected in low areas: laminated sulphide, barite, no footwall alteration."},
 {"id": "L9-g-vent-proximal", "lecture": 9, "kind": "term", "front": "Vent-proximal", "back": "Formed at or near the vent from buoyant fluid: footwall alteration, breccia pipes, coarser sulphide."},
 {"id": "L9-g-vms", "lecture": 9, "kind": "term", "front": "VMS", "back": "Volcanogenic (volcanic-hosted) massive sulphide: a Cu-Zn-Pb deposit formed by vents on the seafloor in a volcanic setting (Lecture 10)."},
 {"id": "L9-g-value", "lecture": 9, "kind": "term", "front": "Μ value", "back": "The ²³⁸U/²⁰⁴Pb ratio of a lead source. A high μ shows that the lead came from upper continental crust."},
 {"id": "L9-cp1", "lecture": 9, "kind": "mc", "front": "What does most SEDEX ore look like?", "opts": ["Massive chalcopyrite lenses", "Thin layers of sphalerite and galena between layers of shale or siltstone", "Coarse gold in quartz veins"], "ans": "Thin layers of sphalerite and galena between layers of shale or siltstone", "back": "The sulphides are in thin layers between shale and siltstone layers. They are often so fine that they are hard to process, as at HYC."},
 {"id": "L9-cp2", "lecture": 9, "kind": "mc", "front": "How does Australia rank for zinc?", "opts": ["Third largest producer, but the largest reserves", "Largest producer, with small reserves", "A minor producer with no reserves"], "ans": "Third largest producer, but the largest reserves", "back": "About 1100 kt per year, behind China and Peru, but 64 000 kt of reserves, more than China. For lead, Australia is the second largest producer and has the largest reserves."},
 {"id": "L9-cp3", "lecture": 9, "kind": "mc", "front": "Why does a SEDEX basin need an impermeable cap above the aquifer?", "opts": ["To make the fluid hotter", "To supply sulphur", "To hold the brine in, so pressure builds and the brine then flows out in a focused way"], "ans": "To hold the brine in, so pressure builds and the brine then flows out in a focused way", "back": "Without the aquitard, brine leaks away up the faults. You get higher background metal, but no deposit."},
 {"id": "L9-cp4", "lecture": 9, "kind": "mc", "front": "Which unit hosts HYC in the McArthur Basin?", "opts": ["Tawallah Group rift volcanics", "Barney Creek Formation organic-rich dolomitic siltstone, deposited in the sag phase", "The platform carbonates at the top"], "ans": "Barney Creek Formation organic-rich dolomitic siltstone, deposited in the sag phase", "back": "The rift-phase Tawallah Group below is the aquifer. The sag-phase Barney Creek Formation hosts HYC. Platform carbonates on top sealed it."},
 {"id": "L9-cp5", "lecture": 9, "kind": "mc", "front": "Why does brine leave the aquifer in pulses?", "opts": ["Pressure builds until the cap breaks and the fault opens, often in a small earthquake. Then the fault seals again", "Tides pump it out twice a day", "Rain pushes it down and out"], "ans": "Pressure builds until the cap breaks and the fault opens, often in a small earthquake. Then the fault seals again", "back": "Each break releases a pulse. Minerals deposited in the fault seal it again, and the pressure builds again."},
 {"id": "L9-cp6", "lecture": 9, "kind": "mc", "front": "A brine that is denser than seawater flows out of a vent. What do you get?", "opts": ["A buoyant plume and a mound above the vent", "No deposit at all", "A brine pool in a low area, which deposits laminated sulphide with no footwall alteration"], "ans": "A brine pool in a low area, which deposits laminated sulphide with no footwall alteration", "back": "This is the vent-distal style, like HYC: saltier, cooler, oxidised brine."},
 {"id": "L9-cp7", "lecture": 9, "kind": "mc", "front": "Where do most of the zinc and the sulphur come from?", "opts": ["Zinc from the basin sediments, dissolved by brine. Sulphur from H₂S in the anoxic seawater", "Both from a granite", "Both from the mantle"], "ans": "Zinc from the basin sediments, dissolved by brine. Sulphur from H₂S in the anoxic seawater", "back": "Metals come from the basin fill, moved by convecting brine. Sulphur comes from the water."},
 {"id": "L9-cp8", "lecture": 9, "kind": "mc", "front": "In a layered SEDEX basin, where is sphalerite deposited?", "opts": ["In the surface water with oxygen", "In the aquifer, deep in the basin", "Where the brine with metals meets H₂S in the anoxic bottom water"], "ans": "Where the brine with metals meets H₂S in the anoxic bottom water", "back": "Zinc carried as chloride complexes meets H₂S. ZnS is deposited, and clumps sink to the floor."},
 {"id": "L9-cp9", "lecture": 9, "kind": "mc", "front": "What changes as you move away from the vent along the ore layer?", "opts": ["Grade rises and Pb:Zn rises", "Grade, Pb:Zn and thickness decrease. Ba:Zn increases", "Copper increases"], "ans": "Grade, Pb:Zn and thickness decrease. Ba:Zn increases", "back": "Distal ore is thinner, lower grade, richer in zinc and richer in barite. It slowly changes into chert and barite."},
 {"id": "L9-cp10", "lecture": 9, "kind": "mc", "front": "You drill through dolomitic host rock towards a north Australian SEDEX ore body. Which carbonates do you record as you get closer?", "opts": ["Siderite → ankerite → ferroan dolomite → dolomite", "Dolomite → ferroan dolomite → ankerite → siderite", "Calcite only, all the way"], "ans": "Dolomite → ferroan dolomite → ankerite → siderite", "back": "The carbonate becomes richer in iron closer to the ore. Siderite is closest."},
 {"id": "L9-cp11", "lecture": 9, "kind": "mc", "front": "Why are SEDEX deposits found in only a few regions?", "opts": ["They form anywhere there is shale", "They need a rare combination: an enclosed, anoxic rift basin with an aquifer, a cap and focused faults. Where one basin has all of these, several deposits form", "They only formed in the last 100 million years"], "ans": "They need a rare combination: an enclosed, anoxic rift basin with an aquifer, a cap and focused faults. Where one basin has all of these, several deposits form", "back": "If you find the right basin, you usually find more than one deposit, as around Mount Isa and McArthur River."},
 {"id": "L9-st1", "lecture": 9, "kind": "q", "lvl": "Recall", "front": "What is a SEDEX deposit? Give its main ore and gangue minerals and its typical host rock.", "back": "Zn-Pb-Ag deposits formed when salty brine (about 80 to 200 °C) flows out into a reduced sedimentary basin. Sphalerite and galena (more Zn than Pb) with some silver; pyrite and pyrrhotite; barite gangue. Hosted in laminated, organic-rich black shale or dolomitic siltstone, with the sulphide in thin layers."},
 {"id": "L9-st2", "lecture": 9, "kind": "q", "lvl": "Recall", "front": "List the five things a basin needs to form SEDEX deposits.", "back": "An extensional setting; structures that control the shape of the basin and the fluid flow; a thick basin fill (2 to 5 km of syn-rift clastic sediments as the aquifer, with shale or carbonate above as the aquitard); large-scale hydrothermal fluid flow (with a heat source); and still water that contains H₂S."},
 {"id": "L9-st3", "lecture": 9, "kind": "q", "lvl": "Apply", "front": "Explain the Goodfellow and Lydon model, from rifting to ore.", "back": "A rift basin that lasts a long time fills with permeable clastic sediments (the aquifer). Reduced shale and chert cover them (the aquitard). Heat drives brine convection, which dissolves metals. The pressure in the aquifer becomes too high and it breaks the cap. Brine rises up active faults, mixes with H₂S in the anoxic water, and forms vent-proximal and vent-distal deposits."},
 {"id": "L9-st4", "lecture": 9, "kind": "q", "lvl": "Apply", "front": "Compare vent-proximal and vent-distal SEDEX deposits: the fluid, the features, and an example of each.", "back": "Proximal: buoyant (or medium-density) brine, less salty, hotter, reduced. Footwall alteration, breccia pipes, coarser sulphide. Example: Sullivan. Distal: dense brine, more salty, cooler, oxidised, collecting in low areas. Laminated sulphide, no footwall alteration, barite. Example: HYC."},
 {"id": "L9-st5", "lecture": 9, "kind": "q", "lvl": "Think", "front": "Why are north Australian SEDEX deposits rich in zinc and lead, but poor in copper?", "back": "Their brines were oxidised and almost neutral (aquifers of sandstone with hematite). So they carried thousands of ppm Zn and Pb as chloride complexes. Copper does not dissolve much in these brines, and the fluids stayed below about 300 °C, which limits copper."},
 {"id": "L9-st6", "lecture": 9, "kind": "q", "lvl": "Recall", "front": "Where do the fluid, the metals, the sulphur and the heat come from? What do the isotopes show?", "back": "Fluid: evaporated seawater and dissolved halite. Metals: basin sediments, dissolved by convecting brine. Sulphur: H₂S in the anoxic seawater. Heat: mafic sills and dykes, or another source. δ³⁴S ranges from -10 to +30‰. Uniform, high-μ Pb isotopes show that the lead came from upper-crustal rocks inside the basin."},
 {"id": "L9-st7", "lecture": 9, "kind": "q", "lvl": "Apply", "front": "Describe the layered water in the basin and how laminated ore builds up.", "back": "An oxic top layer (Fe³⁺ insoluble), a mixing layer where pyrite is deposited, and an anoxic bottom layer rich in H₂S. Brine pulses, caused by tectonic activity, meet H₂S and deposit sphalerite and galena, which sink. Between pulses, organic mud from the water and carbonate mass flows add layers of sediment."},
 {"id": "L9-st8", "lecture": 9, "kind": "q", "lvl": "Think", "front": "Compare the exhalative and replacement models for SEDEX. Which one is favoured, and why?", "back": "Exhalative: sulphide is deposited at the seafloor from brine that flowed out. Replacement: sulphide replaces permeable layers below the seafloor, during diagenesis or later deformation. At MacMillan Pass, sulphide replaced earlier barite. Most deposits, especially the large ones, have sulphide layers between sediment layers. This supports an exhalative, syngenetic origin."},
 {"id": "L9-st9", "lecture": 9, "kind": "q", "lvl": "Apply", "front": "What would you use to find the direction to a hidden SEDEX ore body?", "back": "The Fe-Mn carbonate halo (dolomite to ferroan dolomite to ankerite to siderite towards ore); Mn and Tl halos found by assay; C, O and Sr isotope halos; pyritic shale with Fe-Mn-Zn enrichment; bedded barite, with Ba:Zn increasing away from the vent; Pb/Zn zoning; and deep faults that moved during sedimentation."},
 {"id": "L9-st10", "lecture": 9, "kind": "q", "lvl": "Synthesise", "front": "Use HYC and Century to explain why a large SEDEX deposit can still be difficult to turn into a mine.", "back": "HYC's sulphides are extremely fine grained (some are less than 20 µm) and mixed with carbonaceous mud and silica. So fine-grinding technology was needed before it could be processed at a profit. Century is remote and floods in the wet season, so it needed a slurry pipeline to the Gulf to keep running 24 hours a day. Grade and tonnage are not enough without processing and infrastructure."},
 /* Lecture 10: 33 terms, 11 checkpoints, 10 self-test */
 {"id": "L10-g-alteration-pipe", "lecture": 10, "kind": "term", "front": "Alteration pipe", "back": "The pipe-shaped zone of altered footwall rock (chlorite, silica, sericite) that carried fluid up to the mound."},
 {"id": "L10-g-anhydrite", "lecture": 10, "kind": "term", "front": "Anhydrite", "back": "CaSO₄. Forms where hot fluid heats seawater, on the outside of chimneys."},
 {"id": "L10-g-barite", "lecture": 10, "kind": "term", "front": "Barite", "back": "BaSO₄. Forms on top of the mound and away from it, at low temperature."},
 {"id": "L10-g-besshi-type", "lecture": 10, "kind": "term", "front": "Besshi-type", "back": "Cu-Zn ± Co VMS deposits in mixed basalt and greywacke sequences. They are between VMS and SEDEX."},
 {"id": "L10-g-bimodal", "lecture": 10, "kind": "term", "front": "Bimodal", "back": "A volcanic sequence with two compositions, mafic and felsic, and little in between."},
 {"id": "L10-g-black-smoker", "lecture": 10, "kind": "term", "front": "Black smoker", "back": "A seafloor vent that releases fluid at about 350 °C. The fluid is black with fine sulphide particles."},
 {"id": "L10-g-caldera", "lecture": 10, "kind": "term", "front": "Caldera", "back": "A round depression that forms when the roof of a volcano collapses into an empty magma chamber."},
 {"id": "L10-g-carbonatisation", "lecture": 10, "kind": "term", "front": "Carbonatisation", "back": "Alteration that adds carbonate. Siderite near VMS ore, calcite further away."},
 {"id": "L10-g-chalcopyrite", "lecture": 10, "kind": "term", "front": "Chalcopyrite", "back": "CuFeS₂, the main copper mineral. Brassy yellow. In the hot core and stringer zone."},
 {"id": "L10-g-chlorite", "lecture": 10, "kind": "term", "front": "Chlorite", "back": "A green sheet silicate. It becomes richer in Fe and darker closer to VMS ore."},
 {"id": "L10-g-cyprus-type", "lecture": 10, "kind": "term", "front": "Cyprus-type", "back": "Small Cu-Zn VMS deposits in pillow basalts of ophiolites, like Troodos."},
 {"id": "L10-g-em-survey", "lecture": 10, "kind": "term", "front": "EM survey", "back": "Electromagnetic geophysical survey. It detects bodies that conduct electricity, such as massive sulphide."},
 {"id": "L10-g-exhalative", "lecture": 10, "kind": "term", "front": "Exhalative", "back": "Deposited from fluid that flowed out (exhaled) onto the seafloor."},
 {"id": "L10-g-exhalite", "lecture": 10, "kind": "term", "front": "Exhalite", "back": "A thin chemical sediment (often silica) on top of a VMS lens, deposited as the system becomes weaker."},
 {"id": "L10-g-galena", "lecture": 10, "kind": "term", "front": "Galena", "back": "PbS, the lead mineral. Lead grey and very dense. At the cooler edges."},
 {"id": "L10-g-invisible-gold", "lecture": 10, "kind": "term", "front": "Invisible gold", "back": "Gold locked inside the crystal structure of pyrite or arsenopyrite. It is too fine to see."},
 {"id": "L10-g-kuroko-type", "lecture": 10, "kind": "term", "front": "Kuroko-type", "back": "VMS deposits rich in Zn-Pb-Ag, in felsic volcanic rocks of arcs, like the Kuroko district of Japan."},
 {"id": "L10-g-lithotectonic-setting", "lecture": 10, "kind": "term", "front": "Lithotectonic setting", "back": "Classification based on the volcanic and sedimentary units that formed together with the deposits in a district."},
 {"id": "L10-g-mound", "lecture": 10, "kind": "term", "front": "Mound", "back": "The pile of massive sulphide built on the seafloor around a vent field."},
 {"id": "L10-g-obduction", "lecture": 10, "kind": "term", "front": "Obduction", "back": "When oceanic crust is pushed up onto continental crust, instead of going down a subduction zone."},
 {"id": "L10-g-ophiolite", "lecture": 10, "kind": "term", "front": "Ophiolite", "back": "A piece of oceanic crust and upper mantle pushed up onto land."},
 {"id": "L10-g-pillow-lava", "lecture": 10, "kind": "term", "front": "Pillow lava", "back": "Rounded lava bodies formed by an eruption underwater. A sign of a seafloor setting."},
 {"id": "L10-g-pyrrhotite", "lecture": 10, "kind": "term", "front": "Pyrrhotite", "back": "Fe₁₋ₓS, a magnetic iron sulphide. Found with chalcopyrite in the hot core."},
 {"id": "L10-g-remobilisation", "lecture": 10, "kind": "term", "front": "Remobilisation", "back": "Later movement of metals inside a deposit, or out of it, by hydrothermal fluid."},
 {"id": "L10-g-silicification", "lecture": 10, "kind": "term", "front": "Silicification", "back": "Alteration that adds silica: loss of Fe, Mg, K and gain of Si, Na. Quartz-albite-epidote."},
 {"id": "L10-g-sphalerite", "lecture": 10, "kind": "term", "front": "Sphalerite", "back": "(Zn,Fe)S, the zinc mineral. At the cooler edges."},
 {"id": "L10-g-spilitisation", "lecture": 10, "kind": "term", "front": "Spilitisation", "back": "Regional sodium alteration of basalt: gain of Na, loss of Ca. Chlorite-sericite-albite-epidote-quartz."},
 {"id": "L10-g-stockwork", "lecture": 10, "kind": "term", "front": "Stockwork", "back": "A dense network of crossing veins. Here, the feeder below a VMS lens."},
 {"id": "L10-g-stringer-zone", "lecture": 10, "kind": "term", "front": "Stringer zone", "back": "The network of veins with sulphide in altered footwall rock below a VMS lens. It is often rich in copper. Also called stockwork."},
 {"id": "L10-g-tetrahedrite", "lecture": 10, "kind": "term", "front": "Tetrahedrite", "back": "A Cu-Fe-Ag-Sb sulphosalt. An important mineral that contains silver."},
 {"id": "L10-g-vms", "lecture": 10, "kind": "term", "front": "VMS", "back": "Volcanogenic massive sulphide: a lens of sulphide with several metals, formed on or near the seafloor from hot fluid flowing out in a volcanic setting. Also called VHMS or VAMS."},
 {"id": "L10-g-white-smoker", "lecture": 10, "kind": "term", "front": "White smoker", "back": "A cooler vent. Its plume is pale with barite, silica or anhydrite instead of metal sulphide."},
 {"id": "L10-g-zone-refining", "lecture": 10, "kind": "term", "front": "Zone refining", "back": "Later hot fluid dissolves low-temperature sulphide in the core of a mound and deposits it again at the edges."},
 {"id": "L10-cp1", "lecture": 10, "kind": "mc", "front": "What is the difference between VMS and SEDEX?", "opts": ["VMS is in volcanic rock, with fluid flowing out of volcanic hydrothermal systems. SEDEX is in sediment, with brine rising up basin faults", "VMS has no zinc", "VMS forms on land"], "ans": "VMS is in volcanic rock, with fluid flowing out of volcanic hydrothermal systems. SEDEX is in sediment, with brine rising up basin faults", "back": "Both are exhalative and form under the sea. The host rock and the fluid pathway are different."},
 {"id": "L10-cp2", "lecture": 10, "kind": "mc", "front": "Where are the largest VMS deposits?", "opts": ["Mid-ocean ridges in basalt", "Island arcs and back arcs, in felsic pyroclastic rocks", "Stable continental shields"], "ans": "Island arcs and back arcs, in felsic pyroclastic rocks", "back": "Arc settings bring more metal from the magma. All VMS settings are extensional."},
 {"id": "L10-cp3", "lecture": 10, "kind": "mc", "front": "Why is caldera collapse important for VMS?", "opts": ["It cools the magma", "It suddenly lowers the pressure in the system and opens faults that focus the fluid", "It buries the deposit too deep to mine"], "ans": "It suddenly lowers the pressure in the system and opens faults that focus the fluid", "back": "Collapse faults are the pathways, and the pressure drop drives the fluid out."},
 {"id": "L10-cp4", "lecture": 10, "kind": "mc", "front": "Where do most of the metals come from?", "opts": ["Heated seawater dissolves them from the volcanic rocks. In arcs, the magma adds extra metal", "Seawater alone", "Meteorites"], "ans": "Heated seawater dissolves them from the volcanic rocks. In arcs, the magma adds extra metal", "back": "Oceanic crust contains a lot of metal. Arc magmas add more, partly carried in vapour."},
 {"id": "L10-cp5", "lecture": 10, "kind": "mc", "front": "In an ideal mound, where is the chalcopyrite?", "opts": ["At the margin and top", "In the hot core and the stringer zone below it", "Only in the barite cap"], "ans": "In the hot core and the stringer zone below it", "back": "Cu at about 350 °C in the core and stringer zone; Zn-Pb at the cooler edge; barite on top."},
 {"id": "L10-cp6", "lecture": 10, "kind": "mc", "front": "Why does Zn:Cu increase upwards and outwards?", "opts": ["The fluid cools away from the vent. Cu is deposited first, and Zn later", "Zinc is heavier", "Seawater adds zinc"], "ans": "The fluid cools away from the vent. Cu is deposited first, and Zn later", "back": "The fluid cools step by step: from Cu-rich zones to Zn-rich zones."},
 {"id": "L10-cp7", "lecture": 10, "kind": "mc", "front": "As you get closer to VMS ore, chlorite becomes...", "opts": ["More Mg-rich and paler", "More Fe-rich and darker", "Absent"], "ans": "More Fe-rich and darker", "back": "Fe-rich, black chlorite shows the direction towards mineralisation."},
 {"id": "L10-cp8", "lecture": 10, "kind": "mc", "front": "For which metal does VMS supply the largest share of world production?", "opts": ["Gold, about 2%", "Copper, about 6%", "Zinc, about 22%"], "ans": "Zinc, about 22%", "back": "VMS supplies about 22% of the world's zinc."},
 {"id": "L10-cp9", "lecture": 10, "kind": "mc", "front": "The most widely used VMS classification is based on...", "opts": ["metal ratios only", "the volcanic and sedimentary units that formed with the deposits (lithotectonic setting)", "age"], "ans": "the volcanic and sedimentary units that formed with the deposits (lithotectonic setting)", "back": "Five types: bimodal-mafic, mafic, pelitic-mafic, bimodal-felsic, siliciclastic-felsic."},
 {"id": "L10-cp10", "lecture": 10, "kind": "mc", "front": "Pillow basalt in an ophiolite, and a massive pyrite lens above a Cu-rich stringer zone in basalt altered to chlorite. Which style is it?", "opts": ["Kuroko", "Besshi", "Cyprus"], "ans": "Cyprus", "back": "Cyprus-type: small, Cu-Zn, in mafic volcanic rocks of ophiolites, like Troodos."},
 {"id": "L10-cp11", "lecture": 10, "kind": "mc", "front": "Why are lenses like the ones at Jaguar easy to find with geophysics?", "opts": ["They are magnetic", "They are almost pure sulphide and conduct electricity, so EM surveys detect them", "They are radioactive"], "ans": "They are almost pure sulphide and conduct electricity, so EM surveys detect them", "back": "About 99% sulphide: a strong conductor."},
 {"id": "L10-st1", "lecture": 10, "kind": "q", "lvl": "Recall", "front": "Define a VMS deposit, and list its main metals and minerals.", "back": "A lens of massive sulphide with several metals. It forms on or near the seafloor from a focused flow of hot hydrothermal fluid rich in metals, in a volcanic setting. Metals: Zn, Pb, Cu, Ag, Au (and Co, Sn, Se, Mn, Cd, In, Bi, Te, Ga, Ge). Minerals: pyrite, pyrrhotite, chalcopyrite, sphalerite, galena, barite."},
 {"id": "L10-st2", "lecture": 10, "kind": "q", "lvl": "Apply", "front": "Compare VMS and SEDEX deposits.", "back": "Both are exhalative deposits formed under the sea, and together they contain most of the world's Zn and Pb. VMS: volcanic host rocks, hotter fluid (about 350 °C) flowing out of volcanic hydrothermal cells, Cu-rich cores, and truly massive sulphide. SEDEX: sedimentary host rocks, cooler brines (100 to 200 °C) rising up basin faults, and fine laminated Zn-Pb ore."},
 {"id": "L10-st3", "lecture": 10, "kind": "q", "lvl": "Recall", "front": "Which tectonic settings host VMS deposits? Which settings host the largest?", "back": "All are extensional: mid-ocean ridges and continental rifts (mafic host rocks), and island arcs and back arcs (felsic host rocks). The largest are in felsic pyroclastic rocks in arcs and back arcs."},
 {"id": "L10-st4", "lecture": 10, "kind": "q", "lvl": "Apply", "front": "Explain how a caldera helps to form a VMS deposit in an arc.", "back": "An eruption empties the chamber and the roof collapses. The pressure in the system drops instantly, and ring faults open. These faults carry seawater down and hot fluid up to the vents. New magma can reactivate the system and drive more hydrothermal cycles."},
 {"id": "L10-st5", "lecture": 10, "kind": "q", "lvl": "Recall", "front": "Describe an ideal VMS mound and its feeder.", "back": "A lens of massive sulphide with a chalcopyrite ± pyrrhotite core (~350 °C), a sphalerite ± pyrite ± galena edge (250 to 150 °C), barite on top, and often a thin silica exhalite. Below it is a Cu-rich stringer or stockwork zone in an alteration pipe with chlorite and silica."},
 {"id": "L10-st6", "lecture": 10, "kind": "q", "lvl": "Think", "front": "Why are real VMS deposits often not zoned in the ideal way?", "back": "Remobilisation: later hot fluid dissolves metals again and carries them to the edges or out into the sea. This leaves cores rich in pyrite and thin edges rich in metals. Pulses: hot and cool pulses overprint each other, so high-temperature and low-temperature minerals overlap."},
 {"id": "L10-st7", "lecture": 10, "kind": "q", "lvl": "Apply", "front": "Describe the four alteration styles around VMS ore, and how each one shows the direction to ore.", "back": "Silicification (loss of Fe, Mg, K; gain of Si, Na). Spilitisation (gain of Na, loss of Ca; chlorite becomes richer in Fe towards ore). Carbonatisation (siderite near the ore, calcite further away). Epidote-quartz (amphibole and Al-rich epidote at higher T)."},
 {"id": "L10-st8", "lecture": 10, "kind": "q", "lvl": "Recall", "front": "Name the five lithotectonic VMS types, and give one example of each.", "back": "Bimodal-mafic (Abitibi), mafic (Troodos), pelitic-mafic (Besshi, Windy Craggy), bimodal-felsic (Kuroko, Pilbara), siliciclastic-felsic (Iberian Belt, Teutonic Bore)."},
 {"id": "L10-st9", "lecture": 10, "kind": "q", "lvl": "Apply", "front": "Contrast Cyprus-, Kuroko- and Besshi-type deposits.", "back": "Cyprus: small Cu-Zn deposits in pillow basalts of ophiolites at ridges. Kuroko: small to large, high-grade Zn-Pb-Ag-Sb deposits in felsic volcanic rocks of arcs, mound-shaped, with coarse broken (clastic) sulphide. Besshi: mostly small, low-grade Cu-Zn ± Co sheets in greywacke with basalt, between VMS and SEDEX."},
 {"id": "L10-st10", "lecture": 10, "kind": "q", "lvl": "Synthesise", "front": "Use Jaguar to explain how you would explore for a VMS deposit in an Archean greenstone belt, and how you would recognise it.", "back": "Follow the favourable contact between felsic and mafic rocks along strike, because deposits occur a few kilometres apart. Use EM surveys to find massive sulphide that conducts electricity. Underground or in core, look for more Fe-chlorite, bleaching and sulphide replacing pillows, hematite flooding, and a chalcopyrite stringer zone below banded massive sulphide."},
 /* Lecture 11: 32 terms, 11 checkpoints, 10 self-test */
 {"id": "L11-g-a-vein", "lecture": 11, "kind": "term", "front": "A vein", "back": "An early, irregular, sugary quartz-K-feldspar vein with a K-feldspar halo."},
 {"id": "L11-g-argillic-alteration", "lecture": 11, "kind": "term", "front": "Argillic alteration", "back": "Clay-rich alteration that destroys plagioclase. It is above the system, and not always present."},
 {"id": "L11-g-b-vein", "lecture": 11, "kind": "term", "front": "B vein", "back": "A planar quartz vein with coarse crystals at right angles to the walls, and coarse molybdenite and chalcopyrite. No halo. It contains most of the ore."},
 {"id": "L11-g-block-caving", "lecture": 11, "kind": "term", "front": "Block caving", "back": "Underground mining where a very large block of rock is cut underneath, so it collapses under its own weight."},
 {"id": "L11-g-bornite", "lecture": 11, "kind": "term", "front": "Bornite", "back": "Cu₅FeS₄, a copper sulphide with a purple, rainbow-like tarnish."},
 {"id": "L11-g-breccia-pipe", "lecture": 11, "kind": "term", "front": "Breccia pipe", "back": "A pipe of broken rock made by an explosive release of fluid. It can contain high-grade ore."},
 {"id": "L11-g-carapace", "lecture": 11, "kind": "term", "front": "Carapace", "back": "The outer layer of a crystallising intrusion, saturated in water."},
 {"id": "L11-g-cupola", "lecture": 11, "kind": "term", "front": "Cupola", "back": "The dome-shaped top of an intrusion."},
 {"id": "L11-g-d-vein", "lecture": 11, "kind": "term", "front": "D vein", "back": "A late pyrite-anhydrite vein with a sericite halo. It cuts everything."},
 {"id": "L11-g-eb-vein", "lecture": 11, "kind": "term", "front": "EB vein", "back": "An early biotite vein, deep in the system."},
 {"id": "L11-g-enargite", "lecture": 11, "kind": "term", "front": "Enargite", "back": "Cu₃AsS₄, a copper arsenic sulphide that is common in porphyry systems."},
 {"id": "L11-g-flat-slab-subduction", "lecture": 11, "kind": "term", "front": "Flat-slab subduction", "back": "Subduction at a low angle. It is linked to the largest porphyry deposits."},
 {"id": "L11-g-hydrofracturing", "lecture": 11, "kind": "term", "front": "Hydrofracturing", "back": "Rock breaking because of fluid pressure. It makes the stockworks and breccias in porphyries."},
 {"id": "L11-g-i-type", "lecture": 11, "kind": "term", "front": "I-type", "back": "A granitoid that came from igneous source rock, not from melted sediment."},
 {"id": "L11-g-magmatic-hydrothermal", "lecture": 11, "kind": "term", "front": "Magmatic-hydrothermal", "back": "Formed by hot fluid that is released from a crystallising magma."},
 {"id": "L11-g-mantle-wedge", "lecture": 11, "kind": "term", "front": "Mantle wedge", "back": "The part of the mantle above a subducting slab. Melting with water here makes arc magma."},
 {"id": "L11-g-mash-zone", "lecture": 11, "kind": "term", "front": "MASH zone", "back": "Melting, Assimilation, Storage, Homogenisation: the zone in the lower crust where arc basalt mixes with crust and makes a mixed magma."},
 {"id": "L11-g-molybdenite", "lecture": 11, "kind": "term", "front": "Molybdenite", "back": "MoS₂. Soft, platy and lead-grey. It is the ore of molybdenum."},
 {"id": "L11-g-ore-shell", "lecture": 11, "kind": "term", "front": "Ore shell", "back": "The zone around the barren core with 1 to 3% sulphide, and more chalcopyrite than pyrite. This is the ore."},
 {"id": "L11-g-oxidised-magma", "lecture": 11, "kind": "term", "front": "Oxidised magma", "back": "A magma with high Fe³⁺/Fe²⁺ (near the hematite-magnetite buffer). It carries Cu and Au to porphyry deposits."},
 {"id": "L11-g-phenocryst", "lecture": 11, "kind": "term", "front": "Phenocryst", "back": "A large crystal in a finer-grained groundmass."},
 {"id": "L11-g-phyllic-alteration", "lecture": 11, "kind": "term", "front": "Phyllic alteration", "back": "Quartz-sericite-pyrite alteration on the sides of the deposit. It is not always present."},
 {"id": "L11-g-porphyry", "lecture": 11, "kind": "term", "front": "Porphyry", "back": "An igneous rock with large crystals (phenocrysts) in a fine groundmass. Also short for a porphyry ore deposit."},
 {"id": "L11-g-potassic-alteration", "lecture": 11, "kind": "term", "front": "Potassic alteration", "back": "K-feldspar and biotite (± magnetite) alteration in the porphyry core. It is always present."},
 {"id": "L11-g-propylitic-alteration", "lecture": 11, "kind": "term", "front": "Propylitic alteration", "back": "Chlorite-epidote-albite-calcite alteration in the outer halo. It is always present."},
 {"id": "L11-g-pyrite-shell", "lecture": 11, "kind": "term", "front": "Pyrite shell", "back": "The zone outside the ore shell, with about 10% pyrite and little chalcopyrite."},
 {"id": "L11-g-sericite", "lecture": 11, "kind": "term", "front": "Sericite", "back": "Fine white mica that forms when feldspar is altered by acidic fluid (hydrolytic alteration)."},
 {"id": "L11-g-skarn", "lecture": 11, "kind": "term", "front": "Skarn", "back": "A calc-silicate rock formed where fluid from an intrusion reacts with carbonate. It can contain Cu-Au-Fe or Pb-Zn-Ag ore."},
 {"id": "L11-g-sr-y", "lecture": 11, "kind": "term", "front": "Sr/Y", "back": "The ratio of strontium to yttrium. It is high in fertile porphyry magmas that contain a lot of water."},
 {"id": "L11-g-stockwork", "lecture": 11, "kind": "term", "front": "Stockwork", "back": "A dense network of crossing veinlets. It is the main style of ore in porphyries."},
 {"id": "L11-g-supergene-blanket", "lecture": 11, "kind": "term", "front": "Supergene blanket", "back": "The enriched chalcocite-covellite zone formed by weathering. Up to four times the primary grade."},
 {"id": "L11-g-ust", "lecture": 11, "kind": "term", "front": "UST", "back": "Unidirectional solidification texture: comb-like layers of crystals that grow down from the roof of an intrusion. They help you find ore above them."},
 {"id": "L11-cp1", "lecture": 11, "kind": "mc", "front": "Why can porphyry deposits be mined at only 0.1 to 0.5% Cu?", "opts": ["Because they are very large (hundreds to more than a thousand Mt) and are mined at a very large scale for decades", "Because copper is rare", "Because the ore is at the surface only"], "ans": "Because they are very large (hundreds to more than a thousand Mt) and are mined at a very large scale for decades", "back": "A very large scale and a long mine life make low grade profitable."},
 {"id": "L11-cp2", "lecture": 11, "kind": "mc", "front": "Which porphyry phase carries most of the copper?", "opts": ["The largest intrusion", "The earliest phase. Later phases dilute it", "The last phase"], "ans": "The earliest phase. Later phases dilute it", "back": "The volume does not predict the copper. The earliest phase does."},
 {"id": "L11-cp3", "lecture": 11, "kind": "mc", "front": "What kind of magma forms a porphyry Cu-Au deposit?", "opts": ["Reduced and highly fractionated", "Oxidised, with a lot of water, and only a little fractionated", "Dry basalt"], "ans": "Oxidised, with a lot of water, and only a little fractionated", "back": "Oxidised magma (near hematite-magnetite) keeps Cu and Au out of early sulphide minerals. Sn-W porphyries come from reduced magma."},
 {"id": "L11-cp4", "lecture": 11, "kind": "mc", "front": "Porphyritic texture means...", "opts": ["all crystals the same size", "large phenocrysts in a fine groundmass: slow growth at depth, then fast cooling at a high level", "glassy with no crystals"], "ans": "large phenocrysts in a fine groundmass: slow growth at depth, then fast cooling at a high level", "back": "The two stages of cooling of a shallow intrusion give these deposits their name."},
 {"id": "L11-cp5", "lecture": 11, "kind": "mc", "front": "If you drill outwards from the centre of a porphyry, in what order do you meet the zones?", "opts": ["Ore shell, barren core, pyrite shell", "Barren or low-grade core, ore shell, pyrite shell, propylitic halo", "Pyrite shell, ore shell, propylitic halo"], "ans": "Barren or low-grade core, ore shell, pyrite shell, propylitic halo", "back": "The ore is on the edges of the intrusion, not in its centre."},
 {"id": "L11-cp6", "lecture": 11, "kind": "mc", "front": "Which veins contain most of the porphyry ore?", "opts": ["A veins", "B veins", "D veins"], "ans": "B veins", "back": "Planar B veins with no halo, with coarse molybdenite, chalcopyrite and bornite, often in parallel sets."},
 {"id": "L11-cp7", "lecture": 11, "kind": "mc", "front": "Pink K-feldspar and hydrothermal biotite mean...", "opts": ["propylitic alteration, outer halo", "potassic alteration, the core", "argillic alteration"], "ans": "potassic alteration, the core", "back": "Potassic alteration is always present in the core. Pink K-feldspar shows iron in an oxidised system."},
 {"id": "L11-cp8", "lecture": 11, "kind": "mc", "front": "Why are Chuquicamata and El Abra on magnetic lows?", "opts": ["They are hosted in limestone", "Hydrothermal fluid destroyed the primary magnetite", "They are buried too deep"], "ans": "Hydrothermal fluid destroyed the primary magnetite", "back": "Fluid flushing removed the magnetism of the rock. A low inside a magnetic intrusion is a target."},
 {"id": "L11-cp9", "lecture": 11, "kind": "mc", "front": "What forms the porphyry stockwork?", "opts": ["Tectonic folding", "Hydrofracturing: water separates into the carapace and builds enough pressure to break the rock", "Weathering"], "ans": "Hydrofracturing: water separates into the carapace and builds enough pressure to break the rock", "back": "3 to 5% water collects in the carapace, the pressure builds, and the brittle roof breaks."},
 {"id": "L11-cp10", "lecture": 11, "kind": "mc", "front": "Compared with Cu-Au porphyries, porphyry Mo deposits come from...", "opts": ["more oxidised, less fractionated magma", "more reduced, more fractionated magma", "mantle peridotite"], "ans": "more reduced, more fractionated magma", "back": "Climax is in rhyolitic porphyry. All NSW porphyries are oxidised Cu-Au types."},
 {"id": "L11-cp11", "lecture": 11, "kind": "mc", "front": "Which stress regime is best for forming porphyry Cu deposits?", "opts": ["Pure tension", "Pure compression", "Shear, with pull-apart extensional pathways"], "ans": "Shear, with pull-apart extensional pathways", "back": "Shear focuses magma and fluid along local extensional faults."},
 {"id": "L11-st1", "lecture": 11, "kind": "q", "lvl": "Recall", "front": "What five things are needed for any magmatic-hydrothermal deposit?", "back": "A source of metals, a way to carry them, a way to concentrate them, a way to deposit them, and a later history that preserves the deposit."},
 {"id": "L11-st2", "lecture": 11, "kind": "q", "lvl": "Recall", "front": "Give the size and grade of typical porphyry deposits, and explain why they are profitable.", "back": "Many are more than 500 Mt, and some more than 1000 Mt, at 0.1 to 0.5% Cu, ~0.3 g/t Au, and up to ~0.5% Mo. They are profitable because of their very large scale and long mine life (open pit or block caving). The long mine life also balances out changes in metal prices."},
 {"id": "L11-st3", "lecture": 11, "kind": "q", "lvl": "Apply", "front": "Explain how subduction produces an oxidised porphyry magma that contains metals.", "back": "Oceanic crust with water in its minerals (amphibole, serpentine) loses its water. This releases oxidising fluid rich in Cl, S, LILE, Cu and Au into the mantle wedge, which melts. Basalt collects in a MASH zone in the lower crust and mixes with crust into a mixed calc-alkaline magma. This magma rises to form stocks at a high level."},
 {"id": "L11-st4", "lecture": 11, "kind": "q", "lvl": "Recall", "front": "Describe the Lowell and Guilbert zoning model.", "back": "A barren or low-grade potassic core with magnetite; the ore shell (1 to 3% sulphide, more cpy than py, molybdenite); the pyrite shell (~10% py) with phyllic alteration; an outer propylitic halo with Pb-Zn-Ag-Au veins on the outside; and argillic alteration above. Potassic and propylitic alteration are always present; phyllic and argillic are not always present."},
 {"id": "L11-st5", "lecture": 11, "kind": "q", "lvl": "Apply", "front": "Explain the differences between EB, A, B and D veins.", "back": "EB: early biotite veins, deep. A: early, irregular, sugary quartz-K-feldspar veins with K-feldspar halos. B: planar quartz veins with crystals at right angles to the walls, coarse molybdenite-chalcopyrite-bornite, no halo; they contain most of the ore. D: late pyrite-anhydrite veins with sericite halos, which cut everything."},
 {"id": "L11-st6", "lecture": 11, "kind": "q", "lvl": "Think", "front": "Why might a large porphyry stock contain little copper?", "back": "The volume does not control the copper. Later intrusions dilute the earliest phase, which contains the metal. Also, late sericite or chlorite-sericite fluids can remove copper that came in during potassic alteration."},
 {"id": "L11-st7", "lecture": 11, "kind": "q", "lvl": "Apply", "front": "List three exploration vectors towards porphyry ore, and explain each one.", "back": "Alteration zoning (pyrite shell outside, barren potassic core inside); UST textures (ore 100 to 200 m above, according to slide 33); high Sr/Y in fertile magmas (water suppresses plagioclase); magnetic lows where fluid destroyed magnetite in a magnetic intrusion; and the density of B veins."},
 {"id": "L11-st8", "lecture": 11, "kind": "q", "lvl": "Apply", "front": "Explain how a porphyry stockwork and breccia form.", "back": "A magma with 3 to 5% water at ~1000 °C crystallises. Water collects in a carapace saturated in water. Pressure builds until the brittle roof breaks by hydrofracturing, which makes stockwork veins and breccia pipes. Then meteoric water mixes in and drives sericitic alteration."},
 {"id": "L11-st9", "lecture": 11, "kind": "q", "lvl": "Recall", "front": "How do porphyry Mo deposits differ from porphyry Cu-Au deposits?", "back": "Their magmas are more reduced and more fractionated. There are three host types (granitic, trondhjemite, and rhyolitic like Climax). The ore is mostly stockwork molybdenite at 0.1 to 0.45% MoS₂, 50 to 1500 Mt, mainly in western North America."},
 {"id": "L11-st10", "lecture": 11, "kind": "q", "lvl": "Synthesise", "front": "Why are the central Andes the largest copper region in the world? Why are old porphyries rare?", "back": "Greatest shortening and oroclinal bending; subduction of the Juan Fernandez ridge (flat slab); repeated ore-forming events in crust that was rich in copper; and a young Cenozoic age, so the deposits are preserved. Porphyries form high in rising arcs and are eroded quickly, so Palaeozoic and older porphyries are rare."},
 /* Lecture 12: 32 terms, 11 checkpoints, 10 self-test */
 {"id": "L12-g-adularia", "lecture": 12, "kind": "term", "front": "Adularia", "back": "A low-temperature K-feldspar. It shows almost neutral, low-sulphidation epithermal systems."},
 {"id": "L12-g-alunite", "lecture": 12, "kind": "term", "front": "Alunite", "back": "A potassium aluminium sulphate. It always shows low-pH alteration."},
 {"id": "L12-g-aurostibite", "lecture": 12, "kind": "term", "front": "Aurostibite", "back": "AuSb₂, a gold-antimony alloy. Quite common in orogenic gold deposits."},
 {"id": "L12-g-bisulphide-complex", "lecture": 12, "kind": "term", "front": "Bisulphide complex", "back": "Dissolved gold bonded to HS⁻ (Au(HS)₂⁻). Most common in almost neutral, reducing, cooler fluids."},
 {"id": "L12-g-boiling", "lecture": 12, "kind": "term", "front": "Boiling", "back": "Vapour separating from a hydrothermal liquid as the pressure drops near the surface. It makes gold complexes unstable."},
 {"id": "L12-g-calaverite", "lecture": 12, "kind": "term", "front": "Calaverite", "back": "AuTe₂, the most common gold telluride."},
 {"id": "L12-g-carbon-in-pulp", "lecture": 12, "kind": "term", "front": "Carbon-in-pulp", "back": "A gold recovery method where dissolved gold sticks to activated carbon in a slurry. It made low-grade ore profitable from the 1980s."},
 {"id": "L12-g-carlin-type", "lecture": 12, "kind": "term", "front": "Carlin-type", "back": "Very fine-grained, scattered gold in silicified sedimentary rocks, mined in bulk."},
 {"id": "L12-g-chloride-complex", "lecture": 12, "kind": "term", "front": "Chloride complex", "back": "Dissolved gold bonded to chloride (AuCl₂⁻). Most common in oxidising, acidic, hotter fluids."},
 {"id": "L12-g-connate-water", "lecture": 12, "kind": "term", "front": "Connate water", "back": "Water trapped in the pores of sediment, and changed by burial."},
 {"id": "L12-g-effervescence", "lecture": 12, "kind": "term", "front": "Effervescence", "back": "An H₂O-CO₂ fluid separating into water and CO₂ as the pressure drops at depth."},
 {"id": "L12-g-electrum", "lecture": 12, "kind": "term", "front": "Electrum", "back": "A mining term for a gold-silver alloy between Au75Ag25 and Au25Ag75."},
 {"id": "L12-g-en-echelon-veins", "lecture": 12, "kind": "term", "front": "En echelon veins", "back": "Parallel, overlapping vein segments in a stepped pattern. Typical of shear zones."},
 {"id": "L12-g-epithermal", "lecture": 12, "kind": "term", "front": "Epithermal", "back": "Formed at shallow depth (surface to about 2 km) and low temperature (100 to 300 °C)."},
 {"id": "L12-g-fault-valve", "lecture": 12, "kind": "term", "front": "Fault valve", "back": "A fault that seals between earthquakes, so fluid pressure builds. Then it opens and the fluid drains out."},
 {"id": "L12-g-fluid-mixing", "lecture": 12, "kind": "term", "front": "Fluid mixing", "back": "Two fluids with different chemistry coming together, such as deep ore fluid and groundwater with oxygen. This can make gold be deposited."},
 {"id": "L12-g-hydrostatic-pressure", "lecture": 12, "kind": "term", "front": "Hydrostatic pressure", "back": "Pressure from a connected column of fluid up to the surface. It is lower than lithostatic pressure."},
 {"id": "L12-g-invisible-gold", "lecture": 12, "kind": "term", "front": "Invisible gold", "back": "Gold in tiny clusters too small to see, or inside the crystal structure of pyrite or arsenopyrite."},
 {"id": "L12-g-lithostatic-pressure", "lecture": 12, "kind": "term", "front": "Lithostatic pressure", "back": "Pressure from the weight of the rock above."},
 {"id": "L12-g-magmatic-water", "lecture": 12, "kind": "term", "front": "Magmatic water", "back": "Water that comes from magma. The hottest and saltiest fluid in the crust."},
 {"id": "L12-g-maldonite", "lecture": 12, "kind": "term", "front": "Maldonite", "back": "Au₂Bi, a gold-bismuth alloy named after Maldon, Victoria."},
 {"id": "L12-g-mesothermal", "lecture": 12, "kind": "term", "front": "Mesothermal", "back": "Formed at medium depth and temperature. Often used for orogenic gold."},
 {"id": "L12-g-metamorphic-water", "lecture": 12, "kind": "term", "front": "Metamorphic water", "back": "Water released when minerals lose water or CO₂ above about 200 °C. Low salinity, with CO₂."},
 {"id": "L12-g-meteoric-water", "lecture": 12, "kind": "term", "front": "Meteoric water", "back": "Water from the water cycle (rain, groundwater, lakes, ice). It has little dissolved material and contains oxygen."},
 {"id": "L12-g-orogenic-gold", "lecture": 12, "kind": "term", "front": "Orogenic gold", "back": "Gold deposits formed by metamorphic fluids along faults in deformed areas, 2 to 20 km deep."},
 {"id": "L12-g-paleoplacer", "lecture": 12, "kind": "term", "front": "Paleoplacer", "back": "An ancient placer preserved as hardened rock, often buried, like the Witwatersrand conglomerates."},
 {"id": "L12-g-placer", "lecture": 12, "kind": "term", "front": "Placer", "back": "A deposit of heavy minerals, such as gold, concentrated by rivers or waves."},
 {"id": "L12-g-seismic-pumping", "lecture": 12, "kind": "term", "front": "Seismic pumping", "back": "Fluid rushing up a fault each time an earthquake opens it."},
 {"id": "L12-g-telluride", "lecture": 12, "kind": "term", "front": "Telluride", "back": "A compound of tellurium. Gold tellurides include calaverite AuTe₂, petzite and sylvanite."},
 {"id": "L12-g-troy-ounce", "lecture": 12, "kind": "term", "front": "Troy ounce", "back": "The unit used to price gold: about 31.1 g. One tonne contains 32 150.7 ounces."},
 {"id": "L12-g-uraninite", "lecture": 12, "kind": "term", "front": "Uraninite", "back": "UO₂. Uraninite transported as grains in the Witwatersrand shows that the Archean atmosphere had little oxygen."},
 {"id": "L12-g-witwatersrand", "lecture": 12, "kind": "term", "front": "Witwatersrand", "back": "An Archean conglomerate basin in South Africa that has supplied about 40% of all gold ever mined."},
 {"id": "L12-cp1", "lecture": 12, "kind": "mc", "front": "Why is gold found in so many deposit types?", "opts": ["It is very common in the crust", "Different complexes can carry it over a wide range of temperature, pH and redox, and it is deposited when fluids change", "It only forms in one setting, then moves"], "ans": "Different complexes can carry it over a wide range of temperature, pH and redox, and it is deposited when fluids change", "back": "Chloride and bisulphide complexes let gold travel almost anywhere that a hydrothermal fluid goes."},
 {"id": "L12-cp2", "lecture": 12, "kind": "mc", "front": "Which deposit has supplied about 40% of all gold ever mined?", "opts": ["Kalgoorlie", "Witwatersrand", "Carlin"], "ans": "Witwatersrand", "back": "About 45 000 t since 1886."},
 {"id": "L12-cp3", "lecture": 12, "kind": "mc", "front": "About how many troy ounces are in one tonne of gold?", "opts": ["1000", "32 150", "100 000"], "ans": "32 150", "back": "32 150.7 oz, so one ounce is about 31.1 g."},
 {"id": "L12-cp4", "lecture": 12, "kind": "mc", "front": "What happens to the gold in rocks as metamorphic grade increases?", "opts": ["It increases", "It decreases: rocks in amphibolite facies contain 50 to 80% less gold than their original rocks", "It stays the same"], "ans": "It decreases: rocks in amphibolite facies contain 50 to 80% less gold than their original rocks", "back": "Metamorphic fluids remove it, and orogenic deposits collect this gold."},
 {"id": "L12-cp5", "lecture": 12, "kind": "mc", "front": "Which fluid has low salinity and carries CO₂ from minerals losing water and CO₂ above about 200 °C?", "opts": ["Seawater", "Metamorphic water", "Connate water"], "ans": "Metamorphic water", "back": "Metamorphic water: the fluid that forms orogenic gold."},
 {"id": "L12-cp6", "lecture": 12, "kind": "mc", "front": "In an almost neutral, reducing fluid at 250 °C, gold travels mainly as...", "opts": ["AuCl₂⁻", "Au(HS)₂⁻", "native gold particles"], "ans": "Au(HS)₂⁻", "back": "Bisulphide complexes are most common in almost neutral, reducing, cooler fluids."},
 {"id": "L12-cp7", "lecture": 12, "kind": "mc", "front": "Which of these is NOT a main way that gold is deposited?", "opts": ["Boiling", "Mixing with groundwater that contains oxygen", "Slowly adding more chloride while conditions stay the same"], "ans": "Slowly adding more chloride while conditions stay the same", "back": "Gold is deposited when the fluid changes: boiling, mixing, pressure drop, reaction with wall rock, cooling."},
 {"id": "L12-cp8", "lecture": 12, "kind": "mc", "front": "At what depth range do epithermal deposits form?", "opts": ["Surface to about 2 km", "5 to 20 km", "Below the Moho"], "ans": "Surface to about 2 km", "back": "Epithermal deposits are shallow, porphyries form a few kilometres down, and orogenic deposits form deeper."},
 {"id": "L12-cp9", "lecture": 12, "kind": "mc", "front": "Under the IMA 50:50 rule, a grain with 40% Au and 60% Ag is called...", "opts": ["gold", "silver", "electrum"], "ans": "silver", "back": "With less than 50% Au it is called silver. Electrum is only a mining term."},
 {"id": "L12-cp10", "lecture": 12, "kind": "mc", "front": "Which observation is difficult to explain if the Wits gold is a simple placer?", "opts": ["Rounded quartz pebbles", "There are no granite or greenstone clasts, although the basin is on granite and greenstone", "Gold in the conglomerate matrix"], "ans": "There are no granite or greenstone clasts, although the basin is on granite and greenstone", "back": "The monomictic quartz-chert-pyrite clasts are hard to explain. The best explanation is a paleoplacer that was later changed by hydrothermal fluids."},
 {"id": "L12-cp11", "lecture": 12, "kind": "mc", "front": "Why have companies returned to old goldfields?", "opts": ["To mine the low-grade material that the old miners left, using bulk methods", "Because the visible gold is still there", "Because placer gold regrows"], "ans": "To mine the low-grade material that the old miners left, using bulk methods", "back": "The old miners took the high-grade reefs. Bulk mining makes the low grade profitable."},
 {"id": "L12-st1", "lecture": 12, "kind": "q", "lvl": "Recall", "front": "List the three main groups of deposits that contain only gold, with an example of each.", "back": "Magmatic-hydrothermal (related to porphyries, and epithermal: Kidston, Lihir), metamorphic (orogenic and intrusion-related: Yilgarn, Victoria, Carlin), sedimentary (placer and paleoplacer: possibly Witwatersrand)."},
 {"id": "L12-st2", "lecture": 12, "kind": "q", "lvl": "Apply", "front": "Calculate the total value of a 20 Mt deposit at 1.5 g/t Au, at US$4000 per ounce.", "back": "20 000 000 t × 1.5 g/t = 30 000 000 g = 30 t of gold. × 32 150.7 = about 965 000 oz. × US$4000 = about US$3.9 billion in total, before costs."},
 {"id": "L12-st3", "lecture": 12, "kind": "q", "lvl": "Think", "front": "Why do igneous rocks that are not saturated in sulphur contain more gold than MORB?", "back": "Gold follows sulphide. MORB is more reduced. It becomes saturated in sulphide early and loses gold to the sulphide. Arc and ocean-island magmas that are not saturated in sulphur (more oxidised) keep the gold in the melt."},
 {"id": "L12-st4", "lecture": 12, "kind": "q", "lvl": "Recall", "front": "Name the five fluids in the crust, and give one typical property of each.", "back": "Magmatic (hottest, most salty), seawater (3.5 wt% salts, 98% of free water), meteoric (little dissolved material, contains oxygen, from rain), connate (water trapped in pores, changed by burial), metamorphic (from minerals losing water and CO₂ above ~200 °C, low salinity, CO₂)."},
 {"id": "L12-st5", "lecture": 12, "kind": "q", "lvl": "Apply", "front": "Explain why gold forms deposits over a wider range of temperature than Cu or Zn.", "back": "Gold is quite soluble at all temperatures: as bisulphide at low T and as chloride at high T. Cu and Zn are mainly soluble as chloride at high T (>250 °C), and they do not dissolve in alkaline fluid. Gold dissolves in both acidic and alkaline fluids."},
 {"id": "L12-st6", "lecture": 12, "kind": "q", "lvl": "Recall", "front": "List six ways that gold is deposited from solution.", "back": "Boiling (or effervescence at depth); mixing with groundwater with oxygen; mixing with bicarbonate water; mixing with low-pH water; a pressure drop; reaction with wall rock (neutralisation, oxidation); fast cooling."},
 {"id": "L12-st7", "lecture": 12, "kind": "q", "lvl": "Apply", "front": "Describe the fault-valve mechanism and the veins it forms.", "back": "Between earthquakes, a fault seals and fluid pressure rises from hydrostatic towards lithostatic. An earthquake breaks the fault, and the pressure drops. Fluid rushes up and effervesces or cools, and deposits quartz and gold. Repeated cycles build laminated veins and en echelon vein arrays."},
 {"id": "L12-st8", "lecture": 12, "kind": "q", "lvl": "Apply", "front": "Compare orogenic, epithermal and Carlin-type gold: setting, depth and temperature.", "back": "Orogenic: deformed metamorphic areas under compression, 2 to 20 km, 200 to 700 °C. Epithermal: arcs, surface to 2 km, 100 to 300 °C. Carlin: back arc extension after mountain building, 2 to 3 km, 200 to 300 °C, very fine gold in silicified sediments."},
 {"id": "L12-st9", "lecture": 12, "kind": "q", "lvl": "Think", "front": "Why is the composition of the gold important at Hera?", "back": "The grains contain from about 27% to 96% Au. Gold is about US$4000 and silver about US$44 an ounce, so grains with less gold are worth much less. So the value of the ore depends on knowing the gold chemistry before mining."},
 {"id": "L12-st10", "lecture": 12, "kind": "q", "lvl": "Synthesise", "front": "Summarise the evidence and the models for the origin of the Witwatersrand gold.", "back": "Quartz-pebble conglomerates with gold and uraninite in the matrix; angular fine gold; no granite or greenstone clasts; widespread alteration (pyrophyllite, chloritoid, pyrite). Paleoplacer (Frimmel) or hydrothermal (Phillips). The best fit is a paleoplacer later changed by hydrothermal fluids. Heinrich (2015): acid rain from volcanoes, rivers with no oxygen and microbial mats trapped the gold before the atmosphere had oxygen."},
 /* Lecture 13: 32 terms, 11 checkpoints, 10 self-test */
 {"id": "L13-g-amphibolite-facies", "lecture": 13, "kind": "term", "front": "Amphibolite facies", "back": "Medium to high-grade metamorphism (hornblende, plagioclase, garnet), higher than greenschist."},
 {"id": "L13-g-ankerite", "lecture": 13, "kind": "term", "front": "Ankerite", "back": "Ca(Fe,Mg)(CO₃)₂, an iron carbonate that is common in orogenic gold alteration."},
 {"id": "L13-g-aquitard", "lecture": 13, "kind": "term", "front": "Aquitard", "back": "An impermeable layer or body that holds fluid back, such as the Walhalla dolerite dyke."},
 {"id": "L13-g-arsenian-pyrite", "lecture": 13, "kind": "term", "front": "Arsenian pyrite", "back": "Pyrite with arsenic in its structure. It can contain invisible gold."},
 {"id": "L13-g-arsenopyrite", "lecture": 13, "kind": "term", "front": "Arsenopyrite", "back": "FeAsS, a silver-white arsenic sulphide. It contains gold in orogenic and Carlin deposits."},
 {"id": "L13-g-carlin-type", "lecture": 13, "kind": "term", "front": "Carlin-type", "back": "Very fine, invisible gold in pyrite that contains arsenic, in silicified sedimentary rock. Here it is treated as a type of orogenic gold."},
 {"id": "L13-g-crustal-continuum", "lecture": 13, "kind": "term", "front": "Crustal continuum", "back": "Groves' idea that orogenic gold forms at every level of the crust, from sub-greenschist to amphibolite facies."},
 {"id": "L13-g-deposit", "lecture": 13, "kind": "term", "front": "Deposit", "back": "Rock that has been mined, or that has a proven profitable resource that has not yet been mined."},
 {"id": "L13-g-field", "lecture": 13, "kind": "term", "front": "Field", "back": "A group of deposits or mines with a similar geological setting."},
 {"id": "L13-g-fuchsite", "lecture": 13, "kind": "term", "front": "Fuchsite", "back": "A bright green chromium mica. In rock altered to carbonate, it is a strong sign of orogenic gold."},
 {"id": "L13-g-greenschist-facies", "lecture": 13, "kind": "term", "front": "Greenschist facies", "back": "Low-grade metamorphism (chlorite, epidote, actinolite, albite), roughly 300 to 450 °C."},
 {"id": "L13-g-kink-fold", "lecture": 13, "kind": "term", "front": "Kink fold", "back": "A sharp, angular fold in foliated rock."},
 {"id": "L13-g-leatherjacket", "lecture": 13, "kind": "term", "front": "Leatherjacket", "back": "A thin, flat quartz vein in the Ballarat style."},
 {"id": "L13-g-lode-gold", "lecture": 13, "kind": "term", "front": "Lode gold", "back": "Gold in veins or lodes, not in placer gravels."},
 {"id": "L13-g-metamorphic-hosted", "lecture": 13, "kind": "term", "front": "Metamorphic-hosted", "back": "Hosted in metamorphosed rocks. An older name for orogenic gold."},
 {"id": "L13-g-mine", "lecture": 13, "kind": "term", "front": "Mine", "back": "An area where ore was or is being extracted."},
 {"id": "L13-g-muruntau", "lecture": 13, "kind": "term", "front": "Muruntau", "back": "In Uzbekistan. The largest orogenic gold deposit, about 150 Moz."},
 {"id": "L13-g-nugget", "lecture": 13, "kind": "term", "front": "Nugget", "back": "A lump of gold transported in a placer. Holtermann's \"nugget\" was really a quartz vein rich in gold."},
 {"id": "L13-g-orogenic-gold", "lecture": 13, "kind": "term", "front": "Orogenic gold", "back": "Gold deposits controlled by structures, formed during regional metamorphism and deformation in mountain building, 2 to 20 km deep."},
 {"id": "L13-g-post-kinematic", "lecture": 13, "kind": "term", "front": "Post-kinematic", "back": "Formed after a deformation event; the Lachlan gold veins are post-kinematic."},
 {"id": "L13-g-pre-kinematic", "lecture": 13, "kind": "term", "front": "Pre-kinematic", "back": "Formed before a deformation event."},
 {"id": "L13-g-prospect", "lecture": 13, "kind": "term", "front": "Prospect", "back": "Mineralised rock that has not yet been shown to be profitable."},
 {"id": "L13-g-regolith", "lecture": 13, "kind": "term", "front": "Regolith", "back": "The weathered and transported material above fresh bedrock. It is very thick in the Yilgarn."},
 {"id": "L13-g-retrograde-metamorphism", "lecture": 13, "kind": "term", "front": "Retrograde metamorphism", "back": "Mineral changes as metamorphic rocks cool. Most orogenic gold comes during retrograde amphibolite to greenschist conditions."},
 {"id": "L13-g-saddle-reef", "lecture": 13, "kind": "term", "front": "Saddle reef", "back": "A quartz-gold reef in the hinge of an anticline, as at Bendigo."},
 {"id": "L13-g-seismic-pumping", "lecture": 13, "kind": "term", "front": "Seismic pumping", "back": "Fluid rushing up a fault each time an earthquake opens it."},
 {"id": "L13-g-sericite", "lecture": 13, "kind": "term", "front": "Sericite", "back": "Fine white mica formed when feldspar breaks down. Common in gold alteration."},
 {"id": "L13-g-silicification", "lecture": 13, "kind": "term", "front": "Silicification", "back": "Replacement of rock by silica. It is strong in Carlin-type deposits."},
 {"id": "L13-g-subsidiary-structure", "lecture": 13, "kind": "term", "front": "Subsidiary structure", "back": "A smaller fault or shear zone that branches off a major crustal fault. Most orogenic gold is on these structures."},
 {"id": "L13-g-syn-kinematic", "lecture": 13, "kind": "term", "front": "Syn-kinematic", "back": "Formed during a deformation event."},
 {"id": "L13-g-transpression", "lecture": 13, "kind": "term", "front": "Transpression", "back": "Compression together with strike-slip (sideways) movement."},
 {"id": "L13-g-workings", "lecture": 13, "kind": "term", "front": "Workings", "back": "Excavations made only to find or extract ore."},
 {"id": "L13-cp1", "lecture": 13, "kind": "mc", "front": "What makes a deposit \"orogenic\" gold?", "opts": ["Gold in river gravels", "Gold controlled by structures, formed during regional metamorphism and deformation in mountain building", "Gold in a porphyry stock"], "ans": "Gold controlled by structures, formed during regional metamorphism and deformation in mountain building", "back": "Veins and lodes along structures, 2 to 20 km deep, in settings with compression to transpression."},
 {"id": "L13-cp2", "lecture": 13, "kind": "mc", "front": "When does most orogenic gold arrive?", "opts": ["During peak amphibolite metamorphism", "During retrograde amphibolite-to-greenschist conditions, often up to 100 Myr after the main mountain building", "Before any deformation"], "ans": "During retrograde amphibolite-to-greenschist conditions, often up to 100 Myr after the main mountain building", "back": "Gold comes late in the orogenic cycle."},
 {"id": "L13-cp3", "lecture": 13, "kind": "mc", "front": "Which Precambrian craton has produced over 50 Moz of orogenic gold?", "opts": ["Yilgarn", "Kaapvaal", "Pilbara"], "ans": "Yilgarn", "back": "Together with the Superior and West African cratons, it is one of the three largest."},
 {"id": "L13-cp4", "lecture": 13, "kind": "mc", "front": "Why was Holtermann's \"nugget\" not a real nugget?", "opts": ["It was gold-plated", "It was a slab of quartz vein full of gold, not a lump transported in a placer", "It was found at sea"], "ans": "It was a slab of quartz vein full of gold, not a lump transported in a placer", "back": "A 3000 oz piece of vein from Hawkins Hill, 1872."},
 {"id": "L13-cp5", "lecture": 13, "kind": "mc", "front": "Where is Yilgarn gold usually found?", "opts": ["On the main crustal faults", "On smaller structures that branch off the large faults, often where structures cross", "Only in granite"], "ans": "On smaller structures that branch off the large faults, often where structures cross", "back": "Structure and timing matter more than host rock."},
 {"id": "L13-cp6", "lecture": 13, "kind": "mc", "front": "At Bendigo, where are the saddle reefs?", "opts": ["In the hinges of anticlines", "In syncline troughs only", "In the granite"], "ans": "In the hinges of anticlines", "back": "Anticline hinges close the top and trap the fluid."},
 {"id": "L13-cp7", "lecture": 13, "kind": "mc", "front": "At Stawell, why is the gold concentrated around the basalt dome?", "opts": ["Basalt holds the most gold", "Rigid basalt hardly deforms, while the sediments fold around it. This opens spaces that fill with veins", "The basalt is younger"], "ans": "Rigid basalt hardly deforms, while the sediments fold around it. This opens spaces that fill with veins", "back": "The difference in rock strength opens space (dilation)."},
 {"id": "L13-cp8", "lecture": 13, "kind": "mc", "front": "Muruntau is famous as...", "opts": ["the largest orogenic gold deposit (~150 Moz) and the largest open-cut gold mine", "a Carlin-type deposit", "a paleoplacer"], "ans": "the largest orogenic gold deposit (~150 Moz) and the largest open-cut gold mine", "back": "Found from soil As-Au anomalies in 1958. Mined since 1967."},
 {"id": "L13-cp9", "lecture": 13, "kind": "mc", "front": "According to this lecture, where does the orogenic gold itself come from?", "opts": ["Meteorites", "Tiny inclusions in pyrite in carbonaceous mudstones and shales, released during metamorphism", "Seawater"], "ans": "Tiny inclusions in pyrite in carbonaceous mudstones and shales, released during metamorphism", "back": "The fluids may come from granites. The gold is collected from the country rocks."},
 {"id": "L13-cp10", "lecture": 13, "kind": "mc", "front": "Why can you not see the gold in Carlin ore?", "opts": ["It is in tellurides", "It is invisible, locked in pyrite rims that contain arsenic", "It weathered away"], "ans": "It is invisible, locked in pyrite rims that contain arsenic", "back": "You see the arsenic and antimony minerals, not the gold."},
 {"id": "L13-cp11", "lecture": 13, "kind": "mc", "front": "At Tuena, which generation of veins contains the gold?", "opts": ["Early, pre-kinematic, rootless veins", "Folded syn-kinematic veins", "Late, post-kinematic, flat, carbonate-rich veins"], "ans": "Late, post-kinematic, flat, carbonate-rich veins", "back": "This is typical across the Lachlan: the gold comes late."},
 {"id": "L13-st1", "lecture": 13, "kind": "q", "lvl": "Recall", "front": "Define orogenic gold and give its main features.", "back": "Vein (lode) gold controlled by structures, formed during regional metamorphism and deformation in mountain building. Margins with compression to transpression. 200 to 700 °C, 2 to 20 km. Dilute H₂O-CO₂ ± CH₄, N₂ fluids. Quartz veins with carbonate, sericite, arsenopyrite, pyrite, ± fuchsite. Archean to Mesozoic."},
 {"id": "L13-st2", "lecture": 13, "kind": "q", "lvl": "Apply", "front": "Explain the \"crustal continuum\".", "back": "Orogenic gold forms at every level of the crust, from sub-greenschist to amphibolite facies. At shallow levels there are brittle veins and breccias, in the middle there are brittle-ductile shears, and deep down there are ductile shear zones. Au-Sb is shallow, and Au-As (-W) is deep."},
 {"id": "L13-st3", "lecture": 13, "kind": "q", "lvl": "Think", "front": "Why do orogenic orebodies extend a long way vertically, but not far sideways?", "back": "They form in large, deep, steep faults and shear zones. So the ore follows the structure down for kilometres, but stays narrow. Some Kalgoorlie mines go deeper than 2 km."},
 {"id": "L13-st4", "lecture": 13, "kind": "q", "lvl": "Apply", "front": "Compare the Yilgarn and Victorian goldfields.", "back": "Yilgarn: Archean (2.7 Ga) granites and greenstones. Gold in mafic volcanic rocks, BIF and granite, on smaller structures, with deep regolith. Victoria: Palaeozoic Lachlan turbidites in greenschist facies, with little visible alteration. Zones bounded by faults, saddle reefs (Bendigo), control by bedding and cleavage (Ballarat). Gold is Ordovician to Devonian."},
 {"id": "L13-st5", "lecture": 13, "kind": "q", "lvl": "Apply", "front": "Why is Bendigo's gold in anticline hinges?", "back": "Folding opens spaces in anticline hinges. The hinges also act as traps that close the top and stop rising fluid. Shear zones that cut across them feed fluid into them, which forms saddle reefs."},
 {"id": "L13-st6", "lecture": 13, "kind": "q", "lvl": "Apply", "front": "What controls the gold around dolerite dykes and basalt domes?", "back": "They are rigid and impermeable. Fluid is stopped against them (aquitard). Also, the difference in strength between them and the deforming sediments opens spaces along their edges, as at Walhalla and Stawell."},
 {"id": "L13-st7", "lecture": 13, "kind": "q", "lvl": "Think", "front": "Summarise the evidence for the sources of the fluid and the gold in orogenic deposits.", "back": "Fluids: magmatic sulphur isotopes and granite trace elements (Bi, Te, As, Mo, Sb, Sn, W) suggest buried granites, although the older view is metamorphic fluids. Gold: tiny inclusions in pyrite in carbonaceous mudstones, released during metamorphism. Sampling lines in Finland show gold increasing towards deposits."},
 {"id": "L13-st8", "lecture": 13, "kind": "q", "lvl": "Apply", "front": "How are Carlin-type deposits different from typical orogenic deposits?", "back": "Hosted in sub-greenschist argillites and limestones, 2 to 3 km, 200 to 300 °C, during Cenozoic back-arc extension. Strong silicification and some kaolinisation. Invisible gold in pyrite rims that contain arsenic. Mined in bulk by open cut."},
 {"id": "L13-st9", "lecture": 13, "kind": "q", "lvl": "Apply", "front": "Calculate the value of Bendigo's 700 000 kg of gold at US$4000 an ounce.", "back": "700 000 kg = 700 t × 32 150.7 oz/t = about 22.5 Moz × US$4000 = about US$90 billion (the slide gives about US$120 billion, at a higher price)."},
 {"id": "L13-st10", "lecture": 13, "kind": "q", "lvl": "Synthesise", "front": "Use Tuena to explain how you would decide which veins to target in an orogenic goldfield.", "back": "Map the generations of veins, using cross-cutting relationships and deformation: early pre-kinematic rootless veins, syn-kinematic folded veins, and late post-kinematic flat carbonate veins that cut the foliation. In the Lachlan, the gold is in the late set. So target late veins that are not deformed, along smaller faults in the main structural corridor."},
 /* Lecture 14: 31 terms, 11 checkpoints, 10 self-test */
 {"id": "L14-g-adularia", "lecture": 14, "kind": "term", "front": "Adularia", "back": "A low-temperature K-feldspar, typical of low sulphidation veins."},
 {"id": "L14-g-advanced-argillic", "lecture": 14, "kind": "term", "front": "Advanced argillic", "back": "Acid alteration with alunite, kaolinite, dickite, pyrophyllite."},
 {"id": "L14-g-alunite", "lecture": 14, "kind": "term", "front": "Alunite", "back": "KAl₃(SO₄)₂(OH)₆. It always means low pH."},
 {"id": "L14-g-bonanza", "lecture": 14, "kind": "term", "front": "Bonanza", "back": "Extremely rich ore, with more than about 1 kg of gold or silver per tonne."},
 {"id": "L14-g-breccia", "lecture": 14, "kind": "term", "front": "Breccia", "back": "Rock made of broken angular fragments."},
 {"id": "L14-g-caldera", "lecture": 14, "kind": "term", "front": "Caldera", "back": "A collapsed volcanic depression. Epithermal deposits are found in groups along caldera edges."},
 {"id": "L14-g-chalcedony", "lecture": 14, "kind": "term", "front": "Chalcedony", "back": "Microcrystalline quartz deposited quickly at low temperature."},
 {"id": "L14-g-crack-seal", "lecture": 14, "kind": "term", "front": "Crack-seal", "back": "A vein that opens and seals again and again. Each time, a new band is added."},
 {"id": "L14-g-diatreme", "lecture": 14, "kind": "term", "front": "Diatreme", "back": "A volcanic pipe filled with breccia, formed by a phreatomagmatic eruption."},
 {"id": "L14-g-enargite", "lecture": 14, "kind": "term", "front": "Enargite", "back": "Cu₃AsS₄. The typical copper mineral of high sulphidation systems."},
 {"id": "L14-g-epithermal", "lecture": 14, "kind": "term", "front": "Epithermal", "back": "Formed at shallow depth (surface to about 3 km) and low temperature, in volcanic settings."},
 {"id": "L14-g-floating-clast-breccia", "lecture": 14, "kind": "term", "front": "Floating clast breccia", "back": "A vein breccia with wall-rock fragments inside the vein filling."},
 {"id": "L14-g-free-milling-gold", "lecture": 14, "kind": "term", "front": "Free-milling gold", "back": "Native gold that is released by grinding and is easy to recover."},
 {"id": "L14-g-geyser", "lecture": 14, "kind": "term", "front": "Geyser", "back": "A hot spring that erupts water and steam from time to time."},
 {"id": "L14-g-ginguro", "lecture": 14, "kind": "term", "front": "Ginguro", "back": "Japanese for \"silver-black\": dark bands of very fine sulphide (silver minerals, gold) in banded epithermal veins."},
 {"id": "L14-g-halloysite", "lecture": 14, "kind": "term", "front": "Halloysite", "back": "A kaolin-group clay. Hypogene halloysite in ore suggests mixing with acidic water and a high grade."},
 {"id": "L14-g-high-sulphidation", "lecture": 14, "kind": "term", "front": "High sulphidation", "back": "Epithermal style formed from salty, acidic magmatic fluid rich in SO₂. Vughy silica, alunite, enargite."},
 {"id": "L14-g-hypogene", "lecture": 14, "kind": "term", "front": "Hypogene", "back": "Formed by rising hydrothermal fluid, not by weathering."},
 {"id": "L14-g-intermediate-sulphidation", "lecture": 14, "kind": "term", "front": "Intermediate sulphidation", "back": "Between high and low sulphidation. More base metals (sphalerite, galena, tetrahedrite)."},
 {"id": "L14-g-lithocap", "lecture": 14, "kind": "term", "front": "Lithocap", "back": "A large layer of advanced argillic alteration above a porphyry."},
 {"id": "L14-g-low-sulphidation", "lecture": 14, "kind": "term", "front": "Low sulphidation", "back": "Epithermal style formed from dilute, almost neutral H₂S fluid. Adularia-sericite, banded quartz."},
 {"id": "L14-g-luzonite", "lecture": 14, "kind": "term", "front": "Luzonite", "back": "The low-temperature polymorph of enargite."},
 {"id": "L14-g-milled-matrix-breccia", "lecture": 14, "kind": "term", "front": "Milled matrix breccia", "back": "Breccia with rounded fragments in a finely ground (milled) matrix. Typical of diatremes."},
 {"id": "L14-g-phreatic", "lecture": 14, "kind": "term", "front": "Phreatic", "back": "Driven by steam, when groundwater is heated but no new magma reaches the surface."},
 {"id": "L14-g-phreatomagmatic", "lecture": 14, "kind": "term", "front": "Phreatomagmatic", "back": "Explosive reaction between magma and groundwater. It forms diatremes."},
 {"id": "L14-g-platy-calcite", "lecture": 14, "kind": "term", "front": "Platy calcite", "back": "Blade-shaped calcite formed during boiling. It is often replaced by quartz, and is a sign of boiling."},
 {"id": "L14-g-refractory-gold", "lecture": 14, "kind": "term", "front": "Refractory gold", "back": "Gold locked in sulphides such as enargite or arsenopyrite. It needs extra processing."},
 {"id": "L14-g-roscoelite", "lecture": 14, "kind": "term", "front": "Roscoelite", "back": "A green vanadium mica found with bonanza gold at Porgera."},
 {"id": "L14-g-sinter", "lecture": 14, "kind": "term", "front": "Sinter", "back": "A siliceous deposit formed around hot springs at the surface."},
 {"id": "L14-g-steam-heated-alteration", "lecture": 14, "kind": "term", "front": "Steam-heated alteration", "back": "A barren acid sulphate layer (kaolin, alunite, opal) formed above the water table by condensed H₂S."},
 {"id": "L14-g-vughy-silica", "lecture": 14, "kind": "term", "front": "Vughy silica", "back": "Porous silica left when extremely acidic fluid dissolves everything else. The core of HS systems."},
 {"id": "L14-cp1", "lecture": 14, "kind": "mc", "front": "Which is typical of epithermal deposits?", "opts": ["Large tonnage (>500 Mt) at low grade", "Small tonnage (<50 Mt) but high grade, with bonanza ore common", "Formed at 15 km depth"], "ans": "Small tonnage (<50 Mt) but high grade, with bonanza ore common", "back": "Small and rich, from the surface to ~3 km."},
 {"id": "L14-cp2", "lecture": 14, "kind": "mc", "front": "Why is the 80 ppm gold crust at Champagne Pool not mined?", "opts": ["The gold is fake", "There is no volume to exploit", "It is all silver"], "ans": "There is no volume to exploit", "back": "High grade, but a very small volume: a living system, not a deposit."},
 {"id": "L14-cp3", "lecture": 14, "kind": "mc", "front": "At Round Mountain, what focused the ore?", "opts": ["Impermeable tuff above permeable tuff", "A dolerite dyke", "Seafloor venting"], "ans": "Impermeable tuff above permeable tuff", "back": "The difference in permeability is the main control."},
 {"id": "L14-cp4", "lecture": 14, "kind": "mc", "front": "Which breccia forms when the pressure in a geothermal system drops at the surface?", "opts": ["Magmatic", "Phreatomagmatic", "Phreatic"], "ans": "Phreatic", "back": "Phreatic eruption breccias, as at Champagne Pool and McLaughlin."},
 {"id": "L14-cp5", "lecture": 14, "kind": "mc", "front": "High sulphidation fluid is...", "opts": ["dilute, near neutral, H₂S", "saline, acid, SO₂", "pure seawater"], "ans": "saline, acid, SO₂", "back": "Magmatic vapour close to the intrusion. LS fluid is dilute, almost neutral and contains H₂S."},
 {"id": "L14-cp6", "lecture": 14, "kind": "mc", "front": "What is vughy silica?", "opts": ["Quartz grown into open veins", "Porous silica left after acid dissolved everything else", "A hot spring sinter"], "ans": "Porous silica left after acid dissolved everything else", "back": "The core of high sulphidation alteration. A trap for later gold and enargite."},
 {"id": "L14-cp7", "lecture": 14, "kind": "mc", "front": "Banded quartz-adularia veins with less than 2% sulphide show...", "opts": ["high sulphidation", "low sulphidation", "porphyry"], "ans": "low sulphidation", "back": "Classic LS, as at Hishikari."},
 {"id": "L14-cp8", "lecture": 14, "kind": "mc", "front": "According to Corbett, which process gives the highest gold grades?", "opts": ["Boiling", "Slow cooling", "Mixing with acidic sulphate waters with low pH"], "ans": "Mixing with acidic sulphate waters with low pH", "back": "Shown by hypogene kaolin and halloysite in the ore."},
 {"id": "L14-cp9", "lecture": 14, "kind": "mc", "front": "A layer of powdery alunite, kaolin and opal above the water table, with no gold, is most likely...", "opts": ["steam-heated acid sulphate alteration", "the core of a HS deposit", "propylitic alteration"], "ans": "steam-heated acid sulphate alteration", "back": "Barren steam-heated alteration that looks like HS."},
 {"id": "L14-cp10", "lecture": 14, "kind": "mc", "front": "What caused the epithermal gold at Lihir?", "opts": ["Burial under lava", "Collapse of one side of the volcano at 0.34 Ma removed ~1 km of rock. The pressure dropped and the fluid boiled", "Glaciation"], "ans": "Collapse of one side of the volcano at 0.34 Ma removed ~1 km of rock. The pressure dropped and the fluid boiled", "back": "Gold from 0.336 Ma to today, overprinting the earlier porphyry."},
 {"id": "L14-cp11", "lecture": 14, "kind": "mc", "front": "Epithermal deposits are often hard to understand because...", "opts": ["they are always deeply buried", "they record several episodes of mineralisation and alteration", "they contain no gold"], "ans": "they record several episodes of mineralisation and alteration", "back": "Often they are only understood after mining."},
 {"id": "L14-st1", "lecture": 14, "kind": "q", "lvl": "Recall", "front": "List five characteristics of epithermal deposits.", "back": "Volcanic host rocks in arcs and back arcs (rhyolite to dacite); surface to ~3 km; small (<50 Mt) but high grade, with common bonanza ore; in groups around calderas; deposited by boiling and fluid mixing; Au, Au-Ag or Ag; illite-muscovite and adularia alteration; Archean to active today."},
 {"id": "L14-st2", "lecture": 14, "kind": "q", "lvl": "Apply", "front": "Explain why permeability is so important in epithermal systems. Give an example.", "back": "Fluid must be focused to concentrate metal. Permeable layers, breccias and structures that open guide the fluid, and impermeable caps hold it in. At Round Mountain, impermeable tuff above permeable tuff focused the ore."},
 {"id": "L14-st3", "lecture": 14, "kind": "q", "lvl": "Apply", "front": "Compare magmatic, phreatomagmatic and phreatic breccias.", "back": "Magmatic: violent release of volatiles from an intrusion, deep, and does not need to reach the surface (Kidston). Phreatomagmatic: magma meets groundwater; diatremes with a milled matrix that reach the surface (Wau, Kelian). Phreatic: the pressure of a geothermal system drops; eruption breccias at the surface (Champagne Pool, McLaughlin)."},
 {"id": "L14-st4", "lecture": 14, "kind": "q", "lvl": "Recall", "front": "Compare high and low sulphidation systems: fluid, alteration and ore minerals.", "back": "HS: salty, acidic SO₂ fluid; vughy silica, alunite, kaolinite, illite, a lot of pyrite; enargite-luzonite, Au > Ag + Cu. LS: dilute, almost neutral H₂S fluid; adularia-sericite, illite, quartz, carbonate; <2% sulphide (pyrite, sphalerite, galena, Ag sulphosalts), Au > Ag."},
 {"id": "L14-st5", "lecture": 14, "kind": "q", "lvl": "Apply", "front": "How does vughy silica form, and why is it important for gold?", "back": "Condensed magmatic SO₂ and HCl make extremely acidic water. It dissolves everything except silica, and leaves porous silica. The pores trap later gold-enargite fluid that is rich in liquid (the two-stage model)."},
 {"id": "L14-st6", "lecture": 14, "kind": "q", "lvl": "Apply", "front": "Describe the textures of a low sulphidation vein and what they record.", "back": "Banded quartz, chalcedony and adularia (crack-seal: the vein opened again and again, and the fluid changed each time); dark ginguro bands with chalcedony; quartz that replaced platy calcite (boiling); floating clast breccias (repeated fracturing); and gold in certain bands or in the vein centre."},
 {"id": "L14-st7", "lecture": 14, "kind": "q", "lvl": "Think", "front": "Rank Corbett's deposition processes by gold grade, and give the evidence for each.", "back": "Slow cooling (coarse sulphides, low Au) < boiling (mostly gangue: adularia, quartz replacing platy calcite) < fast cooling (fine sulphides, opal on sulphides) ≈ mixing with groundwater with oxygen (hypogene hematite) < mixing with bicarbonate water (carbonate-base metal) < mixing with low-pH water (hypogene kaolin, halloysite, highest grades)."},
 {"id": "L14-st8", "lecture": 14, "kind": "q", "lvl": "Think", "front": "Why must you be careful with a layer of acid sulphate alteration?", "back": "Steam-heated alteration above the water table (kaolin, powdery alunite, opal) looks like high sulphidation advanced argillic alteration, but it is barren. It can be above a low sulphidation system and can mislead you."},
 {"id": "L14-st9", "lecture": 14, "kind": "q", "lvl": "Recall", "front": "Summarise the Lihir deposit and what caused its gold.", "back": "Luise caldera, Lihir Island, PNG. 649 Mt at 2.25 g/t Au. Monzonite porphyries in andesitic-latitic volcanic rocks. Active geothermal system. Potassic alteration 0.917 to 0.342 Ma. Collapse of one side of the volcano at 0.34 Ma removed ~1 km of rock, which lowered the pressure and caused boiling. Epithermal gold since 0.336 Ma."},
 {"id": "L14-st10", "lecture": 14, "kind": "q", "lvl": "Synthesise", "front": "Place porphyry, high sulphidation, low sulphidation and steam-heated alteration in one volcanic system.", "back": "Porphyry stock at depth (1 to 5 km). HS lithocap and vughy silica above it and near it, fed by magmatic vapour. LS veins further out, where meteoric water dilutes the fluid. Intermediate sulphidation between them. A steam-heated acid sulphate layer above the water table. Hot springs and sinter at the surface."},
 /* Lecture 15: 32 terms, 11 checkpoints, 10 self-test */
 {"id": "L15-g-alluvial", "lecture": 15, "kind": "term", "front": "Alluvial", "back": "Deposited by rivers. Much of the tin in eastern Australia was mined from alluvial cassiterite."},
 {"id": "L15-g-artisanal-mining", "lecture": 15, "kind": "term", "front": "Artisanal mining", "back": "Small-scale mining by individuals or small groups, often unofficial."},
 {"id": "L15-g-beryl", "lecture": 15, "kind": "term", "front": "Beryl", "back": "Be₃Al₂Si₆O₁₈. Aquamarine is the blue variety."},
 {"id": "L15-g-bismuthinite", "lecture": 15, "kind": "term", "front": "Bismuthinite", "back": "Bi₂S₃, lead-grey, soft, needle-shaped. The main bismuth ore."},
 {"id": "L15-g-cassiterite", "lecture": 15, "kind": "term", "front": "Cassiterite", "back": "SnO₂, the main tin ore: adamantine lustre, hard (6 to 7), very dense (SG ~7), black to brown."},
 {"id": "L15-g-ferberite", "lecture": 15, "kind": "term", "front": "Ferberite", "back": "FeWO₄, the iron end of the wolframite series. Black. Typical of eastern Australia."},
 {"id": "L15-g-ferrimolybdite", "lecture": 15, "kind": "term", "front": "Ferrimolybdite", "back": "A bright yellow, powdery mineral that forms when molybdenite is altered."},
 {"id": "L15-g-fluorite", "lecture": 15, "kind": "term", "front": "Fluorite", "back": "CaF₂, a common gangue mineral in deposits related to granites."},
 {"id": "L15-g-fractionation", "lecture": 15, "kind": "term", "front": "Fractionation", "back": "A change in magma composition when minerals crystallise and are removed. It leaves incompatible elements, like Sn, in the last melt."},
 {"id": "L15-g-greisen", "lecture": 15, "kind": "term", "front": "Greisen", "back": "Granite in which more than 90% of the feldspar has been replaced by muscovite and quartz, often with topaz, tourmaline and cassiterite."},
 {"id": "L15-g-hornfels", "lecture": 15, "kind": "term", "front": "Hornfels", "back": "A fine-grained rock heated (baked) by contact metamorphism next to an intrusion."},
 {"id": "L15-g-h-bnerite", "lecture": 15, "kind": "term", "front": "Hübnerite", "back": "MnWO₄, the manganese end of the wolframite series. Red-brown."},
 {"id": "L15-g-ilmenite-series", "lecture": 15, "kind": "term", "front": "Ilmenite series", "back": "Reduced granites with ilmenite and no magnetite. Linked to Sn-W deposits."},
 {"id": "L15-g-ilsemannite", "lecture": 15, "kind": "term", "front": "Ilsemannite", "back": "A pale blue mineral that forms when molybdenite is altered."},
 {"id": "L15-g-knee-twin", "lecture": 15, "kind": "term", "front": "Knee twin", "back": "A twinned crystal bent at an angle, like a knee. Common in cassiterite."},
 {"id": "L15-g-magnetite-series", "lecture": 15, "kind": "term", "front": "Magnetite series", "back": "Oxidised granites with magnetite. Linked to Mo-W deposits."},
 {"id": "L15-g-metaluminous", "lecture": 15, "kind": "term", "front": "Metaluminous", "back": "Having Al less than Na + K + 2Ca but more than Na + K."},
 {"id": "L15-g-molybdenite", "lecture": 15, "kind": "term", "front": "Molybdenite", "back": "MoS₂, the only molybdenum ore: very soft, flexible, platy, lead grey."},
 {"id": "L15-g-native-bismuth", "lecture": 15, "kind": "term", "front": "Native bismuth", "back": "Bismuth metal. Cream to reddish white, soft, very dense."},
 {"id": "L15-g-needle-tin", "lecture": 15, "kind": "term", "front": "Needle tin", "back": "Thin, prismatic cassiterite crystals."},
 {"id": "L15-g-peraluminous", "lecture": 15, "kind": "term", "front": "Peraluminous", "back": "Having Al/(Na + K + 2Ca) > 1. The extra Al is in muscovite, garnet, cordierite and topaz."},
 {"id": "L15-g-ruby-tin", "lecture": 15, "kind": "term", "front": "Ruby tin", "back": "Red, transparent cassiterite."},
 {"id": "L15-g-s-type-granite", "lecture": 15, "kind": "term", "front": "S-type granite", "back": "A granite formed by melting sedimentary rock. Usually peraluminous."},
 {"id": "L15-g-scheelite", "lecture": 15, "kind": "term", "front": "Scheelite", "back": "CaWO₄, a pale tungsten mineral that glows bright blue-white under UV light."},
 {"id": "L15-g-schorl", "lecture": 15, "kind": "term", "front": "Schorl", "back": "Black tourmaline rich in iron. A boron mineral that is common in granite systems."},
 {"id": "L15-g-sheeted-veins", "lecture": 15, "kind": "term", "front": "Sheeted veins", "back": "Many closely spaced parallel veins."},
 {"id": "L15-g-stannite", "lecture": 15, "kind": "term", "front": "Stannite", "back": "Cu₂FeSnS₄, a grey metallic tin sulphide. It forms in reduced systems rich in sulphide."},
 {"id": "L15-g-topaz", "lecture": 15, "kind": "term", "front": "Topaz", "back": "Al₂SiO₄(F,OH)₂, a silicate that contains fluorine. Common in Sn-W greisens."},
 {"id": "L15-g-topazite", "lecture": 15, "kind": "term", "front": "Topazite", "back": "A rock made mostly of topaz. An extreme type of greisen."},
 {"id": "L15-g-volatile", "lecture": 15, "kind": "term", "front": "Volatile", "back": "A component like H₂O, Cl, F, B or CO₂ that goes into the fluid as magma crystallises."},
 {"id": "L15-g-wolframite", "lecture": 15, "kind": "term", "front": "Wolframite", "back": "The (Fe,Mn)WO₄ series between ferberite and hübnerite. Heavy, dark, blade-shaped."},
 {"id": "L15-g-wood-tin", "lecture": 15, "kind": "term", "front": "Wood tin", "back": "Fibrous, colloform banded cassiterite that looks like wood."},
 {"id": "L15-cp1", "lecture": 15, "kind": "mc", "front": "What is tin’s main use?", "opts": ["Coins", "Solder in electronics, about half of all tin", "Steel hardening"], "ans": "Solder in electronics, about half of all tin", "back": "No better replacement has been found. Tin is a critical mineral in many countries."},
 {"id": "L15-cp2", "lecture": 15, "kind": "mc", "front": "Which tin mineral forms in reduced systems rich in sulphide?", "opts": ["Cassiterite", "Stannite", "Wood tin"], "ans": "Stannite", "back": "Stannite, Cu₂FeSnS₄, with chalcopyrite, pyrite, sphalerite and tetrahedrite."},
 {"id": "L15-cp3", "lecture": 15, "kind": "mc", "front": "How can you find scheelite quickly in the field?", "opts": ["By its magnetism", "With a UV lamp at night: it glows blue-white", "By its red streak"], "ans": "With a UV lamp at night: it glows blue-white", "back": "Scheelite glows strongly under UV light."},
 {"id": "L15-cp4", "lecture": 15, "kind": "mc", "front": "Bright yellow powder on weathered molybdenum ore is probably...", "opts": ["ferrimolybdite", "scheelite", "sulphur"], "ans": "ferrimolybdite", "back": "Molybdenite changes to yellow ferrimolybdite where there is iron and water, or to blue ilsemannite."},
 {"id": "L15-cp5", "lecture": 15, "kind": "mc", "front": "Etched, frosted topaz in a Sn-W deposit tells you...", "opts": ["it was transported in a river", "later low-pH fluids partly dissolved it", "it is synthetic"], "ans": "later low-pH fluids partly dissolved it", "back": "There were several hydrothermal pulses, and some were very acidic."},
 {"id": "L15-cp6", "lecture": 15, "kind": "mc", "front": "A very heavy, hard, black mineral with an adamantine lustre and knee-shaped twins is...", "opts": ["wolframite", "cassiterite", "molybdenite"], "ans": "cassiterite", "back": "Cassiterite: H 6 to 7, SG ~7, knee twins."},
 {"id": "L15-cp7", "lecture": 15, "kind": "mc", "front": "Which granite series goes with Sn-W deposits?", "opts": ["Magnetite series", "Ilmenite series", "Neither"], "ans": "Ilmenite series", "back": "Ilmenite series: Sn-W; magnetite series: Mo-W."},
 {"id": "L15-cp8", "lecture": 15, "kind": "mc", "front": "Why are there tin replacement deposits, but tungsten replacement deposits are rare?", "opts": ["Tungsten is not dissolved", "Almost all the tungsten is deposited between 350 and 300 °C, but tin is deposited by many chemical processes", "Tin is lighter"], "ans": "Almost all the tungsten is deposited between 350 and 300 °C, but tin is deposited by many chemical processes", "back": "W is controlled by temperature. Sn reacts with wall rock, feldspar and carbonate."},
 {"id": "L15-cp9", "lecture": 15, "kind": "mc", "front": "What defines a greisen?", "opts": ["A granite with more feldspar", "A granite where >90% of the feldspar has been replaced by muscovite and quartz", "A volcanic breccia"], "ans": "A granite where >90% of the feldspar has been replaced by muscovite and quartz", "back": "Often with topaz, tourmaline and cassiterite."},
 {"id": "L15-cp10", "lecture": 15, "kind": "mc", "front": "How are the metals zoned around the Mole Granite?", "opts": ["W in the core, Sn at the edge", "Sn in the core, W along the edge, and Ag-Zn-Pb in the country rock", "All metals mixed evenly"], "ans": "Sn in the core, W along the edge, and Ag-Zn-Pb in the country rock", "back": "All within the top 200 m of the granite."},
 {"id": "L15-cp11", "lecture": 15, "kind": "mc", "front": "Why is the Tallebung ore easy to process?", "opts": ["It is oxidised", "Coarse, dense cassiterite and ferberite in quartz can be separated by gravity after crushing", "It is liquid"], "ans": "Coarse, dense cassiterite and ferberite in quartz can be separated by gravity after crushing", "back": "Few sulphides, and coarse heavy minerals: gravity separation."},
 {"id": "L15-st1", "lecture": 15, "kind": "q", "lvl": "Recall", "front": "Why is tin a critical mineral? Where does Australia's tin come from?", "back": "About half of all tin is used as solder in all electronics, and there is no replacement. Supply comes from few places, and 40% is from small-scale miners. Australia's main producer is Renison Bell, Tasmania (≥180 kt Sn). The largest proven deposit in NSW is Taronga (22 Mt at 0.16% Sn)."},
 {"id": "L15-st2", "lecture": 15, "kind": "q", "lvl": "Recall", "front": "Describe cassiterite and three of its varieties.", "back": "SnO₂, tetragonal, adamantine lustre, H 6 to 7, SG ~7, black to brown. Varieties: needle tin (prismatic), wood tin (fibrous and banded), ruby tin (red), knee twins. It also occurs as alluvial grains and pseudomorphs."},
 {"id": "L15-st3", "lecture": 15, "kind": "q", "lvl": "Apply", "front": "How can you tell scheelite from wolframite in hand specimen?", "back": "Scheelite: pale (white, yellow, brown), vitreous to adamantine lustre, H 4.5 to 5, SG 6.1, glows blue-white under UV. Wolframite: dark brown to black or red-brown, metallic to submetallic, blade-shaped, SG 7.1 to 7.6, does not glow."},
 {"id": "L15-st4", "lecture": 15, "kind": "q", "lvl": "Recall", "front": "What are the ore minerals of Bi and Mo, and the minerals they change to when altered?", "back": "Bi: bismuthinite (Bi₂S₃) and native bismuth. Mo: molybdenite (MoS₂), which changes to yellow ferrimolybdite and blue ilsemannite."},
 {"id": "L15-st5", "lecture": 15, "kind": "q", "lvl": "Recall", "front": "What kinds of granites form vein and greisen Sn-W-Mo deposits?", "back": "Granites that intruded at a high level (1.5 to 5 km), rich in K, metaluminous to peraluminous, and highly fractionated (high Rb/Sr). Mostly in Phanerozoic orogenic belts. The magnetite series forms Mo-W, and the ilmenite series forms Sn-W."},
 {"id": "L15-st6", "lecture": 15, "kind": "q", "lvl": "Apply", "front": "Explain the roles of H₂O, Cl, F, B and Li in these systems.", "back": "The magma must be undersaturated in water (<3 wt%) to rise high. Cl carries Sn, W, Mo and base metals as chloride complexes. F, B and Li lower the melting temperature and let fractionation continue to low temperatures. F and B also make H₂O and Cl more soluble, so volatiles separate at a lower pressure."},
 {"id": "L15-st7", "lecture": 15, "kind": "q", "lvl": "Apply", "front": "Compare how tin and tungsten are deposited from hydrothermal fluid.", "back": "W depends strongly on temperature: 99% is deposited between 350 and 300 °C. Sn is deposited by mixing with meteoric water, separation of vapour, reaction with wall rock, reaction with feldspars, and replacement of carbonate. So Sn replacement deposits are common, and W replacement deposits are rare."},
 {"id": "L15-st8", "lecture": 15, "kind": "q", "lvl": "Recall", "front": "What is a greisen, and where does it form?", "back": "Granite with >90% of the feldspar replaced by muscovite and quartz, often with topaz, tourmaline and cassiterite. From millimetres to metres wide. Usually where a younger granite rich in fluid intrudes an older granite, along the contact."},
 {"id": "L15-st9", "lecture": 15, "kind": "q", "lvl": "Apply", "front": "Describe the zoning around the Mole Granite, and what caused it.", "back": "Sn in the core, W along the edge, and Ag-Zn-Pb in the country rock, all in the top 200 m. Magmatic fluid cooled from 600 to 200 °C and mixed with meteoric water as it moved outwards. Each metal was deposited in its own range of temperature and chemistry."},
 {"id": "L15-st10", "lecture": 15, "kind": "q", "lvl": "Synthesise", "front": "Use Tallebung to explain why old tin fields are worth exploring again.", "back": "Early miners took supergene silver and alluvial or shallow tin. Later sluicing exposed the veins. Today there is demand for Sn and W, the ore is simple and can be recovered by gravity, the veins continue to at least 500 m, and there is a granite at depth that has not been drilled. So it is worth exploring with modern methods."},
 /* Lecture 16: 35 terms, 11 checkpoints, 10 self-test */
 {"id": "L16-g-acanthite", "lecture": 16, "kind": "term", "front": "Acanthite", "back": "Ag₂S, the common silver sulphide at low temperature."},
 {"id": "L16-g-basinal-brine", "lecture": 16, "kind": "term", "front": "Basinal brine", "back": "Warm, salty water that circulates through a sedimentary basin."},
 {"id": "L16-g-batholith", "lecture": 16, "kind": "term", "front": "Batholith", "back": "A very large body of intrusive granite, often made of many plutons."},
 {"id": "L16-g-bleaching", "lecture": 16, "kind": "term", "front": "Bleaching", "back": "Pale alteration caused by loss of iron. In CMPV it can extend for kilometres, so it is a better guide to ore than the narrow zones next to veins."},
 {"id": "L16-g-cerussite", "lecture": 16, "kind": "term", "front": "Cerussite", "back": "PbCO₃, a lead carbonate in oxide zones."},
 {"id": "L16-g-chalcocite", "lecture": 16, "kind": "term", "front": "Chalcocite", "back": "Cu₂S, a sulphide rich in copper. A main Kupferschiefer ore."},
 {"id": "L16-g-cmpv", "lecture": 16, "kind": "term", "front": "CMPV", "back": "Polymetallic vein hosted in clastic metasediment: Ag-Pb-Zn veins in deformed, metamorphosed clastic sediments, far from granites."},
 {"id": "L16-g-cockade", "lecture": 16, "kind": "term", "front": "Cockade", "back": "Round bands that grew around breccia fragments."},
 {"id": "L16-g-colloform", "lecture": 16, "kind": "term", "front": "Colloform", "back": "Rounded, finely banded growths, as in colloform sphalerite."},
 {"id": "L16-g-comb-texture", "lecture": 16, "kind": "term", "front": "Comb texture", "back": "Crystals that grew at right angles to the vein walls, pointing inwards."},
 {"id": "L16-g-connate-water", "lecture": 16, "kind": "term", "front": "Connate water", "back": "Pore water trapped in sediment, and changed by burial."},
 {"id": "L16-g-covellite", "lecture": 16, "kind": "term", "front": "Covellite", "back": "CuS. Strong indigo-blue colour in reflected light."},
 {"id": "L16-g-crustiform", "lecture": 16, "kind": "term", "front": "Crustiform", "back": "Banding in a vein, with layers that grew inwards from the walls."},
 {"id": "L16-g-dendritic", "lecture": 16, "kind": "term", "front": "Dendritic", "back": "Branching growth, like a tree, as in dendritic galena."},
 {"id": "L16-g-diagenetic", "lecture": 16, "kind": "term", "front": "Diagenetic", "back": "Formed while the sediment is being compacted and hardened."},
 {"id": "L16-g-dissolution-collapse-breccia", "lecture": 16, "kind": "term", "front": "Dissolution collapse breccia", "back": "A breccia that forms when carbonate dissolves and the rock above collapses into the empty space."},
 {"id": "L16-g-dolomitisation", "lecture": 16, "kind": "term", "front": "Dolomitisation", "back": "Replacement of calcite by dolomite. An MVT and Irish alteration."},
 {"id": "L16-g-epigenetic", "lecture": 16, "kind": "term", "front": "Epigenetic", "back": "Formed after the host rock. Here, tens to hundreds of millions of years later."},
 {"id": "L16-g-exsolution", "lecture": 16, "kind": "term", "front": "Exsolution", "back": "One mineral separating from another during cooling, like stannite spots in sphalerite."},
 {"id": "L16-g-framboidal-pyrite", "lecture": 16, "kind": "term", "front": "Framboidal pyrite", "back": "Raspberry-shaped spheres of tiny pyrite crystals. Typical of sediment rich in organic matter and affected by bacteria."},
 {"id": "L16-g-freibergite", "lecture": 16, "kind": "term", "front": "Freibergite", "back": "Silver-rich tetrahedrite, named after Freiberg, Germany. It usually forms late."},
 {"id": "L16-g-irish-type", "lecture": 16, "kind": "term", "front": "Irish-type", "back": "Zn-Pb hosted in carbonate, with features of both SEDEX and MVT. It forms during diagenesis along normal faults."},
 {"id": "L16-g-kupferschiefer", "lecture": 16, "kind": "term", "front": "Kupferschiefer", "back": "Thin stratiform copper hosted in sediment, in reduced shale above oxidised red beds. Named after the German-Polish \"copper shale\"."},
 {"id": "L16-g-marcasite", "lecture": 16, "kind": "term", "front": "Marcasite", "back": "FeS₂, the low-temperature polymorph of pyrite."},
 {"id": "L16-g-mesothermal", "lecture": 16, "kind": "term", "front": "Mesothermal", "back": "Medium depth and temperature. CMPV forms at about 6 km and 250 to 300 °C."},
 {"id": "L16-g-mvt", "lecture": 16, "kind": "term", "front": "MVT", "back": "Mississippi Valley-type: epigenetic Zn-Pb that replaces platform carbonates. It forms from low-temperature basin brines and is not linked to igneous rocks."},
 {"id": "L16-g-pyrargyrite", "lecture": 16, "kind": "term", "front": "Pyrargyrite", "back": "Ag₃SbS₃, a deep red silver sulphosalt (\"ruby silver\")."},
 {"id": "L16-g-pyromorphite", "lecture": 16, "kind": "term", "front": "Pyromorphite", "back": "A green lead chlorophosphate in oxide zones."},
 {"id": "L16-g-red-beds", "lecture": 16, "kind": "term", "front": "Red beds", "back": "Oxidised continental sediments coloured red by hematite."},
 {"id": "L16-g-redox-front", "lecture": 16, "kind": "term", "front": "Redox front", "back": "The boundary between oxidised and reduced rocks, where Kupferschiefer copper is deposited."},
 {"id": "L16-g-smithsonite", "lecture": 16, "kind": "term", "front": "Smithsonite", "back": "ZnCO₃, a zinc carbonate in oxide zones."},
 {"id": "L16-g-stratabound", "lecture": 16, "kind": "term", "front": "Stratabound", "back": "Stays in one stratigraphic unit, but does not always follow its layering exactly."},
 {"id": "L16-g-stratiform", "lecture": 16, "kind": "term", "front": "Stratiform", "back": "Following the layering of the host rock."},
 {"id": "L16-g-syngenetic", "lecture": 16, "kind": "term", "front": "Syngenetic", "back": "Formed at the same time as the host sediment."},
 {"id": "L16-g-tetrahedrite-tennantite", "lecture": 16, "kind": "term", "front": "Tetrahedrite-tennantite", "back": "Cu-Fe-Sb-As sulphosalts that often contain silver."},
 {"id": "L16-cp1", "lecture": 16, "kind": "mc", "front": "Which of the four groups is clearly linked to a granite?", "opts": ["MVT", "CMPV", "Kupferschiefer"], "ans": "CMPV", "back": "CMPV veins are far from batholiths but linked to them. MVT and Kupferschiefer have no link to igneous rocks."},
 {"id": "L16-cp2", "lecture": 16, "kind": "mc", "front": "In what conditions do CMPV deposits usually form?", "opts": ["Surface, <100 °C", "About 6 km, 250 to 300 °C, controlled by structures", "At the base of the crust, 800 °C"], "ans": "About 6 km, 250 to 300 °C, controlled by structures", "back": "Mesothermal, like orogenic gold."},
 {"id": "L16-cp3", "lecture": 16, "kind": "mc", "front": "What did deeper drilling at Webbs start to find?", "opts": ["Gold", "Wolframite and cassiterite, towards the granite", "Diamonds"], "ans": "Wolframite and cassiterite, towards the granite", "back": "Ag-Pb-Zn far from the granite, and Sn-W closer to it: one continuous system."},
 {"id": "L16-cp4", "lecture": 16, "kind": "mc", "front": "Why is wall-rock alteration not a good guide to CMPV ore?", "opts": ["There is none", "It only extends a few metres from the veins. Bleaching over kilometres is better", "It is invisible"], "ans": "It only extends a few metres from the veins. Bleaching over kilometres is better", "back": "Look for hydrothermal bleaching (loss of Fe)."},
 {"id": "L16-cp5", "lecture": 16, "kind": "mc", "front": "In the CMPV model related to intrusions, what does the intrusion supply?", "opts": ["Metals and fluid", "Only heat to drive convection", "Nothing"], "ans": "Only heat to drive convection", "back": "The metals and fluids come from meteoric and metamorphic water from the country rock."},
 {"id": "L16-cp6", "lecture": 16, "kind": "mc", "front": "Which statement fits MVT deposits?", "opts": ["Syngenetic, 300 °C, near granites", "Epigenetic, mostly 90 to 150 °C, basin brines, no link to igneous rocks", "Volcanic-hosted massive sulphide"], "ans": "Epigenetic, mostly 90 to 150 °C, basin brines, no link to igneous rocks", "back": "Low-temperature brines in platform carbonates."},
 {"id": "L16-cp7", "lecture": 16, "kind": "mc", "front": "What makes the sulphides be deposited in an MVT?", "opts": ["Boiling", "Oxidised brine with metals meets organic matter and hydrocarbons (redox)", "Seawater H₂S at the seafloor"], "ans": "Oxidised brine with metals meets organic matter and hydrocarbons (redox)", "back": "The redox reaction makes the chloride or sulphate complexes unstable."},
 {"id": "L16-cp8", "lecture": 16, "kind": "mc", "front": "Irish-type deposits are different from MVTs because they...", "opts": ["form during diagenesis, are linked to volcanism, and form along normal faults", "are hosted in granite", "have no zinc"], "ans": "form during diagenesis, are linked to volcanism, and form along normal faults", "back": "Also, barite is common and fluorite is rare."},
 {"id": "L16-cp9", "lecture": 16, "kind": "mc", "front": "Where is Kupferschiefer copper deposited?", "opts": ["In the red beds", "At the redox boundary between oxidised red beds and reduced shale", "In a granite"], "ans": "At the redox boundary between oxidised red beds and reduced shale", "back": "Zoning: hematite → chalcocite → bornite → chalcopyrite → pyrite."},
 {"id": "L16-cp10", "lecture": 16, "kind": "mc", "front": "What is mined at Manuka?", "opts": ["Copper sulphide", "Silver in oxidised Fe-Mn clays above the limestone", "Gold in quartz veins"], "ans": "Silver in oxidised Fe-Mn clays above the limestone", "back": "Clays left from weathered limestone keep the silver."},
 {"id": "L16-cp11", "lecture": 16, "kind": "mc", "front": "Thin copper ore in black shale directly above hematite-rich, wind-blown sandstone is...", "opts": ["CMPV", "Kupferschiefer", "MVT"], "ans": "Kupferschiefer", "back": "Redox boundary at the contact with the red beds."},
 {"id": "L16-st1", "lecture": 16, "kind": "q", "lvl": "Recall", "front": "Define a CMPV deposit and give the conditions in which it forms.", "back": "Ag-Pb-Zn (± Cu, Sn) veins in clastic metasediments in greenschist facies, far from batholiths, but not related to porphyries. Mesothermal, ~6 km and 250 to 300 °C, 0 to 26 wt% salinity, strongly controlled by structures, late in the history of mountain building."},
 {"id": "L16-st2", "lecture": 16, "kind": "q", "lvl": "Apply", "front": "Compare Webbs and Conrad.", "back": "Both are in the southern New England Orogen. Conrad: 458 000 t at 600 g/t Ag, 8% Pb, 4% Zn, 1.5% Cu, 1.5% Sn, hosted in granite. Webbs: 1.49 Mt at 245 g/t Ag, 0.71% Pb, 1.56% Zn, 0.27% Cu, in dark metasiltstone away from the granite. Deeper drilling finds wolframite and cassiterite."},
 {"id": "L16-st3", "lecture": 16, "kind": "q", "lvl": "Recall", "front": "What are the ore and gangue minerals of CMPV deposits?", "back": "Galena, sphalerite, tetrahedrite-tennantite (freibergite); minor pyrite, chalcopyrite, arsenopyrite, stibnite, native silver and Ag sulphosalts (pyrargyrite, stephanite, bournonite). Gangue: quartz and siderite, with minor dolomite, ankerite, calcite, barite, fluorite and magnetite."},
 {"id": "L16-st4", "lecture": 16, "kind": "q", "lvl": "Apply", "front": "Describe the three models for how CMPV deposits form.", "back": "Magmatic differentiation (volatile fluid from a fractionating magma, rich in Ag, Pb, Zn and Cu, with mafic and lamprophyre dykes). Deep crustal faults (fluid from deep sources, with boiling and mixing with meteoric water in smaller structures). Related to intrusions (the intrusion only provides heat; the metals and fluids come from meteoric and metamorphic waters). Probably a mix of these."},
 {"id": "L16-st5", "lecture": 16, "kind": "q", "lvl": "Recall", "front": "List the main features of MVT deposits.", "back": "Epigenetic; 50 to 250 °C, mostly 90 to 150 °C; not linked to igneous rocks; stratabound, in some places stratiform; basin brines with 10 to 30 wt% NaCl; hosted in platform carbonates in the forelands of orogens; districts with many deposits; average ~7 Mt at 7.9% Pb + Zn."},
 {"id": "L16-st6", "lecture": 16, "kind": "q", "lvl": "Apply", "front": "Explain how an MVT ore body forms.", "back": "Tectonic squeezing, compaction or a change in sea level drives connate basin brine with metals (dissolved from basin sediments) up aquifers to platform carbonates. Acidic fluid dissolves carbonate and makes collapse breccias. Where the oxidised brine meets organic matter or hydrocarbons, redox reactions make the metal complexes unstable, and sphalerite and galena are deposited."},
 {"id": "L16-st7", "lecture": 16, "kind": "q", "lvl": "Think", "front": "Why are MVTs in dolostone larger and richer than MVTs in limestone?", "back": "Fluid usually flows through dolostone more easily (higher transmissivity), so more brine passes through. The exception is the large, high-grade Navan deposit, which is in limestone."},
 {"id": "L16-st8", "lecture": 16, "kind": "q", "lvl": "Apply", "front": "Compare the two models for how Irish-type deposits form.", "back": "Syngenetic deposition on the seafloor: stratiform shape, bedded and broken sulphides, similar ages. Diagenetic to epigenetic replacement: replacement and open-space textures, few laminated sulphides, alteration above the lenses, no oxidation on the seafloor."},
 {"id": "L16-st9", "lecture": 16, "kind": "q", "lvl": "Recall", "front": "Describe the setting and zoning of Kupferschiefer deposits.", "back": "Rifts inside continents, within 20 to 30° of the old equator, at the boundary between oxidised wind-blown red beds and reduced shales, carbonates and evaporites. From the red beds into the reduced ore: hematite, chalcocite, bornite, chalcopyrite, pyrite, with Pb-Zn near the chalcopyrite and pyrite zones."},
 {"id": "L16-st10", "lecture": 16, "kind": "q", "lvl": "Synthesise", "front": "Why is Manuka described as a \"hot\" MVT, and what is actually mined?", "back": "Inclusions in calcite give 80 to 110 °C, which is typical of MVT. But smoky quartz in holes, which grew during tectonic events, gives ~220 °C. The mine takes silver from Fe-Mn oxide clays left after the impure limestone weathered, not from the primary sulphides."},
 /* Lecture 17: 25 terms, 11 checkpoints, 9 self-test */
 {"id": "L17-g-autunite", "lecture": 17, "kind": "term", "front": "Autunite", "back": "Ca(UO₂)₂(PO₄)₂·10-12H₂O, bright green secondary uranium phosphate."},
 {"id": "L17-g-brannerite", "lecture": 17, "kind": "term", "front": "Brannerite", "back": "A complex U-Ti oxide that is hard and expensive to leach."},
 {"id": "L17-g-calcrete", "lecture": 17, "kind": "term", "front": "Calcrete", "back": "Carbonate-cemented sediment that forms in dry climates; hosts carnotite deposits."},
 {"id": "L17-g-carnotite", "lecture": 17, "kind": "term", "front": "Carnotite", "back": "K₂(UO₂)₂(VO₄)₂·3H₂O, bright yellow; the calcrete ore mineral."},
 {"id": "L17-g-coffinite", "lecture": 17, "kind": "term", "front": "Coffinite", "back": "A uranium silicate; primary, common in sandstone deposits."},
 {"id": "L17-g-disequilibrium", "lecture": 17, "kind": "term", "front": "Disequilibrium", "back": "When the daughters have moved away from their uranium (or vice versa), so gamma readings no longer show the uranium grade."},
 {"id": "L17-g-half-life", "lecture": 17, "kind": "term", "front": "Half-life", "back": "The time for half of a radioactive isotope to decay."},
 {"id": "L17-g-iocg", "lecture": 17, "kind": "term", "front": "IOCG", "back": "Iron oxide copper-gold deposit, such as Olympic Dam."},
 {"id": "L17-g-isl", "lecture": 17, "kind": "term", "front": "ISL", "back": "In situ leaching: dissolving uranium in the aquifer through wells, without digging."},
 {"id": "L17-g-oklo", "lecture": 17, "kind": "term", "front": "Oklo", "back": "A natural nuclear reactor in Gabon that ran about 2 billion years ago, when ²³⁵U was above 3%."},
 {"id": "L17-g-oxyphilic", "lecture": 17, "kind": "term", "front": "Oxyphilic", "back": "Strongly bonding to oxygen. Uranium always occurs with oxygen, never as a sulphide."},
 {"id": "L17-g-palaeochannel", "lecture": 17, "kind": "term", "front": "Palaeochannel", "back": "An old river channel, often buried; a common host for sandstone uranium."},
 {"id": "L17-g-pitchblende", "lecture": 17, "kind": "term", "front": "Pitchblende", "back": "U₃O₈, massive or microcrystalline uraninite; the chief ore mineral."},
 {"id": "L17-g-qpc", "lecture": 17, "kind": "term", "front": "QPC", "back": "Quartz-pebble conglomerate with detrital uraninite, formed before oxygen rose."},
 {"id": "L17-g-radiometric-equilibrium", "lecture": 17, "kind": "term", "front": "Radiometric equilibrium", "back": "When all daughters in a decay chain are present in the amounts expected from their parent uranium."},
 {"id": "L17-g-radiometrics", "lecture": 17, "kind": "term", "front": "Radiometrics", "back": "Measuring natural gamma radiation from K, U (²¹⁴Bi) and Th (²⁰⁸Tl), often from the air."},
 {"id": "L17-g-reductant", "lecture": 17, "kind": "term", "front": "Reductant", "back": "A material that reduces U⁶⁺ to U⁴⁺: organic matter, pyrite, graphite."},
 {"id": "L17-g-roll-front", "lecture": 17, "kind": "term", "front": "Roll front", "back": "A crescent-shaped uranium ore body at the moving boundary between oxidised and reduced sandstone."},
 {"id": "L17-g-smr", "lecture": 17, "kind": "term", "front": "SMR", "back": "Small modular reactor."},
 {"id": "L17-g-unconformity-deposit", "lecture": 17, "kind": "term", "front": "Unconformity deposit", "back": "High-grade uranium at a Proterozoic unconformity between basement and sandstone; Athabasca, Alligator Rivers."},
 {"id": "L17-g-uraninite", "lecture": 17, "kind": "term", "front": "Uraninite", "back": "UO₂, the black primary uranium oxide."},
 {"id": "L17-g-uranophane", "lecture": 17, "kind": "term", "front": "Uranophane", "back": "A yellow secondary calcium uranium silicate."},
 {"id": "L17-g-uranous", "lecture": 17, "kind": "term", "front": "Uranous", "back": "The reduced U⁴⁺ ion; insoluble."},
 {"id": "L17-g-uranyl", "lecture": 17, "kind": "term", "front": "Uranyl", "back": "The oxidised UO₂²⁺ ion of U⁶⁺; soluble and mobile."},
 {"id": "L17-g-yellowcake", "lecture": 17, "kind": "term", "front": "Yellowcake", "back": "The bright yellow uranium concentrate produced by processing."},
 {"id": "L17-cp1", "lecture": 17, "kind": "mc", "front": "Why is uranium useful for electricity?", "opts": ["It is renewable", "It is carbon-free and can supply base load", "It is the cheapest fuel"], "ans": "It is carbon-free and can supply base load", "back": "Renewables suit peak daytime demand; base load is still mostly coal and gas."},
 {"id": "L17-cp2", "lecture": 17, "kind": "mc", "front": "What does the \"uranium channel\" of a gamma spectrometer actually detect?", "opts": ["²³⁸U directly", "²¹⁴Bi, a uranium daughter", "⁴⁰K"], "ans": "²¹⁴Bi, a uranium daughter", "back": "So disequilibrium can mislead you."},
 {"id": "L17-cp3", "lecture": 17, "kind": "mc", "front": "In which state does uranium move in groundwater?", "opts": ["U⁴⁺, as uraninite", "U⁶⁺ (uranyl), mainly as carbonate complexes", "As a sulphide"], "ans": "U⁶⁺ (uranyl), mainly as carbonate complexes", "back": "It drops out when reduced to U⁴⁺."},
 {"id": "L17-cp4", "lecture": 17, "kind": "mc", "front": "A bright yellow coating on weathered calcrete. Which mineral is most likely?", "opts": ["Pitchblende", "Carnotite", "Autunite"], "ans": "Carnotite", "back": "Autunite is green; pitchblende is black."},
 {"id": "L17-cp5", "lecture": 17, "kind": "mc", "front": "Why could detrital uraninite survive in Archean to earliest Proterozoic gravels?", "opts": ["Rivers were faster", "There was little oxygen, so uraninite did not oxidise and dissolve", "It was coated in gold"], "ans": "There was little oxygen, so uraninite did not oxidise and dissolve", "back": "Hence the quartz-pebble conglomerate deposits."},
 {"id": "L17-cp6", "lecture": 17, "kind": "mc", "front": "Why is Olympic Dam special for uranium?", "opts": ["Highest grade on Earth", "The largest economic uranium resource, but uranium is a by-product of Cu-Au", "It is an unconformity deposit"], "ans": "The largest economic uranium resource, but uranium is a by-product of Cu-Au", "back": "More than 10 billion tonnes of ore."},
 {"id": "L17-cp7", "lecture": 17, "kind": "mc", "front": "What reduces the uranium in unconformity deposits?", "opts": ["Seawater", "Graphitic units in the basement", "Calcrete"], "ans": "Graphitic units in the basement", "back": "Graphite also shows as an electrical conductor."},
 {"id": "L17-cp8", "lecture": 17, "kind": "mc", "front": "Where does a roll front deposit form?", "opts": ["In the oxidised sandstone behind the front", "At the reducing edge of the front, where oxidised water meets organic matter and pyrite", "In the basement granite"], "ans": "At the reducing edge of the front, where oxidised water meets organic matter and pyrite", "back": "The front migrates downstream."},
 {"id": "L17-cp9", "lecture": 17, "kind": "mc", "front": "Why can calcrete ore not easily be acid-leached?", "opts": ["It is too deep", "It is full of carbonate, which uses up the acid", "It has no uranium"], "ans": "It is full of carbonate, which uses up the acid", "back": "Grades are 100 to 1500 ppm."},
 {"id": "L17-cp10", "lecture": 17, "kind": "mc", "front": "Which is an advantage of in situ leaching?", "opts": ["It needs a deep pit", "Almost no tailings and no broken rock", "It works on any rock"], "ans": "Almost no tailings and no broken rock", "back": "It needs a permeable aquifer between clays."},
 {"id": "L17-cp11", "lecture": 17, "kind": "mc", "front": "A 20% U₃O₈ pod at a sandstone-basement contact next to graphitic gneiss in Saskatchewan is...", "opts": ["A roll front", "An unconformity deposit", "A calcrete deposit"], "ans": "An unconformity deposit", "back": "Like Cigar Lake."},
 {"id": "L17-st1", "lecture": 17, "kind": "q", "lvl": "Recall", "front": "List the uranium isotopes and their abundances. Why could Oklo happen 2 Ga ago but not today?", "back": "²³⁸U 99.27% (half-life 4.47 Ga), ²³⁵U 0.72% (0.7 Ga), ²³⁴U 0.0055%. ²³⁵U decays faster, so 2 Ga ago it was above 3%, enough for natural fission. Today it is 0.720%; Oklo has 0.717% because some was used up."},
 {"id": "L17-st2", "lecture": 17, "kind": "q", "lvl": "Apply", "front": "Explain the three channels of a gamma-ray spectrometer and the problem of disequilibrium.", "back": "K = ⁴⁰K; U = ²¹⁴Bi; Th = ²⁰⁸Tl. Daughters (Ra, Rn, Bi) behave differently from U and can separate from it, so gamma readings may not match the uranium; only assays give the grade."},
 {"id": "L17-st3", "lecture": 17, "kind": "q", "lvl": "Recall", "front": "Describe the behaviour of U⁴⁺ and U⁶⁺.", "back": "U⁴⁺ (uranous): insoluble, forms uraninite, pitchblende, coffinite in magmas and reduced sediments. U⁶⁺ (uranyl): soluble in acid and alkaline water, transported mainly as carbonate complexes; forms bright secondary minerals; precipitates when reduced or when it reacts with V, P or Si oxyanions."},
 {"id": "L17-st4", "lecture": 17, "kind": "q", "lvl": "Recall", "front": "Name three primary and three secondary uranium minerals.", "back": "Primary: pitchblende (U₃O₈), uraninite (UO₂), coffinite. Secondary: carnotite (yellow, K-U vanadate), autunite (green, Ca-U phosphate), uranophane (yellow, Ca-U silicate), tyuyamunite."},
 {"id": "L17-st5", "lecture": 17, "kind": "q", "lvl": "Apply", "front": "Explain the three main ages of uranium deposits.", "back": "Earliest Proterozoic (QPC with detrital uraninite, low O₂); middle Proterozoic (unconformity deposits, after O₂ allowed U transport); Cretaceous to Recent (sandstone and surficial deposits, after land plants supplied reductants). All continental."},
 {"id": "L17-st6", "lecture": 17, "kind": "q", "lvl": "Recall", "front": "Describe Olympic Dam.", "back": "Hematite-rich granite breccia complex in the Gawler Craton under ~300 m of Stuart Shelf sediments; ~1590 Ma (Hiltaba Suite); > 10 Bt at 0.82% Cu, 0.31 g/t Au, 0.26 kg/t U₃O₈, 1.5 g/t Ag; ~66% of Australian U resources; uranium is a by-product."},
 {"id": "L17-st7", "lecture": 17, "kind": "q", "lvl": "Apply", "front": "Explain how unconformity deposits form and compare Athabasca with Alligator Rivers.", "back": "Basin brines carrying oxidised U flow through sandstone and along faults at the unconformity; graphitic basement reduces it. Athabasca: ore below, across and above the unconformity, richest at or above it (Cigar Lake ~20% U₃O₈). Alligator Rivers: below the unconformity, lower grade, less explored."},
 {"id": "L17-st8", "lecture": 17, "kind": "q", "lvl": "Apply", "front": "Draw and explain a roll front.", "back": "Oxidised water from a weathered source carries U⁶⁺ through a confined sandstone aquifer. At the boundary with reduced sandstone (organic matter, pyrite), U is reduced and precipitates as uraninite or coffinite in a crescent. U behind the front is re-oxidised and moved forward, so the front migrates."},
 {"id": "L17-st9", "lecture": 17, "kind": "q", "lvl": "Synthesise", "front": "Why is in situ leaching used for sandstone deposits but not calcrete deposits?", "back": "Sandstone ore sits in a permeable aquifer confined by clays, so acid can be pumped through and recovered. Calcrete ore is high in carbonate, which consumes acid, and it is thin and shallow over large areas."},
 /* Lecture 18: 32 terms, 11 checkpoints, 9 self-test */
 {"id": "L18-g-anatase", "lecture": 18, "kind": "term", "front": "Anatase", "back": "A form of TiO₂. Common in the critical element ash beds."},
 {"id": "L18-g-brine", "lecture": 18, "kind": "term", "front": "Brine", "back": "Very salty water. Lithium brines are hypersaline, 1.7 to 24 times saltier than seawater."},
 {"id": "L18-g-carbonatite", "lecture": 18, "kind": "term", "front": "Carbonatite", "back": "An igneous rock made mostly of carbonate minerals. The main source of niobium (and many REE)."},
 {"id": "L18-g-carrollite", "lecture": 18, "kind": "term", "front": "Carrollite", "back": "A copper-cobalt sulphide in the African Copperbelt ores."},
 {"id": "L18-g-coal-ash", "lecture": 18, "kind": "term", "front": "Coal ash", "back": "What is left after coal is burnt. Elements become more concentrated in it."},
 {"id": "L18-g-cobaltite", "lecture": 18, "kind": "term", "front": "Cobaltite", "back": "CoAsS, the main primary cobalt mineral. The cobalt version of arsenopyrite."},
 {"id": "L18-g-cookeite", "lecture": 18, "kind": "term", "front": "Cookeite", "back": "A lithium chlorite. Found in pegmatites and in coal; its lithium can be extracted economically."},
 {"id": "L18-g-critical-element", "lecture": 18, "kind": "term", "front": "Critical element", "back": "An element in great demand now or soon, with a risk to its future supply. Each country makes its own list. Industry calls them critical minerals."},
 {"id": "L18-g-elip", "lecture": 18, "kind": "term", "front": "ELIP", "back": "Emeishan Large Igneous Province, south-west China, about 260 million years old."},
 {"id": "L18-g-erythrite", "lecture": 18, "kind": "term", "front": "Erythrite", "back": "Co₃(AsO₄)₂·8H₂O, purple-pink \"cobalt bloom\" in oxide zones."},
 {"id": "L18-g-eucryptite", "lecture": 18, "kind": "term", "front": "Eucryptite", "back": "LiAlSiO₄, a lithium silicate in pegmatites."},
 {"id": "L18-g-fractional-crystallisation", "lecture": 18, "kind": "term", "front": "Fractional crystallisation", "back": "Crystals form and separate from a melt, so the melt that is left becomes more and more enriched in the elements the crystals do not take."},
 {"id": "L18-g-greenbushes", "lecture": 18, "kind": "term", "front": "Greenbushes", "back": "The largest lithium pegmatite and lithium mine on Earth, in south-west Western Australia. Mined for tin from 1888, lithium from 1985."},
 {"id": "L18-g-hectorite", "lecture": 18, "kind": "term", "front": "Hectorite", "back": "A lithium-bearing smectite clay."},
 {"id": "L18-g-jadarite", "lecture": 18, "kind": "term", "front": "Jadarite", "back": "LiNaSiB₃O₇(OH), a lithium borosilicate known only from the Jadar Basin, Serbia."},
 {"id": "L18-g-laterite", "lecture": 18, "kind": "term", "front": "Laterite", "back": "A deeply weathered, iron-rich soil profile. Ni-Co laterites form on ultramafic rocks."},
 {"id": "L18-g-lct", "lecture": 18, "kind": "term", "front": "LCT", "back": "Lithium-caesium-tantalum pegmatite family. Also rich in boron. Forms from S-type granites."},
 {"id": "L18-g-lepidolite", "lecture": 18, "kind": "term", "front": "Lepidolite", "back": "A pink to lilac lithium mica. Common in lithium pegmatites, but its lithium is not extracted yet."},
 {"id": "L18-g-liquidus", "lecture": 18, "kind": "term", "front": "Liquidus", "back": "The temperature above which a melt is completely liquid."},
 {"id": "L18-g-metalliferous-coal", "lecture": 18, "kind": "term", "front": "Metalliferous coal", "back": "Coal with critical elements at concentrations that may be economic."},
 {"id": "L18-g-mineral-sands", "lecture": 18, "kind": "term", "front": "Mineral sands", "back": "Beach or dune sands with heavy minerals such as zircon, rutile and ilmenite."},
 {"id": "L18-g-natural-gamma-log", "lecture": 18, "kind": "term", "front": "Natural gamma log", "back": "A drill hole log of the natural radioactivity of the rocks. Coal and many ore beds give spikes."},
 {"id": "L18-g-nyf", "lecture": 18, "kind": "term", "front": "NYF", "back": "Niobium-yttrium-fluorine pegmatite family."},
 {"id": "L18-g-pegmatite", "lecture": 18, "kind": "term", "front": "Pegmatite", "back": "A very coarse-grained igneous rock, usually granitic, that crystallised from a melt rich in water and other volatiles."},
 {"id": "L18-g-petalite", "lecture": 18, "kind": "term", "front": "Petalite", "back": "LiAlSi₄O₁₀, a lithium silicate in pegmatites."},
 {"id": "L18-g-rey", "lecture": 18, "kind": "term", "front": "REY", "back": "Rare earth elements plus yttrium."},
 {"id": "L18-g-s-type-granite", "lecture": 18, "kind": "term", "front": "S-type granite", "back": "A granite made by melting sedimentary rock."},
 {"id": "L18-g-salar", "lecture": 18, "kind": "term", "front": "Salar", "back": "A salt flat in a dry basin in the Andes. Immature salars are mostly clastic sediment; mature salars are mostly halite."},
 {"id": "L18-g-sanidine", "lecture": 18, "kind": "term", "front": "Sanidine", "back": "A high-temperature potassium feldspar found in volcanic rocks."},
 {"id": "L18-g-spodumene", "lecture": 18, "kind": "term", "front": "Spodumene", "back": "LiAlSi₂O₆, a pale lithium pyroxene with 6 to 9 wt% Li₂O. The main lithium ore mineral in pegmatites."},
 {"id": "L18-g-tuff", "lecture": 18, "kind": "term", "front": "Tuff", "back": "A rock made of volcanic ash."},
 {"id": "L18-g-zinnwaldite", "lecture": 18, "kind": "term", "front": "Zinnwaldite", "back": "An iron-bearing lithium mica. Not processed for lithium yet."},
 {"id": "L18-cp1", "lecture": 18, "kind": "mc", "front": "Why does the lecturer prefer \"critical elements\" to \"critical minerals\"?", "opts": ["Minerals are cheaper", "The critical things are elements; a mineral such as quartz is not critical", "Elements are easier to mine"], "ans": "The critical things are elements; a mineral such as quartz is not critical", "back": "The industry term is wrong, but you will see it everywhere."},
 {"id": "L18-cp2", "lecture": 18, "kind": "mc", "front": "Which lithium deposit type supplies most of today's production?", "opts": ["Brines", "Pegmatites", "Clays"], "ans": "Pegmatites", "back": "Pegmatites: 40% of resources but 60% of production. Brines are the reverse."},
 {"id": "L18-cp3", "lecture": 18, "kind": "mc", "front": "What is spodumene?", "opts": ["A lithium mica", "A lithium pyroxene, the main lithium ore mineral", "A cobalt sulphide"], "ans": "A lithium pyroxene, the main lithium ore mineral", "back": "LiAlSi₂O₆, pale, with 6 to 9 wt% Li₂O."},
 {"id": "L18-cp4", "lecture": 18, "kind": "mc", "front": "Why do pegmatites have giant crystals?", "opts": ["They cool for millions of years", "Their melts are rich in volatiles, which make space and speed up crystal growth", "They form at the surface"], "ans": "Their melts are rich in volatiles, which make space and speed up crystal growth", "back": "Pegmatites can cool in days to weeks."},
 {"id": "L18-cp5", "lecture": 18, "kind": "mc", "front": "Where do lithium brines form?", "opts": ["Wet tropical coasts", "Dry, high basins such as the Andes and Tibet", "Deep ocean floors"], "ans": "Dry, high basins such as the Andes and Tibet", "back": "Hypersaline water in salars."},
 {"id": "L18-cp6", "lecture": 18, "kind": "mc", "front": "Which deposit is the only known source of jadarite?", "opts": ["Greenbushes", "Jadar, Serbia", "Thacker Pass, Nevada"], "ans": "Jadar, Serbia", "back": "It could supply 10% of world lithium demand."},
 {"id": "L18-cp7", "lecture": 18, "kind": "mc", "front": "Where does most of the world's cobalt come from?", "opts": ["Ni-Co laterites", "Stratiform sediment-hosted Cu-Co deposits of the African Copperbelt", "Pegmatites"], "ans": "Stratiform sediment-hosted Cu-Co deposits of the African Copperbelt", "back": "About 60%. Magmatic Ni-Cu gives 23% and laterites 15%."},
 {"id": "L18-cp8", "lecture": 18, "kind": "mc", "front": "Which country is the top zirconium producer, and from what?", "opts": ["Brazil, carbonatites", "Australia, mineral sands", "DRC, pegmatites"], "ans": "Australia, mineral sands", "back": "Zircon in mineral sands."},
 {"id": "L18-cp9", "lecture": 18, "kind": "mc", "front": "Why is coal ash richer in critical elements than the coal?", "opts": ["Burning adds metals", "Burning removes organic matter and volatiles, so the elements are left in a smaller mass", "Ash is mixed with ore"], "ans": "Burning removes organic matter and volatiles, so the elements are left in a smaller mass", "back": "Ash can match the grade of conventional ore."},
 {"id": "L18-cp10", "lecture": 18, "kind": "mc", "front": "How were the Xuanwei ore beds found?", "opts": ["By their bright colours", "By gamma ray anomalies in drill holes where there was no coal", "By visible alteration haloes"], "ans": "By gamma ray anomalies in drill holes where there was no coal", "back": "They look like ordinary claystone and siltstone."},
 {"id": "L18-cp11", "lecture": 18, "kind": "mc", "front": "Thin, laterally extensive layers with uniform REY grades and no alteration, next to coal. What are they?", "opts": ["LCT pegmatites", "Volcanic ash (tuff) beds", "Lithium brines"], "ans": "Volcanic ash (tuff) beds", "back": "Unconventional sediment-hosted critical element ore."},
 {"id": "L18-st1", "lecture": 18, "kind": "q", "lvl": "Recall", "front": "Define a critical element and explain why the lists differ between countries.", "back": "An element in great demand now or soon, with major future supply risks. The lists are geopolitical: each country's geology controls what it lacks, and even different government departments have different lists. Australia's list is short because it has deposits of almost everything."},
 {"id": "L18-st2", "lecture": 18, "kind": "q", "lvl": "Recall", "front": "Name the three lithium deposit types and their shares of resources and production.", "back": "Granitic pegmatites (40% of resources, 60% of production), brines (60%, 40%), and clays (potentially significant; first mines now in Nevada)."},
 {"id": "L18-st3", "lecture": 18, "kind": "q", "lvl": "Recall", "front": "Describe the zoning and minerals of a lithium pegmatite.", "back": "Feldspar-rich outer zones, an intermediate zone rich in rare metals with spodumene (main ore, 6 to 9 wt% Li₂O), petalite, eucryptite, lepidolite and zinnwaldite, and a quartz core. Grades are about 0.6% Li₂O. Be, Ta-Nb and Sn come with the lithium."},
 {"id": "L18-st4", "lecture": 18, "kind": "q", "lvl": "Apply", "front": "Describe the geology of Greenbushes.", "back": "A 2.57 Ga pegmatite, 3 km long and 300 m wide, dipping 45° west in amphibolite and schist, cut by dolerite dykes that dilute the ore. Many dykes and pods parallel to the foliation. Mined for tin from 1888, then tantalum, and lithium from 1985."},
 {"id": "L18-st5", "lecture": 18, "kind": "q", "lvl": "Apply", "front": "Explain how an LCT pegmatite forms.", "back": "A sedimentary protolith melts to an S-type granite. About 90% fractional crystallisation in a mostly closed system leaves a small, viscous melt with up to 15% water, rich in Li, Cs, Ta and B. It moves away from the granite to 9 to 6 km depth and crystallises fast (days to weeks) at about 500 to 400 °C. Volatiles give giant crystals. Tanco: 2 km³ from 18 000 km³ of melt."},
 {"id": "L18-st6", "lecture": 18, "kind": "q", "lvl": "Apply", "front": "Compare immature and mature salars.", "back": "Immature: mostly clastic clay, silt and sand with little evaporite; sand beds with 20 to 25% porosity through ~300 m hold brine. Mature: mostly halite; only the top 15 to 25 m is porous, deeper halite is cemented, so brine comes from the edges and base."},
 {"id": "L18-st7", "lecture": 18, "kind": "q", "lvl": "Recall", "front": "List the three cobalt deposit types with their shares, and the two cobalt minerals.", "back": "Stratiform sediment-hosted Cu-Co of the African Copperbelt (60%), magmatic Ni-Cu-(Co-PGE) (23%), Ni-Co laterites (15%). Cobaltite CoAsS (primary) and erythrite (oxide zone, pink cobalt bloom)."},
 {"id": "L18-st8", "lecture": 18, "kind": "q", "lvl": "Think", "front": "Why could critical elements in coal and ash beds be more important than conventional deposits?", "back": "Their grades are moderate, but they are layers that extend for hundreds of kilometres with uniform thickness and grade, so the total amount is huge. Ashing concentrates the elements further, and the ash is a by-product of power generation."},
 {"id": "L18-st9", "lecture": 18, "kind": "q", "lvl": "Synthesise", "front": "Explain the formation model for the Xuanwei ash beds.", "back": "Syenites enriched in critical elements crystallise in the Emeishan province; a final explosive eruption blasts through them; ash spreads and falls as distal tuff in basins; some is reworked; burial and diagenesis; later hydrothermal fluids move some elements, especially the LREE. No visible alteration, so they are found with gamma logs and geochemistry."},
 /* Lecture 19: 34 terms, 11 checkpoints, 9 self-test */
 {"id": "L19-g-adsorption", "lecture": 19, "kind": "term", "front": "Adsorption", "back": "Attachment of dissolved ions to a mineral surface, without entering the crystal structure."},
 {"id": "L19-g-allanite", "lecture": 19, "kind": "term", "front": "Allanite", "back": "A REE-bearing epidote-group silicate."},
 {"id": "L19-g-bastn-site", "lecture": 19, "kind": "term", "front": "Bastnäsite", "back": "(Ce,La,Nd,Y)(CO₃)F, a REE fluorocarbonate with 70 to 74% REO. Named after Bastnäs, Sweden."},
 {"id": "L19-g-carbonatite", "lecture": 19, "kind": "term", "front": "Carbonatite", "back": "An igneous rock with more than 50% carbonate minerals. Very rich in LREE."},
 {"id": "L19-g-ce-anomaly", "lecture": 19, "kind": "term", "front": "Ce anomaly", "back": "A spike or dip at Ce, caused by Ce³⁺ oxidising to Ce⁴⁺ near the surface."},
 {"id": "L19-g-cerianite", "lecture": 19, "kind": "term", "front": "Cerianite", "back": "(Ce⁴⁺,Th)O₂, a cerium oxide."},
 {"id": "L19-g-ci-chondrite", "lecture": 19, "kind": "term", "front": "CI chondrite", "back": "A primitive meteorite whose REE pattern is close to that of the early solar system. The usual REE standard."},
 {"id": "L19-g-eu-anomaly", "lecture": 19, "kind": "term", "front": "Eu anomaly", "back": "A dip (or spike) at Eu on a normalised plot. A negative anomaly usually means plagioclase was removed from the melt."},
 {"id": "L19-g-fenitisation", "lecture": 19, "kind": "term", "front": "Fenitisation", "back": "Alkali (Na-K) alteration of the rocks around a carbonatite or alkaline intrusion."},
 {"id": "L19-g-fractionation", "lecture": 19, "kind": "term", "front": "Fractionation", "back": "Separation of elements, here between the LREE and the HREE, during crystallisation or weathering."},
 {"id": "L19-g-halloysite", "lecture": 19, "kind": "term", "front": "Halloysite", "back": "A clay mineral like kaolinite, often tube-shaped."},
 {"id": "L19-g-heavy-mineral-sands", "lecture": 19, "kind": "term", "front": "Heavy mineral sands", "back": "Beach or dune sands rich in dense resistate minerals such as rutile, ilmenite, zircon and monazite."},
 {"id": "L19-g-hree", "lecture": 19, "kind": "term", "front": "HREE", "back": "Heavy rare earth elements, Eu to Lu, plus Y."},
 {"id": "L19-g-iocg", "lecture": 19, "kind": "term", "front": "IOCG", "back": "Iron oxide copper-gold deposit, such as Olympic Dam."},
 {"id": "L19-g-ion-adsorption-deposit", "lecture": 19, "kind": "term", "front": "Ion adsorption deposit", "back": "A weathered granite in which the REE are weakly attached to clay surfaces, not locked in minerals."},
 {"id": "L19-g-lanthanide", "lecture": 19, "kind": "term", "front": "Lanthanide", "back": "One of the 15 elements from lanthanum (57) to lutetium (71)."},
 {"id": "L19-g-lanthanide-contraction", "lecture": 19, "kind": "term", "front": "Lanthanide contraction", "back": "The steady decrease in ionic radius from La to Lu."},
 {"id": "L19-g-lanthanite", "lecture": 19, "kind": "term", "front": "Lanthanite", "back": "A hydrated REE carbonate. Lanthanite-(Nd) was described from Whitianga, New Zealand."},
 {"id": "L19-g-laterite", "lecture": 19, "kind": "term", "front": "Laterite", "back": "A thick, deeply weathered soil profile."},
 {"id": "L19-g-lree", "lecture": 19, "kind": "term", "front": "LREE", "back": "Light rare earth elements, La to Sm."},
 {"id": "L19-g-magnet-ree", "lecture": 19, "kind": "term", "front": "Magnet REE", "back": "Nd, Pr, Dy and Tb, the REE used in permanent magnets."},
 {"id": "L19-g-megacryst", "lecture": 19, "kind": "term", "front": "Megacryst", "back": "An exceptionally large crystal, often carried up by a younger magma."},
 {"id": "L19-g-monazite", "lecture": 19, "kind": "term", "front": "Monazite", "back": "(Ce,La,Nd,Th)PO₄, a LREE phosphate."},
 {"id": "L19-g-normalisation", "lecture": 19, "kind": "term", "front": "Normalisation", "back": "Dividing each REE value by the value in a standard (such as CI chondrite), so that the natural zigzag in abundance disappears and processes show up."},
 {"id": "L19-g-parisite", "lecture": 19, "kind": "term", "front": "Parisite", "back": "Ca(Ce,La)₂(CO₃)₃F₂, a REE fluorocarbonate."},
 {"id": "L19-g-partition-coefficient", "lecture": 19, "kind": "term", "front": "Partition coefficient", "back": "How strongly an element goes into a mineral compared with the melt."},
 {"id": "L19-g-reo", "lecture": 19, "kind": "term", "front": "REO", "back": "Rare earth oxide. Grades and tonnages are given as REO."},
 {"id": "L19-g-resistate-mineral", "lecture": 19, "kind": "term", "front": "Resistate mineral", "back": "A mineral that is very hard to weather or dissolve, such as zircon, monazite and xenotime."},
 {"id": "L19-g-rey", "lecture": 19, "kind": "term", "front": "REY", "back": "The rare earth elements (La to Lu) plus yttrium, which behaves like them."},
 {"id": "L19-g-rhabdophane", "lecture": 19, "kind": "term", "front": "Rhabdophane", "back": "(Ce,La)PO₄·H₂O, a hydrated REE phosphate formed at low temperature."},
 {"id": "L19-g-strand-line", "lecture": 19, "kind": "term", "front": "Strand line", "back": "A former or present shoreline where waves concentrated heavy minerals."},
 {"id": "L19-g-supergene", "lecture": 19, "kind": "term", "front": "Supergene", "back": "Formed by near-surface weathering and groundwater."},
 {"id": "L19-g-syenite", "lecture": 19, "kind": "term", "front": "Syenite", "back": "An alkaline igneous rock with alkali feldspar and little or no quartz."},
 {"id": "L19-g-xenotime", "lecture": 19, "kind": "term", "front": "Xenotime", "back": "YPO₄, a HREE phosphate."},
 {"id": "L19-cp1", "lecture": 19, "kind": "mc", "front": "Why are the rare earths called rare?", "opts": ["They are less common than gold", "Processes that concentrate them enough to mine are rare", "They are radioactive"], "ans": "Processes that concentrate them enough to mine are rare", "back": "Ce and La are more common than tin."},
 {"id": "L19-cp2", "lecture": 19, "kind": "mc", "front": "A granite has a deep dip at Eu on its chondrite plot. What happened?", "opts": ["Garnet was added", "Plagioclase crystallised and was removed, taking Eu²⁺ with it", "Cerium oxidised"], "ans": "Plagioclase crystallised and was removed, taking Eu²⁺ with it", "back": "Eu²⁺ swaps for Ca²⁺ in plagioclase."},
 {"id": "L19-cp3", "lecture": 19, "kind": "mc", "front": "Which three minerals supply most economic REE?", "opts": ["Zircon, apatite, quartz", "Bastnäsite, monazite, xenotime", "Galena, sphalerite, pyrite"], "ans": "Bastnäsite, monazite, xenotime", "back": "Bastnäsite (fluorocarbonate), monazite (LREE phosphate), xenotime (HREE phosphate)."},
 {"id": "L19-cp4", "lecture": 19, "kind": "mc", "front": "Why can zircon tell you about events that left no other evidence?", "opts": ["It dissolves easily", "It is a resistate mineral that survives weathering and can be dated", "It contains no REE"], "ans": "It is a resistate mineral that survives weathering and can be dated", "back": "U-Pb ages, Hf isotopes and Ti thermometry all come from zircon."},
 {"id": "L19-cp5", "lecture": 19, "kind": "mc", "front": "Which use accounts for about 95% of REE value?", "opts": ["Glass polishing", "Permanent magnets (Nd, Pr, Dy, Tb)", "Catalysts"], "ans": "Permanent magnets (Nd, Pr, Dy, Tb)", "back": "Demand for magnet REE doubled since 2015."},
 {"id": "L19-cp6", "lecture": 19, "kind": "mc", "front": "Which deposit type is secondary?", "opts": ["Carbonatite", "Ion adsorption clay", "Alkali granite"], "ans": "Ion adsorption clay", "back": "Secondary deposits form by weathering."},
 {"id": "L19-cp7", "lecture": 19, "kind": "mc", "front": "Why is Bayan Obo mined?", "opts": ["Only for REE", "For iron, with REE (and Nb) as by-products", "For gold"], "ans": "For iron, with REE (and Nb) as by-products", "back": "It is a Fe-Nb-REE deposit, the largest REE resource on Earth."},
 {"id": "L19-cp8", "lecture": 19, "kind": "mc", "front": "At Mt Weld, which zone has been the main REE target?", "opts": ["Fresh carbonatite", "The lateritic supergene and residual zone", "The alluvium"], "ans": "The lateritic supergene and residual zone", "back": "Weathering enriched the REE above the carbonatite."},
 {"id": "L19-cp9", "lecture": 19, "kind": "mc", "front": "In an ion adsorption profile, where is cerium enriched?", "opts": ["At the base, in fresh granite", "Near the top, as Ce⁴⁺ (cerianite)", "Nowhere"], "ans": "Near the top, as Ce⁴⁺ (cerianite)", "back": "A shallow positive Ce anomaly points to the REE-rich horizon below."},
 {"id": "L19-cp10", "lecture": 19, "kind": "mc", "front": "Where do waves concentrate heavy minerals?", "opts": ["In river headwaters", "Along strand lines (old and modern shorelines)", "In lake muds"], "ans": "Along strand lines (old and modern shorelines)", "back": "Follow the old shorelines to explore."},
 {"id": "L19-cp11", "lecture": 19, "kind": "mc", "front": "Why can ion adsorption clays be mined at 800 ppm REY?", "opts": ["They are deep and hot", "The REE are weakly adsorbed and easy to extract, and rich in valuable HREE", "They contain gold"], "ans": "The REE are weakly adsorbed and easy to extract, and rich in valuable HREE", "back": "No need to break down minerals."},
 {"id": "L19-st1", "lecture": 19, "kind": "q", "lvl": "Recall", "front": "Define the REE and explain the LREE, HREE and REY terms.", "back": "The lanthanides, La to Lu. Y behaves the same and is included as REY. LREE = La to Sm; HREE = Eu to Lu plus Y; MREE = Sm to Dy. Pm is not natural."},
 {"id": "L19-st2", "lecture": 19, "kind": "q", "lvl": "Recall", "front": "Explain why the REE are normalised to chondrite, and what the standard must be like.", "back": "Normalising removes the natural zigzag in abundance, so processes show up. The standard must have formed by a similar process: chondrite for igneous rocks, PAAS for sediments, average coal for coals."},
 {"id": "L19-st3", "lecture": 19, "kind": "q", "lvl": "Apply", "front": "Explain the lanthanide contraction and how it fractionates the REE.", "back": "The ionic radius decreases from La to Lu. Minerals prefer ions of the right size: garnet, pyroxene and hornblende take the small HREE, others take the larger LREE. So crystallisation separates the LREE from the HREE."},
 {"id": "L19-st4", "lecture": 19, "kind": "q", "lvl": "Apply", "front": "What causes a negative Eu anomaly, and what does it tell you about a granite?", "back": "In reducing magmas, Eu becomes Eu²⁺, which has the size and charge of Ca²⁺ and enters plagioclase. Removing plagioclase leaves the melt short of Eu. A strong negative anomaly means a long-fractionated granite, which is often enriched in rare metals (Sn, W)."},
 {"id": "L19-st5", "lecture": 19, "kind": "q", "lvl": "Apply", "front": "Why are carbonatites so rich in LREE?", "back": "Carbonate melts take up REE better than silicate melts, and the common carbonate minerals reject REE. So the REE build up in the remaining melt until REE-rich minerals (bastnäsite, monazite) crystallise."},
 {"id": "L19-st6", "lecture": 19, "kind": "q", "lvl": "Recall", "front": "Describe Bayan Obo.", "back": "World's largest REE resource, at Baotou, Inner Mongolia. Mesoproterozoic Fe-Nb-REE deposit in dolomitised marble, between carbonatite and IOCG. Bastnäsite, monazite, niobite, magnetite. Multiple hydrothermal stages, fenitisation, zoned disseminated-banded-massive ore, ~6% REO in the main ore bodies. REE are a by-product of iron mining."},
 {"id": "L19-st7", "lecture": 19, "kind": "q", "lvl": "Recall", "front": "Describe Mt Weld.", "back": "~2.03 Ga carbonatite in the Laverton tectonic zone, WA, in an alkaline province with kimberlites. Greenschist overprint. Lateritic weathering enriched the LREE (plus P, Nb, Ta) in supergene and residual zones above the carbonatite. Crown: 37.7 Mt at 1.16% REO and 1.07% Nb₂O₅."},
 {"id": "L19-st8", "lecture": 19, "kind": "q", "lvl": "Apply", "front": "Explain how an ion adsorption clay deposit forms and how you explore for it.", "back": "Granite weathers in a subtropical climate; acids break down REE minerals near the top; REE³⁺ moves down and adsorbs onto kaolinite and halloysite where the pH rises. Ce oxidises to Ce⁴⁺ and stays near the top as cerianite. A shallow positive Ce anomaly points to the REE-rich zone below. Profiles are 6 to 10 m thick."},
 {"id": "L19-st9", "lecture": 19, "kind": "q", "lvl": "Synthesise", "front": "Compare the four deposit types by what makes them economic.", "back": "Bayan Obo: by-product of Fe. Mt Weld: very high grade LREE in shallow laterite. IAD: easy extraction and valuable HREE at ~800 ppm. Heavy mineral sands: shallow, natural concentration, several products. Metallurgy and magnet REE content decide the economics."},
 /* Lecture 20: 29 terms, 11 checkpoints, 9 self-test */
 {"id": "L20-g-adamantine", "lecture": 20, "kind": "term", "front": "Adamantine", "back": "A very bright, brilliant lustre, like diamond."},
 {"id": "L20-g-boart", "lecture": 20, "kind": "term", "front": "Boart", "back": "Black, opaque industrial diamond, used in drill bits and grinding wheels."},
 {"id": "L20-g-carat", "lecture": 20, "kind": "term", "front": "Carat", "back": "The unit of gem weight: 0.2 g. A 1 carat diamond is about 6.5 mm across."},
 {"id": "L20-g-carbonado", "lecture": 20, "kind": "term", "front": "Carbonado", "back": "Black, porous, fine-grained polycrystalline diamond, as rounded balls, found only in palaeoalluvial deposits."},
 {"id": "L20-g-coesite", "lecture": 20, "kind": "term", "front": "Coesite", "back": "A high-pressure form of SiO₂. Coesite inclusions suggest subduction diamonds."},
 {"id": "L20-g-craton", "lecture": 20, "kind": "term", "front": "Craton", "back": "An old, thick, stable part of a continent (Archean to Proterozoic)."},
 {"id": "L20-g-deep-lead", "lecture": 20, "kind": "term", "front": "Deep lead", "back": "An old river gravel buried under younger rocks such as basalt."},
 {"id": "L20-g-diamond-window", "lecture": 20, "kind": "term", "front": "Diamond window", "back": "The depth range (more than about 140 km) where a magma can pick up diamonds."},
 {"id": "L20-g-diatreme", "lecture": 20, "kind": "term", "front": "Diatreme", "back": "A volcanic pipe filled with broken rock, made by a gas-rich explosive eruption."},
 {"id": "L20-g-eclogite", "lecture": 20, "kind": "term", "front": "Eclogite", "back": "A high-pressure rock of garnet and Na-rich pyroxene."},
 {"id": "L20-g-framesite", "lecture": 20, "kind": "term", "front": "Framesite", "back": "Black, porous polycrystalline diamond with crystal faces, found only in kimberlite and lamproite."},
 {"id": "L20-g-graphite-pseudomorph", "lecture": 20, "kind": "term", "front": "Graphite pseudomorph", "back": "Graphite that has the shape of the diamond it replaced. A sign of slow ascent."},
 {"id": "L20-g-indicator-minerals", "lecture": 20, "kind": "term", "front": "Indicator minerals", "back": "Minerals that travel with kimberlite and survive in streams, used to trace a pipe: pyrope, picroilmenite, chrome diopside, perovskite."},
 {"id": "L20-g-kimberlite", "lecture": 20, "kind": "term", "front": "Kimberlite", "back": "A volatile-rich, potassic ultramafic rock of serpentinised olivine with mantle crystals and xenoliths, in pipes, dykes and sills."},
 {"id": "L20-g-lamproite", "lecture": 20, "kind": "term", "front": "Lamproite", "back": "A porphyritic K- and Mg-rich volcanic rock with phlogopite, leucite and unusual accessory minerals. Argyle is an olivine lamproite."},
 {"id": "L20-g-macle", "lecture": 20, "kind": "term", "front": "Macle", "back": "A flattened, twinned octahedron of diamond with sharp edges."},
 {"id": "L20-g-macrocryst", "lecture": 20, "kind": "term", "front": "Macrocryst", "back": "A large crystal in kimberlite, usually derived from the mantle."},
 {"id": "L20-g-metastable", "lecture": 20, "kind": "term", "front": "Metastable", "back": "Existing in a form that is not stable under present conditions but changes too slowly to notice. Diamond at the surface."},
 {"id": "L20-g-palaeoalluvial", "lecture": 20, "kind": "term", "front": "Palaeoalluvial", "back": "Old river gravels, often buried. Also called deep leads."},
 {"id": "L20-g-picroilmenite", "lecture": 20, "kind": "term", "front": "Picroilmenite", "back": "Mg-rich ilmenite. A key kimberlite indicator mineral."},
 {"id": "L20-g-pyrope", "lecture": 20, "kind": "term", "front": "Pyrope", "back": "Mg-rich red-purple garnet from the mantle. A key diamond indicator mineral."},
 {"id": "L20-g-radiometrics", "lecture": 20, "kind": "term", "front": "Radiometrics", "back": "Measuring natural gamma radiation (K, U, Th) from the air. Finds K-rich lamproites."},
 {"id": "L20-g-subduction-diamond", "lecture": 20, "kind": "term", "front": "Subduction diamond", "back": "Diamond formed at high pressure but low temperature in a subduction zone."},
 {"id": "L20-g-synthetic-diamond", "lecture": 20, "kind": "term", "front": "Synthetic diamond", "back": "Man-made diamond. Gem quality up to 5 carats is now cheaper than natural; it has no inclusions."},
 {"id": "L20-g-thermobarometry", "lecture": 20, "kind": "term", "front": "Thermobarometry", "back": "Calculating the temperature and pressure (depth) of formation from coexisting mineral pairs."},
 {"id": "L20-g-type-i-diamond", "lecture": 20, "kind": "term", "front": "Type I diamond", "back": "A diamond with aggregated nitrogen, usually yellow or brown."},
 {"id": "L20-g-type-ii-diamond", "lecture": 20, "kind": "term", "front": "Type II diamond", "back": "A diamond with little or no nitrogen, colourless to white."},
 {"id": "L20-g-xenocryst", "lecture": 20, "kind": "term", "front": "Xenocryst", "back": "A foreign crystal carried in a magma. Diamonds are xenocrysts in kimberlite."},
 {"id": "L20-g-xenolith", "lecture": 20, "kind": "term", "front": "Xenolith", "back": "A fragment of foreign rock carried in a magma, such as a mantle peridotite."},
 {"id": "L20-cp1", "lecture": 20, "kind": "mc", "front": "Why do diamond mine profits now depend on large stones?", "opts": ["Small stones are too hard to cut", "Synthetic gems up to 5 carats are now cheaper than natural stones", "Large stones are easier to find"], "ans": "Synthetic gems up to 5 carats are now cheaper than natural stones", "back": "Most mined stones are 0.5 to 3 carats, the size synthetics now supply."},
 {"id": "L20-cp2", "lecture": 20, "kind": "mc", "front": "What makes a Type I diamond yellow or brown?", "opts": ["Iron", "Aggregated nitrogen", "Boron"], "ans": "Aggregated nitrogen", "back": "Type II diamonds have little or no nitrogen and are colourless."},
 {"id": "L20-cp3", "lecture": 20, "kind": "mc", "front": "Which country produces the most natural diamonds?", "opts": ["Australia", "Russia", "Canada"], "ans": "Russia", "back": "16 million carats in 2025. Australia has no operating mine now."},
 {"id": "L20-cp4", "lecture": 20, "kind": "mc", "front": "Why is Argyle special?", "opts": ["It is the oldest kimberlite", "It is an olivine lamproite that supplied 90 to 95% of the world's pink diamonds", "It produced only gem stones"], "ans": "It is an olivine lamproite that supplied 90 to 95% of the world's pink diamonds", "back": "Only 5% gem quality, but unique pink and red stones."},
 {"id": "L20-cp5", "lecture": 20, "kind": "mc", "front": "In kimberlite, what are diamonds?", "opts": ["Phenocrysts that grew from the kimberlite", "Xenocrysts carried up from the mantle", "Secondary veins"], "ans": "Xenocrysts carried up from the mantle", "back": "They are accidental passengers."},
 {"id": "L20-cp6", "lecture": 20, "kind": "mc", "front": "Why do kimberlite pipes form round depressions at the surface?", "opts": ["They are always lakes", "They weather faster than the rocks around them", "They collapse after mining"], "ans": "They weather faster than the rocks around them", "back": "Some explorers found pipes on Google Earth this way."},
 {"id": "L20-cp7", "lecture": 20, "kind": "mc", "front": "You find graphite with the shape of diamond crystals. What does it mean?", "opts": ["A rich deposit nearby", "The magma rose too slowly and the diamonds turned to graphite", "The diamonds are synthetic"], "ans": "The magma rose too slowly and the diamonds turned to graphite", "back": "Leave the region."},
 {"id": "L20-cp8", "lecture": 20, "kind": "mc", "front": "How did the Copeton diamonds probably form?", "opts": ["In a craton at 200 km", "At high pressure but low temperature in a subduction zone", "In a granite"], "ans": "At high pressure but low temperature in a subduction zone", "back": "Below 400 °C, in the New England Fold Belt."},
 {"id": "L20-cp9", "lecture": 20, "kind": "mc", "front": "Mantle xenoliths in a kimberlite came from 70 km. Should you keep exploring it for diamonds?", "opts": ["Yes", "No, it is outside the diamond window (more than 140 km)", "Only for gold"], "ans": "No, it is outside the diamond window (more than 140 km)", "back": "Thermobarometry on the xenoliths tells you the depth."},
 {"id": "L20-cp10", "lecture": 20, "kind": "mc", "front": "What shows that the Cempaka diamonds did not travel far?", "opts": ["They are rounded", "They are sharp and angular, with delicate surface features", "They are all small"], "ans": "They are sharp and angular, with delicate surface features", "back": "No indicator minerals either; zircons suggest lamproite."},
 {"id": "L20-cp11", "lecture": 20, "kind": "mc", "front": "Which is the largest gem diamond ever found?", "opts": ["Hope", "Cullinan, 3106.75 carats", "Constellation"], "ans": "Cullinan, 3106.75 carats", "back": "Found at the Premier mine in 1905."},
 {"id": "L20-st1", "lecture": 20, "kind": "q", "lvl": "Recall", "front": "List the physical properties of diamond and its three common forms.", "back": "Carbon, cubic, hardness 10, SG 3.5, adamantine lustre, any colour (mostly colourless, yellow or brown). Octahedra (most common), cubes (common in West Africa) and macles (flattened twinned octahedra)."},
 {"id": "L20-st2", "lecture": 20, "kind": "q", "lvl": "Recall", "front": "Explain the 4 Cs and why large stones matter more now.", "back": "Carat (0.2 g), cut (round brilliant best), colour (strong colours most valuable) and clarity. Above 10 carats value rises exponentially. Synthetic gems up to 5 carats are now cheaper, so profit depends on large and rarely coloured stones."},
 {"id": "L20-st3", "lecture": 20, "kind": "q", "lvl": "Recall", "front": "Describe kimberlite and its indicator minerals.", "back": "Volatile-rich potassic ultramafic rock of serpentinised olivine with phlogopite, pyroxenes, carbonate and chromite; fragmental, with mantle macrocrysts and xenoliths in a fine matrix. Indicators: pyrope garnet, picroilmenite, perovskite, monticellite, rutile. Diamond is a very rare xenocryst."},
 {"id": "L20-st4", "lecture": 20, "kind": "q", "lvl": "Apply", "front": "How does lamproite differ from kimberlite? Give an Australian example.", "back": "Lamproite is strongly porphyritic, less fragmental, rich in K and Mg, with phlogopite, leucite and unusual minerals (K-Ti-richterite, priderite, wadeite, jeppeite). Argyle (WA) is an olivine lamproite."},
 {"id": "L20-st5", "lecture": 20, "kind": "q", "lvl": "Apply", "front": "Explain why diamonds survive the trip to the surface.", "back": "They form at ~1100 °C and 150 to 200 km, and are metastable at the surface. Kimberlite is ~95% CO₂-rich and rises explosively at up to 8 km/h, so there is no time to convert to graphite. Slow ascent gives graphite pseudomorphs (southern Spain)."},
 {"id": "L20-st6", "lecture": 20, "kind": "q", "lvl": "Apply", "front": "Describe the two economic types of diamond deposit with examples.", "back": "Large tonnage with few gems but unique colour (Argyle) or size (Premier); moderate to large tonnage with a moderate (Jwaneng) to high (Mir) proportion of gems."},
 {"id": "L20-st7", "lecture": 20, "kind": "q", "lvl": "Recall", "front": "What evidence suggests subduction diamonds, and where in NSW?", "back": "Coesite inclusions, Na-rich garnet in eclogite, nearby eclogite and blueschist, nephelinite or basanite diatremes; indicators coesite, grossular garnet, Na pyroxene and corundum. Copeton (Inverell): high P, low T (< 400 °C), New England Fold Belt."},
 {"id": "L20-st8", "lecture": 20, "kind": "q", "lvl": "Apply", "front": "Outline an exploration strategy for diamonds in a craton.", "back": "Satellite and air photos for lineament intersections and round depressions; stream sediment sampling for pyrope, picroilmenite and perovskite; radiometrics for K-rich lamproites; thermobarometry on xenoliths to confirm > 140 km; walk away if you find graphite pseudomorphs."},
 {"id": "L20-st9", "lecture": 20, "kind": "q", "lvl": "Synthesise", "front": "Why was the glacial origin rejected for the Cempaka diamonds?", "back": "Millions of carats of sharp, angular diamonds with preserved surface features show little transport; no kimberlite indicators; two Cretaceous zircon populations with lamproite-like chemistry; nearest cratons are 2000 km away."},
 /* Lecture 21: 27 terms, 11 checkpoints, 9 self-test */
 {"id": "L21-g-anoxic", "lecture": 21, "kind": "term", "front": "Anoxic", "back": "Without free oxygen."},
 {"id": "L21-g-bif", "lecture": 21, "kind": "term", "front": "BIF", "back": "Banded iron formation: thin alternating layers of iron oxide and chert, mostly 2.5 to 1.9 Ga."},
 {"id": "L21-g-bulk-commodity", "lecture": 21, "kind": "term", "front": "Bulk commodity", "back": "A raw material mined in very large tonnages, such as iron ore, manganese, bauxite and coal."},
 {"id": "L21-g-channel-iron-deposit", "lecture": 21, "kind": "term", "front": "Channel iron deposit", "back": "Goethite-rich pisolitic ore in old river valleys, formed by Cretaceous to Cenozoic weathering."},
 {"id": "L21-g-cryptomelane", "lecture": 21, "kind": "term", "front": "Cryptomelane", "back": "KMn₈O₁₆, a potassium manganese oxide."},
 {"id": "L21-g-eh", "lecture": 21, "kind": "term", "front": "Eh", "back": "Redox potential: how oxidising (high Eh) or reducing (low Eh) the water is."},
 {"id": "L21-g-exogenous", "lecture": 21, "kind": "term", "front": "Exogenous", "back": "Formed at or near the Earth's surface: residual, detrital or chemical deposits."},
 {"id": "L21-g-goethite", "lecture": 21, "kind": "term", "front": "Goethite", "back": "FeO(OH), an iron oxide-hydroxide formed by weathering; yellow-brown streak."},
 {"id": "L21-g-great-oxidation-event", "lecture": 21, "kind": "term", "front": "Great Oxidation Event", "back": "The rise of free oxygen in the atmosphere about 2.4 Ga."},
 {"id": "L21-g-hematite", "lecture": 21, "kind": "term", "front": "Hematite", "back": "Fe₂O₃, the main iron ore mineral; red streak."},
 {"id": "L21-g-jaspilite", "lecture": 21, "kind": "term", "front": "Jaspilite", "back": "Red jasper banded with iron oxide; a type of BIF."},
 {"id": "L21-g-magnetite", "lecture": 21, "kind": "term", "front": "Magnetite", "back": "Fe₃O₄, a magnetic iron oxide."},
 {"id": "L21-g-manganite", "lecture": 21, "kind": "term", "front": "Manganite", "back": "MnO(OH), a manganese oxide-hydroxide."},
 {"id": "L21-g-manganocalcite", "lecture": 21, "kind": "term", "front": "Manganocalcite", "back": "Calcite with manganese; pale pink."},
 {"id": "L21-g-marine-transgression", "lecture": 21, "kind": "term", "front": "Marine transgression", "back": "A rise in sea level that moves the shoreline inland."},
 {"id": "L21-g-martite", "lecture": 21, "kind": "term", "front": "Martite", "back": "Hematite that has replaced magnetite, keeping its octahedral shape. Not magnetic."},
 {"id": "L21-g-microplaty-hematite", "lecture": 21, "kind": "term", "front": "Microplaty hematite", "back": "Fine platy hematite, the main high-grade Pilbara ore."},
 {"id": "L21-g-mn-nodule", "lecture": 21, "kind": "term", "front": "Mn nodule", "back": "A concentric Mn-Fe oxide ball on the deep ocean floor; low grade (15 to 19% Mn)."},
 {"id": "L21-g-oolite", "lecture": 21, "kind": "term", "front": "Oolite", "back": "A round sedimentary grain less than 2 mm with concentric layers."},
 {"id": "L21-g-pisolite", "lecture": 21, "kind": "term", "front": "Pisolite", "back": "A round concentric grain larger than 2 mm. Pisolitic Mn is the richest ore at Groote Eylandt."},
 {"id": "L21-g-psilomelane", "lecture": 21, "kind": "term", "front": "Psilomelane", "back": "A field name for a mixture of black Mn oxides, often botryoidal. Not a true mineral species."},
 {"id": "L21-g-pyrolusite", "lecture": 21, "kind": "term", "front": "Pyrolusite", "back": "MnO₂, the main manganese ore mineral: black and sooty."},
 {"id": "L21-g-rhodochrosite", "lecture": 21, "kind": "term", "front": "Rhodochrosite", "back": "MnCO₃, a deep pink manganese carbonate."},
 {"id": "L21-g-stratified-basin", "lecture": 21, "kind": "term", "front": "Stratified basin", "back": "A water body with oxic water on top and anoxic water below."},
 {"id": "L21-g-stromatolite", "lecture": 21, "kind": "term", "front": "Stromatolite", "back": "A layered structure built by microbial mats; evidence of early photosynthesis."},
 {"id": "L21-g-supergene-enrichment", "lecture": 21, "kind": "term", "front": "Supergene enrichment", "back": "Near-surface weathering and groundwater that remove gangue (silica, carbonate) and concentrate the ore metal."},
 {"id": "L21-g-u-pb-hematite-dating", "lecture": 21, "kind": "term", "front": "U-Pb hematite dating", "back": "Dating hematite directly using the small amount of uranium in its structure."},
 {"id": "L21-cp1", "lecture": 21, "kind": "mc", "front": "Why does iron ore show strongly on gravity maps?", "opts": ["It is radioactive", "Hematite and magnetite are much denser than quartz", "It is magnetic only"], "ans": "Hematite and magnetite are much denser than quartz", "back": "Big gravity (and magnetic) highs."},
 {"id": "L21-cp2", "lecture": 21, "kind": "mc", "front": "What setting is most important for large sedimentary Mn deposits?", "opts": ["Deep ocean trenches", "Shallow marine shelves on stable cratons, in anoxic basins starved of detritus", "Granite batholiths"], "ans": "Shallow marine shelves on stable cratons, in anoxic basins starved of detritus", "back": "Estuarine to shallow marine shelf."},
 {"id": "L21-cp3", "lecture": 21, "kind": "mc", "front": "In a stratified basin, where does MnO₂ precipitate?", "opts": ["In the deep anoxic water", "Where the oxic-anoxic boundary meets the shelf", "In rivers"], "ans": "Where the oxic-anoxic boundary meets the shelf", "back": "Mn²⁺ oxidises to Mn⁴⁺ when it meets oxygen."},
 {"id": "L21-cp4", "lecture": 21, "kind": "mc", "front": "Which ore type is richest at Groote Eylandt?", "opts": ["Siliceous ore", "Pisolitic Mn ore", "Mn carbonate"], "ans": "Pisolitic Mn ore", "back": "Pisolites grew in shallow agitated water."},
 {"id": "L21-cp5", "lecture": 21, "kind": "mc", "front": "Why are deep-sea nodules not yet mined?", "opts": ["They are radioactive", "Low grade (15 to 19% Mn) and very hard to prove tonnage and grade", "They are too rich"], "ans": "Low grade (15 to 19% Mn) and very hard to prove tonnage and grade", "back": "A land deposit needs about 40% Mn."},
 {"id": "L21-cp6", "lecture": 21, "kind": "mc", "front": "Which country is by far the largest iron ore producer?", "opts": ["China", "Australia", "Brazil"], "ans": "Australia", "back": "980 Mt in 2025, more than twice Brazil."},
 {"id": "L21-cp7", "lecture": 21, "kind": "mc", "front": "How did iron move through Archean oceans?", "opts": ["As hematite grains", "Dissolved as Fe²⁺, because there was no oxygen", "As magnetite sand"], "ans": "Dissolved as Fe²⁺, because there was no oxygen", "back": "It precipitated as Fe³⁺ oxide when it met oxygen."},
 {"id": "L21-cp8", "lecture": 21, "kind": "mc", "front": "What turns a 35% Fe BIF into 62% Fe ore?", "opts": ["Adding more chert", "Supergene leaching of silica and carbonate", "Metamorphism alone"], "ans": "Supergene leaching of silica and carbonate", "back": "The insoluble iron oxides stay behind."},
 {"id": "L21-cp9", "lecture": 21, "kind": "mc", "front": "Why are Pilbara ore bodies better in more deformed areas?", "opts": ["Deformation added iron", "Faults and folds let weathering fluids go deeper", "Deformed BIF is younger"], "ans": "Faults and folds let weathering fluids go deeper", "back": "Weaknesses focus the fluids."},
 {"id": "L21-cp10", "lecture": 21, "kind": "mc", "front": "What did U-Pb dating of Pilbara hematite show?", "opts": ["The ore is 3.5 Ga", "The ore formed at 1.4 to 1.1 Ga, much later than the BIF", "The ore is Cenozoic only"], "ans": "The ore formed at 1.4 to 1.1 Ga, much later than the BIF", "back": "Linked to the break-up of Columbia (Nuna)."},
 {"id": "L21-cp11", "lecture": 21, "kind": "mc", "front": "Black, sooty, pisolitic ore in flat Cretaceous beds on an old shoreline. What is it?", "opts": ["BIF hematite", "Sedimentary Mn ore (Groote type)", "Deep-sea nodules"], "ans": "Sedimentary Mn ore (Groote type)", "back": "Oxide facies on the landward shelf."},
 {"id": "L21-st1", "lecture": 21, "kind": "q", "lvl": "Recall", "front": "Define exogenous deposits and give the three types.", "back": "Deposits formed at or near the Earth's surface: residual (laterites), detrital (placers) and chemical (evaporites, BIFs)."},
 {"id": "L21-st2", "lecture": 21, "kind": "q", "lvl": "Recall", "front": "Describe the tectonic and depositional setting of sedimentary Mn deposits.", "back": "Stable craton margins or cratonic basins; shallow marine to estuarine shelf (15 to 300 m), sheltered sites around islands; anoxic basins starved of detrital input; during transgressions. Oxide facies landward, carbonate facies basinward."},
 {"id": "L21-st3", "lecture": 21, "kind": "q", "lvl": "Apply", "front": "Explain the stratified basin model for Mn ore.", "back": "Oxic water over anoxic water. Mn²⁺ dissolves in the anoxic water. Transgression and upwelling bring it onto the shelf, where the redox interface meets the sediment; Mn²⁺ oxidises and MnO₂ precipitates. Deeper, Mn carbonates form. Clastic input would dilute it."},
 {"id": "L21-st4", "lecture": 21, "kind": "q", "lvl": "Recall", "front": "Describe Groote Eylandt.", "back": "Cretaceous intracratonic shelf deposit, Gulf of Carpentaria; ~250 Mt, ~15% of world production; 22 × 6 km; beds 0.1 to 11 m, dipping ~3°; 30 to 50% Mn; pyrolusite, psilomelane, cryptomelane, manganocalcite; oolitic and pisolitic ore along a palaeo-shoreline; supergene enrichment."},
 {"id": "L21-st5", "lecture": 21, "kind": "q", "lvl": "Apply", "front": "Why are deep-sea Mn nodules not economic?", "back": "Only 15 to 19% Mn (land ore needs ~40%), often more Fe than Mn, ~0.3% Co; deeper than 3000 m; very hard to prove grade and tonnage of scattered nodules; land deposits are higher grade."},
 {"id": "L21-st6", "lecture": 21, "kind": "q", "lvl": "Apply", "front": "Explain how BIFs formed and their link with oxygen.", "back": "In O₂-poor Archean to Palaeoproterozoic oceans, Fe²⁺ (from volcanic exhalation) stayed dissolved and travelled far. It precipitated as Fe³⁺ oxide where oxygen (from photosynthesising bacteria, stromatolites) was present, mostly in shallow water. Oxide, carbonate and sulphide facies form at increasing depth."},
 {"id": "L21-st7", "lecture": 21, "kind": "q", "lvl": "Recall", "front": "List the iron ore types and their grades.", "back": "Primary BIF 30 to 45% Fe; goethite-rich ore 56 to 63%; high-grade hematite (massive or microplaty) 60 to 68%; pure hematite 70%. Pilbara ores 58 to 64%."},
 {"id": "L21-st8", "lecture": 21, "kind": "q", "lvl": "Apply", "front": "Explain the three outcomes of fluid alteration of BIF.", "back": "(1) Iron added and silica lost, stratigraphy kept: richest ore. (2) No iron added, silica lost, stratigraphy kept, porosity created. (3) No iron added, silica lost, layers collapse and stratigraphy is lost."},
 {"id": "L21-st9", "lecture": 21, "kind": "q", "lvl": "Synthesise", "front": "How did direct dating change the model for Pilbara iron ore?", "back": "U-Pb dating of hematite gives 1.4 to 1.1 Ga, not the traditional 2.2 to 2 Ga. The ore formed during the amalgamation of Australia after Columbia (Nuna) broke up, not during the Great Oxidation Event, although the BIF host is still 2.2 to 2 Ga."}
];

/* ---- hand-written cards below: kept when tools/build_cards.py reruns ---- */
CARDS.push(
 {"id": "L1-x-chain", "lecture": 1, "kind": "q", "front": "Name the links in the hydrothermal chain.", "back": "A metal source, a fluid that can carry metal, a pathway to focus it, a trap that makes it drop the metal, a seal to keep it there long enough, and preservation afterwards. Every link must hold, and every deposit is structurally controlled."},
 {"id": "L1-x-trap", "lecture": 1, "kind": "q", "front": "Hydrothermal fluids are usually undersaturated in metals. What fast changes make them drop their load?", "back": "The fluid cools, the pressure falls and it boils, it mixes with cooler groundwater, or it reacts with a rock (limestone is the classic) that neutralises its acidity. Each pass leaves only a little metal, so you need an enormous volume of fluid through the same small volume of rock."},
 {"id": "L1-x-hypo", "lecture": 1, "kind": "q", "front": "Hypogene versus hypothermal: what does each word describe?", "back": "Hypogene is fluid direction (rising). Hypothermal is depth and temperature (deep, hot). An epithermal deposit is still hypogene."},
 {"id": "L1-x-strata", "lecture": 1, "kind": "q", "front": "Stratiform, stratabound and discordant ore: what's the difference?", "back": "Stratiform ore forms as a layer within the sediment. Stratabound ore is confined to one unit but may have replaced it later. Discordant ore cuts across layering."},
 {"id": "L1-x-200c", "lecture": 1, "kind": "q", "front": "What rule of thumb lets chalcopyrite act as a thermometer?", "back": "Chalcopyrite generally needs more than about 200 °C, so a sample full of it probably isn't epithermal. A vein of galena, sphalerite and fine banded quartz points to the shallow, cooler end."},
 {"id": "L1-x-ladder", "lecture": 1, "kind": "q", "front": "Which resource categories can become which reserve categories?", "back": "Indicated can become probable. Measured can become proved, or only probable if some modifying factor is still uncertain. Inferred never converts directly."},
 {"id": "L2-x-three", "lecture": 2, "kind": "q", "front": "Weathering, oxidation and alteration: pin each one down in a line.", "back": "Weathering is physical and chemical breakdown of rock near the surface, needing air, water and often plants. Oxidation (for ore) is sulphides and carbonates turning into oxides and hydroxides when oxygenated water reaches them. Alteration is a change in a rock's minerals at low pressure because fluids moved through it, anywhere those fluids go."},
 {"id": "L2-x-kinds", "lecture": 2, "kind": "q", "front": "Name four kinds of alteration, from the obvious to the invisible.", "back": "Mineralogical (new minerals you can see, such as phyllic or propylitic). Mineral structural (same mineral, changed crystal structure, such as illite crystallinity). Geochemical or cryptic (only the chemistry changes, such as barium around VHMS). Isotopic (shifted isotope ratios, important around Carlin-type gold)."},
 {"id": "L3-x-families", "lecture": 3, "kind": "q", "front": "What are the three families of ore texture?", "back": "Breccias (broken rock: how it broke, moved and was cemented tells you what broke it). Ore classifications by abundance and layering (massive, semi-massive, disseminated, banded). Veins (cracks that opened and filled, recording a sequence of events)."},
 {"id": "L4-x-why", "lecture": 4, "kind": "q", "front": "Give three questions ore microscopy answers for a mine.", "back": "Which mineral hosts the metal (free gold is cheap to recover; refractory gold locked in pyrite or arsenopyrite is not). How big the grains are (that sets how finely you must grind). Whether there are dirty minerals (arsenic and tellurium phases attract smelter penalties)."},
 {"id": "L4-x-yellows", "lecture": 4, "kind": "q", "front": "Pyrite, chalcopyrite and gold are all yellow in reflected light. How do you tell them apart?", "back": "Pyrite is pale yellow, hard and takes a perfect polish. Chalcopyrite is a stronger yellow and soft. Gold is yellow-orange and so bright it still glows with the lamp turned right down, and it polishes poorly."},
 {"id": "L4-x-marcasite", "lecture": 4, "kind": "q", "front": "Pyrite or marcasite?", "back": "Both are FeS₂. Marcasite is more bronze-yellow and strongly anisotropic in blue and yellow-green. It also breaks down in warm, humid air."},
 {"id": "L4-x-galena-apy", "lecture": 4, "kind": "q", "front": "Galena or arsenopyrite? Both are white.", "back": "Galena is soft, isotropic and covered in triangular cleavage pits. Arsenopyrite is hard, anisotropic and forms sharp rhomb-shaped crystals."},
 {"id": "L5-x-jobs", "lecture": 5, "kind": "q", "front": "What four jobs do structures do for ore?", "back": "Make space (faults, fractures and dilational jogs open gaps). Block flow (gouge, impermeable beds and dykes seal, so fluid ponds and drops its load). Soften rock (deformation plus fluid makes weak chlorite and talc rock). Move ore (a later fault slices a deposit and shifts part of it)."},
 {"id": "L5-x-deform", "lecture": 5, "kind": "q", "front": "What are the three basic ways to deform a block of rock?", "back": "Pull it apart (extension, normal faults), push it together (compression, reverse and thrust faults, folds), or slide it sideways (strike-slip). Each makes different space and moves fluid differently, so each makes different ore geometries."},
 {"id": "L5-x-geometry", "lecture": 5, "kind": "q", "front": "Same limestone, same fault. How does the ore body differ between extension and compression?", "back": "In extension the fault opens a pathway, meteoric water flows down and mixes with basinal fluid, and you get one large lens on the fault. In compression the fold and fault act as an aquitard: fluid is squeezed up beneath it and replaces favourable beds, giving a series of smaller lenses."},
 {"id": "L5-x-dyke", "lecture": 5, "kind": "q", "front": "Why are so many gold mines called \"Golden Dyke\" when the dyke itself carries little gold?", "back": "The dyke intruded before the gold event and then acted as a barrier (an aquitard) to the gold-bearing fluid, which dumped its gold right against the dyke contact. A structure doesn't have to be permeable to control ore."}
);
